#[derive(Debug, thiserror::Error, PartialEq, Eq)]
enum ConsensusInvariantError {
    #[error("SP_CONS_INV_BLOCK_HASH_MISSING: created block missing hash at height {height}")]
    MissingBlockHash { height: u64 },
    #[error(
        "SP_CONS_INV_POP_PAYLOAD_MISSING: PoP tx {tx_type} at index {tx_index} in block {height} has missing or malformed payload"
    )]
    MissingPopPayload {
        height: u64,
        tx_index: usize,
        tx_type: TransactionType,
    },
    #[error(
        "SP_CONS_INV_POP_STATE_TRANSITION_FAILED: PoP tx {tx_type} at index {tx_index} in block {height} failed state replay: {reason}"
    )]
    PopStateTransitionFailed {
        height: u64,
        tx_index: usize,
        tx_type: TransactionType,
        reason: String,
    },
    #[error(
        "SP_CONS_INV_REAL_REVEAL_NO_QUORUM: real contribution reveal {commit_id} in block {height} has {approvals} distinct valid approval(s), below chain quorum {required_quorum}"
    )]
    RealRevealWithoutOracleQuorum {
        height: u64,
        commit_id: String,
        approvals: usize,
        required_quorum: usize,
    },
}

