/// Default blocks to retain spent nonces/key images before pruning (#937, #953).
/// 100,000 blocks at ~10s/block = ~11.5 days of replay protection.
/// Must exceed maximum reorg depth (finality depth).
///
/// Override with `WRFCOIN_STATE_PRUNING_RETENTION_BLOCKS` for testnet soak tests (#1202).
pub const DEFAULT_STATE_PRUNING_RETENTION_BLOCKS: u64 = 100_000;

/// Lower bound for `WRFCOIN_STATE_PRUNING_RETENTION_BLOCKS` overrides (#1202).
///
/// Any retention depth below this floor would prune state still reachable by a
/// legal reorg, breaking replay protection and risking consensus divergence.
/// 128 blocks exceeds the workspace's maximum reorg depth of 100 (see
/// `tools/cli/WrfcoinCLI/src/consensus.rs` and
/// `consensus-engines/src/security/attack_prevention.rs`) with a small safety
/// margin. Override values below this floor are rejected and the default is
/// used instead.
pub const MIN_STATE_PRUNING_RETENTION_BLOCKS: u64 = 128;

/// Opt-in flag that must be explicitly set to permit a non-default
/// `WRFCOIN_STATE_PRUNING_RETENTION_BLOCKS` override (#1972).
///
/// The retention depth feeds the replay-protection sets that are hashed into the
/// consensus `state_root` (`spent_oracle_nonces`, `privacy_spent_key_images`,
/// `privacy_spent_nullifiers`, `privacy_commitments`, `privacy_disclosure_ids`,
/// `reward_claim_key_images` — see `State::state_root_material`). Two nodes that
/// prune those sets at different cutoffs (`current_height - retention`) emit
/// different bytes for the SAME ledger and silently diverge. Since there is no
/// peer-level handshake advertising retention (that would be a wire-format /
/// fleet-rollout change, intentionally out of scope here), the only safe local
/// guard is to FAIL CLOSED: refuse to honor an accidental override.
///
/// The #1202 soak-test escape hatch is preserved but made deliberate — an
/// operator who genuinely wants a non-default value on a single-operator network
/// must also set this flag to a truthy value (`1`/`true`/`yes`, case-insensitive).
pub const ALLOW_NONDEFAULT_RETENTION_ENV: &str = "WRFCOIN_ALLOW_NONDEFAULT_RETENTION";

/// Outcome of evaluating a raw `WRFCOIN_STATE_PRUNING_RETENTION_BLOCKS` value
/// together with the [`ALLOW_NONDEFAULT_RETENTION_ENV`] acknowledgment flag.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RetentionDecision {
    /// Use this retention depth (either the default or an explicitly-acked override).
    Use(u64),
    /// A non-default override was requested without the acknowledgment flag.
    /// Callers MUST fail closed (abort startup) rather than diverge from peers.
    UnacknowledgedOverride(u64),
}

/// Pure helper: resolve the retention depth from an optional raw env value.
///
/// Separated from [`state_pruning_retention_blocks`] so the validation logic
/// can be unit-tested without the process-wide `OnceLock` cache interfering.
///
/// This retains the historical clamp-to-default semantics (`#1202`) for unparseable
/// and below-floor inputs. For the consensus-safety (`#1972`) acknowledgment gate,
/// prefer [`decide_state_pruning_retention`], which distinguishes an *accidental*
/// non-default override (fail closed) from an *acknowledged* one.
///
/// Behavior:
/// - `None` or unparseable → [`DEFAULT_STATE_PRUNING_RETENTION_BLOCKS`]
/// - Parsed value `>=` [`MIN_STATE_PRUNING_RETENTION_BLOCKS`] → the parsed value
/// - Parsed value `<` [`MIN_STATE_PRUNING_RETENTION_BLOCKS`] →
///   [`DEFAULT_STATE_PRUNING_RETENTION_BLOCKS`] (rejected as unsafe)
pub fn resolve_state_pruning_retention_blocks(raw: Option<&str>) -> u64 {
    let Some(raw) = raw else {
        return DEFAULT_STATE_PRUNING_RETENTION_BLOCKS;
    };
    let Ok(parsed) = raw.parse::<u64>() else {
        log::warn!(
            "WRFCOIN_STATE_PRUNING_RETENTION_BLOCKS={raw:?} failed to parse as u64; \
             falling back to default ({DEFAULT_STATE_PRUNING_RETENTION_BLOCKS})."
        );
        return DEFAULT_STATE_PRUNING_RETENTION_BLOCKS;
    };
    if parsed < MIN_STATE_PRUNING_RETENTION_BLOCKS {
        log::error!(
            "WRFCOIN_STATE_PRUNING_RETENTION_BLOCKS={parsed} is below the safety floor \
             of {MIN_STATE_PRUNING_RETENTION_BLOCKS}; retention below this value would prune \
             state within reorg range and risk consensus divergence. Falling back to \
             default ({DEFAULT_STATE_PRUNING_RETENTION_BLOCKS})."
        );
        return DEFAULT_STATE_PRUNING_RETENTION_BLOCKS;
    }
    parsed
}

/// Interpret an env flag value as a boolean acknowledgment.
///
/// Truthy (case-insensitive): `1`, `true`, `yes`, `on`. Everything else (incl.
/// unset / empty) is false.
fn ack_flag_is_truthy(raw: Option<&str>) -> bool {
    matches!(
        raw.map(|s| s.trim().to_ascii_lowercase()).as_deref(),
        Some("1" | "true" | "yes" | "on")
    )
}

/// Pure decision helper for the #1972 consensus-safety gate.
///
/// Given the raw `WRFCOIN_STATE_PRUNING_RETENTION_BLOCKS` value and the raw
/// [`ALLOW_NONDEFAULT_RETENTION_ENV`] flag, decide whether the resolved retention
/// is safe to use:
/// - resolves to the default → always [`RetentionDecision::Use`]
/// - resolves to a non-default value WITH the ack flag set → [`RetentionDecision::Use`]
/// - resolves to a non-default value WITHOUT the ack flag →
///   [`RetentionDecision::UnacknowledgedOverride`] (caller must fail closed)
///
/// Pure / side-effect-free so it is unit-testable without touching the process
/// environment or the `OnceLock` cache.
pub fn decide_state_pruning_retention(
    raw_retention: Option<&str>,
    raw_ack: Option<&str>,
) -> RetentionDecision {
    let resolved = resolve_state_pruning_retention_blocks(raw_retention);
    if resolved == DEFAULT_STATE_PRUNING_RETENTION_BLOCKS {
        return RetentionDecision::Use(resolved);
    }
    if ack_flag_is_truthy(raw_ack) {
        RetentionDecision::Use(resolved)
    } else {
        RetentionDecision::UnacknowledgedOverride(resolved)
    }
}

/// Returns the active pruning retention depth, reading `WRFCOIN_STATE_PRUNING_RETENTION_BLOCKS`
/// once on first call. Falls back to [`DEFAULT_STATE_PRUNING_RETENTION_BLOCKS`] when the
/// variable is unset, unparseable, or below [`MIN_STATE_PRUNING_RETENTION_BLOCKS`] (#1202).
///
/// All nodes in a network **must** use the same value or state roots will diverge,
/// because the retention depth governs pruning of replay-protection sets that are
/// hashed into the consensus `state_root` (#1972). There is no peer-level handshake
/// advertising retention, so this function FAILS CLOSED (panics on first call) when a
/// *non-default* override is requested WITHOUT the explicit
/// [`ALLOW_NONDEFAULT_RETENTION_ENV`] acknowledgment flag, rather than letting an
/// accidental misconfiguration silently fork the node off the network.
///
/// # Panics
/// Panics on first call if `WRFCOIN_STATE_PRUNING_RETENTION_BLOCKS` resolves to a
/// non-default value and `WRFCOIN_ALLOW_NONDEFAULT_RETENTION` is not set to a truthy
/// value. This is a deliberate fail-closed startup guard (#1972).
pub fn state_pruning_retention_blocks() -> u64 {
    use std::sync::OnceLock;
    static VAL: OnceLock<u64> = OnceLock::new();
    *VAL.get_or_init(|| {
        let raw = std::env::var("WRFCOIN_STATE_PRUNING_RETENTION_BLOCKS").ok();
        let raw_ack = std::env::var(ALLOW_NONDEFAULT_RETENTION_ENV).ok();
        match decide_state_pruning_retention(raw.as_deref(), raw_ack.as_deref()) {
            RetentionDecision::Use(val) => {
                if val != DEFAULT_STATE_PRUNING_RETENTION_BLOCKS {
                    log::warn!(
                        "STATE_PRUNING_RETENTION_BLOCKS overridden to {val} \
                         (default {DEFAULT_STATE_PRUNING_RETENTION_BLOCKS}) with \
                         {ALLOW_NONDEFAULT_RETENTION_ENV} acknowledged. All nodes on this \
                         network MUST use the same value or consensus will break (#1972)."
                    );
                }
                val
            }
            RetentionDecision::UnacknowledgedOverride(val) => {
                panic!(
                    "FATAL (#1972): WRFCOIN_STATE_PRUNING_RETENTION_BLOCKS resolves to {val}, \
                     which differs from the network default \
                     {DEFAULT_STATE_PRUNING_RETENTION_BLOCKS}. The retention depth controls \
                     pruning of replay-protection sets hashed into the consensus state_root, \
                     so a node with a non-default value will SILENTLY FORK off any peer using \
                     the default. There is no peer-level handshake to negotiate this value. \
                     Refusing to start. If you are intentionally running an isolated \
                     single-operator network with a non-default retention, set \
                     {ALLOW_NONDEFAULT_RETENTION_ENV}=1 to acknowledge the divergence risk."
                );
            }
        }
    })
}
