    async fn assert_create_next_block_refusal(
        mut pop: ProofOfPublishing,
        chain: Blockchain,
        mempool: Mempool,
        reason_fragment: &str,
    ) -> String {
        let before = (chain.height, chain.tip, chain.state.state_root);
        let chain = Arc::new(RwLock::new(chain));
        let err = pop.create_next_block(
            chain.clone(), Arc::new(RwLock::new(mempool)), "wrf-refusal-miner",
        ).await.expect_err("configured refusal must fire");
        let reason = err.to_string();
        assert!(reason.contains(reason_fragment), "wrong refusal: {reason}");
        let after = chain.read().await;
        assert_eq!((after.height, after.tip, after.state.state_root), before);
        reason
    }

