    /// #3361 option B: a chain whose emission table funds a faucet slice must
    /// not be cut without a faucet recipient. PRODUCER-ONLY: the verifier must
    /// keep accepting the live chain 777's block 1, which has none.
    #[tokio::test]
    async fn create_next_block_refusal_genesis_faucet_address_3361() {
        use crate::crypto::chain_binding::GENESIS_FAUCET_ADDRESS_KEY;
        const CHILD: &str = "WRFCOIN_FAUCET_REQUIRED_CHILD_3361";
        // WRFCOIN_CHAIN_ID is process-global; run each chain id in its own child.
        let Ok(chain_id) = std::env::var(CHILD) else {
            for chain_id in ["777", "wrfcoin-main"] {
                let output = std::process::Command::new(std::env::current_exe().unwrap())
                    .args(["--exact", "consensus::proof_of_publishing::tests::create_next_block_refusal_genesis_faucet_address_3361"])
                    .env(CHILD, chain_id)
                    .env("WRFCOIN_CHAIN_ID", chain_id)
                    .output().unwrap();
                let stdout = String::from_utf8_lossy(&output.stdout);
                assert!(output.status.success(), "chain {chain_id}: {stdout}");
                assert!(stdout.contains("1 passed"), "chain {chain_id}: {stdout}");
            }
            return;
        };
        let sink = Address([0x61; 20]);
        if chain_id == "wrfcoin-main" {
            // Mainnet's faucet share is 0 bps: no recipient is required.
            let (mut pop, chain, mempool) = refusal_fixture();
            let block = pop.create_next_block(Arc::new(RwLock::new(chain)),
                Arc::new(RwLock::new(mempool)), "wrf-refusal-miner").await
                .expect("a 0-bps chain cuts without a faucet address");
            assert!(!block.metadata.contains_key(GENESIS_FAUCET_ADDRESS_KEY));
            return;
        }
        assert!(EmissionPartition::at_height(1, Some("777")).slice(EmissionRole::Faucet) > 0,
            "fixture is vacuous: chain 777 no longer funds a faucet slice");
        let (pop, chain, mempool) = refusal_fixture();
        assert_create_next_block_refusal(pop, chain, mempool,
            "SP_CONS_BLOCK_ONE_NO_FAUCET_ADDRESS:").await;
        let (mut pop, chain, mempool) = refusal_fixture();
        pop.set_genesis_faucet_address(Address([0; 20]));
        assert_create_next_block_refusal(pop, chain, mempool,
            "SP_CONS_BLOCK_ONE_NO_FAUCET_ADDRESS:").await;

        let (mut pop, chain, mempool) = refusal_fixture();
        pop.set_genesis_faucet_address(sink);
        let mut block = pop.create_next_block(Arc::new(RwLock::new(chain)),
            Arc::new(RwLock::new(mempool)), "wrf-refusal-miner").await
            .expect("a faucet chain with a recipient cuts");
        assert_eq!(block.metadata.get(GENESIS_FAUCET_ADDRESS_KEY), Some(&sink.to_string()));

        // Replay: the live 777 block 1 carries no faucet address. A verifier —
        // which never reads cut configuration — must still accept that shape.
        let (mut verifier, _, _) = refusal_fixture();
        let accepted = verifier.verify_block(&block, &FxHashSet::default(),
            DEFAULT_ORACLE_QUORUM.max(1), &[]).await.expect("verify_block must not error");
        assert!(accepted, "control: the stamped block 1 must verify");
        block.metadata.remove(GENESIS_FAUCET_ADDRESS_KEY);
        block.hash = Some(block.calculate_hash());
        let accepted = verifier.verify_block(&block, &FxHashSet::default(),
            DEFAULT_ORACLE_QUORUM.max(1), &[]).await.expect("verify_block must not error");
        assert!(accepted, "a 777 block 1 without faucet_address must still verify (live chain replay)");
    }

