    const FIXED_TEST_NOW_SECS: i64 = 1_700_000_000;

    fn fixed_test_now() -> chrono::DateTime<chrono::Utc> {
        chrono::DateTime::from_timestamp(FIXED_TEST_NOW_SECS, 0).unwrap()
    }

    #[derive(Clone, Debug)]
    struct FixedClock(chrono::DateTime<chrono::Utc>);

    impl Clock for FixedClock {
        fn now(&self) -> chrono::DateTime<chrono::Utc> {
            self.0
        }
    }

    fn fixed_clock() -> Arc<dyn Clock> {
        Arc::new(FixedClock(fixed_test_now()))
    }

    // #2145 deliberately covers allocation only. The contributor timing vector
    // across an emission-reduction boundary remains open on that issue.
    fn allocation_nominals(seed: u64, n: usize) -> Vec<u128> {
        let mut state = seed.wrapping_mul(6_364_136_223_846_793_005).wrapping_add(1);
        (0..n)
            .map(|_| {
                state = state
                    .wrapping_mul(6_364_136_223_846_793_005)
                    .wrapping_add(1_442_695_040_888_963_407);
                ((state >> 33) % 5_000_000 + 1) as u128
            })
            .collect()
    }

    #[test]
    fn reward_allocation_conserves_the_budget_2145() {
        for n in [1usize, 2, 3, 7, 64, 120] {
            for seed in 0..12u64 {
                let nominal = allocation_nominals(seed, n);
                let total: u128 = nominal.iter().sum();
                let budget = total / 2;
                let paid = allocate_rewards_within_budget(&nominal, budget, true);
                assert_eq!(paid.iter().sum::<u128>(), budget, "n={n} seed={seed}"); // secret-leak-ok: test-only numeric fixture seed
                assert!(paid.iter().zip(&nominal).all(|(got, want)| got <= want));
                assert_eq!(
                    allocate_rewards_within_budget(&nominal, total, false),
                    nominal,
                    "n={n} seed={seed}: unlimited path must pay nominal"
                ); // secret-leak-ok: test-only numeric fixture seed
            }
        }
    }

    #[test]
    fn reward_allocation_pays_a_non_participant_exactly_zero_2145() {
        for n in [1usize, 2, 3, 32] {
            let mut nominal = allocation_nominals(5, n);
            nominal.push(0);
            let total: u128 = nominal.iter().sum();
            assert_eq!(
                *allocate_rewards_within_budget(&nominal, total / 3, true)
                    .last()
                    .expect("non-empty"),
                0,
                "n={n}: rounding must not pay a zero-nominal last recipient"
            );
            let mut middle = allocation_nominals(6, n);
            middle.insert(n / 2, 0);
            let middle_total: u128 = middle.iter().sum();
            assert_eq!(
                allocate_rewards_within_budget(&middle, middle_total / 3, true)[n / 2],
                0,
                "n={n}: rounding must not pay a zero-nominal middle recipient"
            );
        }
    }

    #[test]
    fn reward_allocation_remainder_bias_is_bounded_2145() {
        for n in [2usize, 3, 8, 120] {
            for seed in 0..8u64 {
                let nominal = allocation_nominals(seed, n);
                let total: u128 = nominal.iter().sum();
                let budget = total / 3;
                let paid = allocate_rewards_within_budget(&nominal, budget, true);
                let last_nominal = *nominal.last().expect("non-empty");
                let fair = last_nominal.saturating_mul(budget) / total;
                let got = *paid.last().expect("non-empty");
                assert!(got.saturating_sub(fair) <= n as u128, "n={n} seed={seed}"); // secret-leak-ok: test-only numeric fixture seed
                assert!(got <= last_nominal, "n={n} seed={seed}"); // secret-leak-ok: test-only numeric fixture seed
            }
        }
    }

    #[test]
    fn reward_allocation_total_is_order_invariant_2145() {
        for n in [2usize, 3, 9, 64] {
            for seed in 0..8u64 {
                let nominal = allocation_nominals(seed, n);
                let total: u128 = nominal.iter().sum();
                let budget = total / 4;
                let base: u128 = allocate_rewards_within_budget(&nominal, budget, true)
                    .iter()
                    .sum();
                let mut reversed = nominal.clone();
                reversed.reverse();
                let mut rotated = nominal;
                rotated.rotate_left(n / 2);
                assert_eq!(
                    base,
                    allocate_rewards_within_budget(&reversed, budget, true)
                        .iter()
                        .sum::<u128>()
                );
                assert_eq!(
                    base,
                    allocate_rewards_within_budget(&rotated, budget, true)
                        .iter()
                        .sum::<u128>()
                );
            }
        }
    }

    #[test]
    fn reward_allocation_degenerate_cases_2145() {
        let nominal = allocation_nominals(9, 5);
        assert!(allocate_rewards_within_budget(&nominal, 0, true)
            .iter()
            .all(|reward| *reward == 0));
        let single = vec![1_000u128];
        assert_eq!(
            allocate_rewards_within_budget(&single, 10_000, true),
            vec![1_000]
        );
        assert_eq!(
            allocate_rewards_within_budget(&single, 400, true),
            vec![400]
        );
        assert!(allocate_rewards_within_budget(&[], 500, true).is_empty());
    }

    /// A producer whose clock is skewed must still emit a coinbase.
    ///
    /// RED CONTROL for the `is_coinbase()` early-return in
    /// `filter_by_submission_timing`. Remove that early-return and this fails:
    /// the coinbase is stamped `Utc::now()` at construction, the reference time
    /// is the clamped `producer_block_timestamp`, and when they differ by more
    /// than `submission_time_window` the `retain` deletes the coinbase.
    ///
    /// The failure is not "the block pays nothing". `verify_block` requires
    /// `transactions[0]` to be a Coinbase and requires exactly one, so peers
    /// reject the block outright — while `create_next_block` returns `Ok`,
    /// installs the staged state and advances the producer's own height. The
    /// producer forks itself off the network without erroring.
    #[tokio::test]
    async fn the_coinbase_survives_a_skewed_producer_clock() {
        use std::sync::Arc;
        use tokio::sync::RwLock;

        let mut pop = ProofOfPublishing::new(1, 60, 1_000_000, 16);
        // #2523: this dev chain has no oracle ceremony. It must SAY so — a
        // block 1 that declares nothing is refused, which is the point.
        pop.declare_no_genesis_oracles();

        // Anti-vacuity: the skew has to actually exceed the submission window,
        // or this test passes without exercising the filter at all.
        let skew = chrono::Utc::now()
            .timestamp()
            .abs_diff(fixed_test_now().timestamp());
        assert!(
            skew > pop.submission_time_window,
            "fixture is vacuous: producer clock skew {skew}s does not exceed the \
             submission window {}s, so the filter would keep the coinbase anyway",
            pop.submission_time_window
        );

        pop.set_clock(fixed_clock());
        let chain = Arc::new(RwLock::new(Blockchain::default()));
        let mempool = Arc::new(RwLock::new(Mempool::new(&Config::default())));

        let block = pop
            .create_next_block(
                chain.clone(),
                mempool.clone(),
                "0x3333333333333333333333333333333333333333",
            )
            .await
            .expect("block production must succeed under clock skew");

        let coinbase_count = block
            .transactions
            .iter()
            .filter(|tx| tx.tx_type == TransactionType::Coinbase)
            .count();
        assert_eq!(
            coinbase_count, 1,
            "the submission-timing filter deleted the coinbase under a {skew}s \
             clock skew — block carries {} transaction(s): {:?}",
            block.transactions.len(),
            block
                .transactions
                .iter()
                .map(|t| format!("{:?}", t.tx_type))
                .collect::<Vec<_>>()
        );
        assert!(
            block
                .transactions
                .first()
                .map(|tx| tx.is_coinbase())
                .unwrap_or(false),
            "verify_block requires transactions[0] to be the coinbase"
        );
        let amount = block.transactions[0]
            .outputs
            .first()
            .map(|o| o.amount)
            .unwrap_or(0);
        assert!(amount > 0, "a surviving coinbase must still pay something");

        // The block a skewed producer emits must be acceptable to its peers.
        // Without the fix this is unreachable — the assertions above fire first —
        // but it is the property that actually matters: a locally-Ok block that
        // every peer rejects is a self-inflicted fork, not a failed payment.
        let accepted = pop
            .verify_block(
                &block,
                &FxHashSet::default(),
                DEFAULT_ORACLE_QUORUM.max(1),
                &[],
            )
            .await
            .expect("verify_block must not error");
        assert!(
            accepted,
            "peers rejected a block produced under clock skew — the producer \
             would fork itself off the network"
        );
    }

    #[test]
    fn data_quality_slashing_activation_height_is_zero() {
        assert_eq!(DATA_QUALITY_SLASHING_ACTIVATION_HEIGHT, 0u64);
    }

    fn build_tx(tx_type: TransactionType, data: Option<&str>, tag: &str) -> Transaction {
        let mut tx = Transaction::new(
            vec![TransactionInput {
                txid: hash_string(&format!("input-{tag}")),
                vout: 0,
                signature: None,
                public_key: None,
                coinbase_data: None,
            }],
            vec![TransactionOutput {
                amount: 1,
                address: format!("wrf-{tag}"),
                script: "OP_TRUE".to_string(),
                nft_data: None,
            }],
        );
        tx.tx_type = tx_type;
        tx.data = data.map(|v| v.to_string());
        tx.set_id();
        tx
    }

    /// Build a Transfer tx with a valid ed25519 input signature (#1279 test helper).
    /// Any test that passes a Transfer through `verify_block` needs this, since
    /// `verify_block_transactions_fused` now enforces per-input signature checks
    /// on Transfer tx types at all heights `>= TX_SIGNATURE_VERIFICATION_ACTIVATION_HEIGHT`.
    fn build_signed_transfer_tx(tag: &str, seed: u64) -> Transaction {
        let mut rng = StdRng::seed_from_u64(seed);
        let private_key = PrivateKey::generate(&mut rng);
        let public_key = PublicKey::from_private_key(&private_key);

        let mut tx = Transaction::new(
            vec![TransactionInput {
                txid: hash_string(&format!("input-{tag}")),
                vout: 0,
                signature: None,
                public_key: Some(public_key.to_hex()),
                coinbase_data: None,
            }],
            vec![TransactionOutput {
                amount: 1,
                address: format!("wrf-{tag}"),
                script: "OP_TRUE".to_string(),
                nft_data: None,
            }],
        );
        tx.tx_type = TransactionType::Transfer;
        // signing_hash excludes signature, so we can sign it then populate signature.
        let sig = private_key.sign(tx.signing_hash().as_bytes());
        tx.inputs[0].signature = Some(sig.to_hex());
        tx.set_id();
        tx
    }

    /// Build a Stake/Unstake tx authorized by `account_key` (#1763): the staking
    /// account is the key's derived address and the payload carries a valid
    /// `account`-bound authorization, so it passes the `verify_block` stake gate.
    fn build_authorized_stake_tx(
        account_key: &PrivateKey,
        amount: u64,
        is_unstake: bool,
        nonce: u64,
    ) -> Transaction {
        let account = Address::from_public_key(&PublicKey::from_private_key(account_key));
        let mut payload = StakeAuthPayload {
            account: account.to_hex(),
            amount,
            auth_pubkey: None,
            auth_signature: None,
        };
        payload.sign_authorization(account_key, is_unstake, nonce);
        let mut tx = Transaction::new(
            vec![TransactionInput {
                txid: hash_string(&format!("stake-input-{}-{nonce}", account.to_hex())),
                vout: 0,
                signature: None,
                public_key: Some(account.to_hex()),
                coinbase_data: None,
            }],
            vec![TransactionOutput {
                amount: payload.amount,
                address: account.to_hex(),
                script: "OP_TRUE".to_string(),
                nft_data: None,
            }],
        );
        tx.tx_type = if is_unstake {
            TransactionType::Unstake
        } else {
            TransactionType::Stake
        };
        tx.sender_address = account;
        tx.nonce = nonce;
        tx.data = Some(serde_json::to_string(&payload).unwrap());
        tx.set_id();
        tx
    }

    /// Build a forged Stake/Unstake debiting `victim` (a hex address the
    /// attacker does NOT control). When `attacker_key` is supplied it signs the
    /// authorization with the attacker's own key (which does not derive to
    /// `victim`); otherwise the payload carries no authorization at all (#1763).
    fn build_forged_stake_tx(
        victim: &Address,
        amount: u64,
        is_unstake: bool,
        nonce: u64,
        attacker_key: Option<&PrivateKey>,
    ) -> Transaction {
        let mut payload = StakeAuthPayload {
            account: victim.to_hex(),
            amount,
            auth_pubkey: None,
            auth_signature: None,
        };
        if let Some(key) = attacker_key {
            payload.sign_authorization(key, is_unstake, nonce);
        }
        let mut tx = Transaction::new(
            vec![TransactionInput {
                txid: hash_string(&format!("forged-stake-input-{}-{nonce}", victim.to_hex())),
                vout: 0,
                signature: None,
                public_key: Some(victim.to_hex()),
                coinbase_data: None,
            }],
            vec![TransactionOutput {
                amount,
                address: victim.to_hex(),
                script: "OP_TRUE".to_string(),
                nft_data: None,
            }],
        );
        tx.tx_type = if is_unstake {
            TransactionType::Unstake
        } else {
            TransactionType::Stake
        };
        tx.sender_address = *victim;
        tx.nonce = nonce;
        tx.data = Some(serde_json::to_string(&payload).unwrap());
        tx.set_id();
        tx
    }

    fn build_commit_and_reveal(
        reveal_type: TransactionType,
        station_id: &str,
        contribution_type: &str,
        timestamp: i64,
        reveal_metrics: serde_json::Value,
        tag: &str,
    ) -> (Transaction, Transaction, String) {
        try_build_commit_and_reveal(
            reveal_type,
            station_id,
            contribution_type,
            timestamp,
            reveal_metrics,
            tag,
        )
        .expect("build_commit_and_reveal requires ContributionReveal or ForecastReveal")
    }

    fn try_build_commit_and_reveal(
        reveal_type: TransactionType,
        station_id: &str,
        contribution_type: &str,
        timestamp: i64,
        reveal_metrics: serde_json::Value,
        tag: &str,
    ) -> Result<(Transaction, Transaction, String), &'static str> {
        let nonce = format!("nonce-{tag}");
        let commit_id = Transaction::compute_commit_id(
            &reveal_metrics,
            &nonce,
            station_id,
            timestamp,
            contribution_type,
        );

        let commit_tx_type = match reveal_type {
            TransactionType::ContributionReveal => TransactionType::ContributionCommit,
            TransactionType::ForecastReveal => TransactionType::ForecastCommit,
            _ => return Err("invalid reveal type"),
        };

        let seed = tag.bytes().fold(99u64, |acc, b| acc.saturating_add(b as u64));
        let mut rng = StdRng::seed_from_u64(seed);
        let private_key = PrivateKey::generate(&mut rng);
        let mut commit_payload = CommitPayload {
            commit_id: commit_id.clone(),
            station_id: station_id.to_string(),
            timestamp,
            contribution_type: contribution_type.to_string(),
            auth_pubkey: None,
            auth_signature: None,
        };
        commit_payload.sign_authorization(&private_key);

        let reveal_payload = RevealPayload {
            commit_id: commit_id.clone(),
            station_id: station_id.to_string(),
            timestamp,
            contribution_type: contribution_type.to_string(),
            data: reveal_metrics,
            nonce,
            data_cid: None,
            data_hash: None,
            storage_provider: None,
            provenance: None,
            manifest: None,
            verification_receipt: None,
            compute_receipt: None,
                quality_tier: None,
        };

        let tx_timestamp = chrono::DateTime::from_timestamp(timestamp, 0).unwrap();
        let mut commit_tx = build_tx(commit_tx_type, None, &format!("commit-{tag}"));
        commit_tx.timestamp = tx_timestamp;
        commit_tx.data = Some(serde_json::to_string(&commit_payload).unwrap());
        commit_tx.set_id();

        let mut reveal_tx = build_tx(reveal_type, None, &format!("reveal-{tag}"));
        reveal_tx.timestamp = tx_timestamp;
        reveal_tx.data = Some(serde_json::to_string(&reveal_payload).unwrap());
        reveal_tx.set_id();

        Ok((commit_tx, reveal_tx, commit_id))
    }

    fn build_attestation_for_oracle(
        commit_id: &str,
        oracle_id: &str,
        approved: bool,
        timestamp: i64,
        signature: Option<String>,
        tag: &str,
    ) -> Transaction {
        let payload = OracleAttestationPayload {
            commit_id: commit_id.to_string(),
            oracle_id: oracle_id.to_string(),
            approved,
            signature,
            confidence: Some(1.0),
            timestamp,
            nonce: Some(format!("nonce-{tag}")),
        };
        let tx_timestamp = chrono::DateTime::from_timestamp(timestamp, 0).unwrap();
        let mut tx = build_tx(
            TransactionType::OracleAttestation,
            None,
            &format!("att-{tag}"),
        );
        tx.timestamp = tx_timestamp;
        tx.data = Some(serde_json::to_string(&payload).unwrap());
        tx.set_id();
        tx
    }

    fn build_attestation(commit_id: &str, approved: bool, tag: &str) -> Transaction {
        let seed = 1000
            + tag
                .bytes()
                .fold(0u64, |acc, b| acc.saturating_add(b as u64));
        let (private_key, oracle_id) = oracle_identity(seed);
        signed_attestation_tx(
            commit_id,
            &private_key,
            &oracle_id,
            approved,
            1_700_000_010,
            tag,
        )
    }

    fn addr(byte: u8) -> Address {
        Address([byte; 20])
    }

    /// The DECIDED reward for one commit in this block, read from the
    /// `reward_entries` metadata the producer serializes — the reward-sizing
    /// output BEFORE the per-user window cap (#2509) clamps the CREDIT
    /// (#2969 a2). Sizing tests (quality, trust, reputation, desert and
    /// receipt multipliers) assert ordering on this; the credit is asserted
    /// separately, because under a correctly denominated `emission_rate` the
    /// cap binds and clamped credits tie.
    fn decided_reward_for_commit(block: &Block, commit_id: &str) -> Balance {
        let raw = block
            .metadata
            .get("reward_entries")
            .expect("reward_entries metadata must be present on a reward block");
        let entries: Vec<ContributionRewardRecord> =
            serde_json::from_str(raw).expect("reward_entries must be valid JSON");
        entries
            .iter()
            .filter(|record| record.commit_id() == Some(commit_id))
            .map(|record| record.amount)
            .fold(Balance::new(0), |total, amount| total + amount)
    }

    /// For an address with exactly ONE decision so far: the decided reward,
    /// having asserted the (a2) credit rule
    /// `credited == min(decided, per_user_emission_cap(height))`.
    fn decided_reward_with_clamped_credit(
        chain: &Blockchain,
        block: &Block,
        commit_id: &str,
        address: &Address,
    ) -> Balance {
        let decided = decided_reward_for_commit(block, commit_id);
        let cap = EmissionForTests(&chain.state).per_user_emission_cap(block.height);
        let credited = chain
            .state
            .get_account(address)
            .map(|account| account.earned_balance_total)
            .unwrap_or(Balance::new(0));
        assert_eq!(
            credited,
            Balance::new(decided.into_inner().min(cap)),
            "the credit must be the decided reward clamped to the per-user window cap \
             (#2969 a2): decided={decided}, cap={cap}, credited={credited}"
        );
        decided
    }

    fn oracle_identity(seed: u64) -> (PrivateKey, String) {
        let mut rng = StdRng::seed_from_u64(seed);
        let private_key = PrivateKey::generate(&mut rng);
        let oracle_id = PublicKey::from_private_key(&private_key).to_string();
        (private_key, oracle_id)
    }

