    #[test]
    fn rich_ambient_payload_is_legacy_zero_below_and_positive_at_activation_2768() {
        let pop = ProofOfPublishing::new(1, 60, 0, 10);
        let (_, reveal, _) = build_commit_and_reveal(
            TransactionType::ContributionReveal,
            "station-rich-boundary",
            "contribution",
            1_700_500_000,
            rich_ambient_payload_2768(),
            "2768-boundary",
        );

        assert_eq!(
            pop.score_data_collection(
                &reveal,
                RICH_AMBIENT_REWARD_ACTIVATION_HEIGHT.saturating_sub(1),
            ),
            0,
            "historical mixed-type payloads must retain the strict legacy zero score"
        );
        assert_eq!(
            pop.score_data_collection(&reveal, RICH_AMBIENT_REWARD_ACTIVATION_HEIGHT),
            3 * SCORE_PRECISION,
            "an activated rich payload uses the existing 0.5 defaults for absent scoring fields"
        );
    }

    /// Owner ruling 2026-10-23: the gate is h3_000 (chain 888). Pinned by literal on
