    #[test]
    fn rich_ambient_two_oracle_quorum_mints_registered_owner_reward_2768() {
        let pop = ProofOfPublishing::new(1, 60, 0, 10);
        let mut chain = Blockchain::default();
        let (oracle_sk_a, oracle_id_a) = oracle_identity(2768_1);
        let (oracle_sk_b, oracle_id_b) = oracle_identity(2768_2);
        chain
            .apply_state_transition(StateTransition::SetOracleConfig {
                oracle_set: vec![oracle_id_a.clone(), oracle_id_b.clone()],
                oracle_quorum: 2,
            })
            .expect("two-oracle configuration must apply");

        let owner = addr(0x68);
        chain.state.create_account(owner, Balance::new(0));
        register_real_test_station(&mut chain, "PWS-EXAMPLE-AMBIENT-01", owner);
        let (commit, mut reveal, commit_id) = build_commit_and_reveal(
            TransactionType::ContributionReveal,
            "PWS-EXAMPLE-AMBIENT-01",
            "contribution",
            1_700_500_300,
            rich_ambient_payload_2768(),
            "2768-live-shape",
        );
        // The activated ownership rule must select the registry owner even if
        // the submitting transaction does not carry a payable sender/output.
        reveal.sender_address = Address([0; 20]);
        reveal.outputs.clear();
        reveal.set_id();
        let attestation_a = signed_attestation_tx(
            &commit_id,
            &oracle_sk_a,
            &oracle_id_a,
            true,
            1_700_500_301,
            "2768-live-a",
        );
        let attestation_b = signed_attestation_tx(
            &commit_id,
            &oracle_sk_b,
            &oracle_id_b,
            true,
            1_700_500_302,
            "2768-live-b",
        );
        let mut block = Block::new(
            3,
            chain.tip,
            vec![commit, reveal, attestation_a, attestation_b],
            1,
            RICH_AMBIENT_REWARD_ACTIVATION_HEIGHT,
        );

        pop.apply_contribution_rewards(&mut chain, &mut block)
            .expect("activated rich Ambient reward path must apply");

        let entries: Vec<ContributionRewardRecord> = serde_json::from_str(
            block
                .metadata
                .get("reward_entries")
                .expect("quorum-approved reveal must emit a reward decision"),
        )
        .expect("reward entries must decode");
        let reward = entries
            .iter()
            .find(|entry| entry.commit_id() == Some(commit_id.as_str()))
            .expect("the rich Ambient commit must have a reward entry");
        assert_eq!(reward.address, owner, "the registered owner must be paid");
        assert!(reward.amount.0 > 0, "the finalized reward must be nonzero");
        assert!(
            chain
                .state
                .finalized_contribution_rewards
                .contains(&commit_id),
            "the quorum-approved decision must finalize"
        );
        assert!(
            chain
                .state
                .get_account(&owner)
                .is_some_and(|account| account.balance.0 > 0),
            "the registered owner's balance must increase"
        );
    }

    #[test]
    fn rich_ambient_synthetic_and_unclassified_remain_finalized_zero_2768() {
        let pop = ProofOfPublishing::new(1, 60, 0, 20);
        let mut chain = Blockchain::default();
        let (oracle_sk_a, oracle_id_a) = oracle_identity(2768_3);
        let (oracle_sk_b, oracle_id_b) = oracle_identity(2768_4);
        chain
            .apply_state_transition(StateTransition::SetOracleConfig {
                oracle_set: vec![oracle_id_a.clone(), oracle_id_b.clone()],
                oracle_quorum: 2,
            })
            .expect("two-oracle configuration must apply");

        let synthetic_owner = addr(0x69);
        let unclassified_owner = addr(0x6a);
        for (station_id, owner, provenance) in [
            (
                "station-2768-synthetic",
                synthetic_owner,
                ContributionProvenanceClass::Synthetic,
            ),
            (
                "station-2768-unclassified",
                unclassified_owner,
                ContributionProvenanceClass::Unclassified,
            ),
        ] {
            chain.state.create_account(owner, Balance::new(0));
            register_test_station_with_provenance_2768(&mut chain, station_id, owner, provenance);
        }

        let mut transactions = Vec::new();
        let mut commit_ids = Vec::new();
        for (index, station_id) in ["station-2768-synthetic", "station-2768-unclassified"]
            .into_iter()
            .enumerate()
        {
            let timestamp = 1_700_500_400 + index as i64 * 10;
            let tag = format!("2768-ineligible-{index}");
            let (commit, reveal, commit_id) = build_commit_and_reveal(
                TransactionType::ContributionReveal,
                station_id,
                "contribution",
                timestamp,
                rich_ambient_payload_2768(),
                &tag,
            );
            transactions.extend([
                commit,
                reveal,
                signed_attestation_tx(
                    &commit_id,
                    &oracle_sk_a,
                    &oracle_id_a,
                    true,
                    timestamp + 1,
                    &format!("{tag}-a"),
                ),
                signed_attestation_tx(
                    &commit_id,
                    &oracle_sk_b,
                    &oracle_id_b,
                    true,
                    timestamp + 2,
                    &format!("{tag}-b"),
                ),
            ]);
            commit_ids.push(commit_id);
        }
        let mut block = Block::new(
            3,
            chain.tip,
            transactions,
            1,
            RICH_AMBIENT_REWARD_ACTIVATION_HEIGHT,
        );

        pop.apply_contribution_rewards(&mut chain, &mut block)
            .expect("ineligible rich contributions must finalize as zero decisions");

        let entries: Vec<ContributionRewardRecord> = serde_json::from_str(
            block
                .metadata
                .get("reward_entries")
                .expect("both ineligible commits must remain durably visible"),
        )
        .expect("reward entries must decode");
        assert_eq!(entries.len(), 2);
        assert!(
            entries.iter().all(|entry| entry.amount.0 == 0),
            "rich parsing must not bypass the provenance reward gate"
        );
        for commit_id in commit_ids {
            assert!(
                chain
                    .state
                    .finalized_contribution_rewards
                    .contains(&commit_id),
                "each ineligible decision must finalize exactly once"
            );
        }
        for owner in [synthetic_owner, unclassified_owner] {
            assert_eq!(
                chain
                    .state
                    .get_account(&owner)
                    .expect("fixture account exists")
                    .balance
                    .0,
                0,
                "ineligible provenance must never increase a balance"
            );
        }
    }

    /// Build a signing-key registry that registers each oracle id for the
    /// Oracle role (legacy identity-as-key mode), mirroring how production
    /// seeds `oracle_set` members into `chain.state.signing_keys` via
    /// `State::ensure_legacy_oracle_keys`. Apply-time attestation verification
    /// is fail-closed (#1756): it requires explicit registration, so tests that
    /// exercise the reward/quality path must register their oracles just like
    /// production does before `verify_block`.
    fn oracle_registry_for(oracle_ids: &[&str]) -> SigningKeyRegistry {
        let mut registry = SigningKeyRegistry::default();
        for id in oracle_ids {
            registry
                .ensure_legacy_identity_key(id, SigningRole::Oracle, 0)
                .expect("oracle registration should succeed");
        }
        registry
    }

    fn signed_attestation_tx(
        commit_id: &str,
        private_key: &PrivateKey,
        oracle_id: &str,
        approved: bool,
        timestamp: i64,
        tag: &str,
    ) -> Transaction {
        let payload = OracleAttestationPayload {
            commit_id: commit_id.to_string(),
            oracle_id: oracle_id.to_string(),
            approved,
            signature: None,
            confidence: Some(1.0),
            timestamp,
            nonce: Some(format!("nonce-{tag}")),
        };
        let message = payload.signing_message();
        let signature = private_key.sign(message.as_bytes()).to_string();
        build_attestation_for_oracle(
            commit_id,
            oracle_id,
            approved,
            timestamp,
            Some(signature),
            tag,
        )
    }

    /// Build a signed OracleAttestationPayload from an explicit signing key.
    fn signed_attestation_payload(
        commit_id: &str,
        signing_key: &PrivateKey,
        oracle_id: &str,
        timestamp: i64,
    ) -> OracleAttestationPayload {
        let mut payload = OracleAttestationPayload {
            commit_id: commit_id.to_string(),
            oracle_id: oracle_id.to_string(),
            approved: true,
            signature: None,
            confidence: Some(1.0),
            timestamp,
            nonce: Some(format!("nonce-{commit_id}")),
        };
        let signature = signing_key.sign(payload.signing_message().as_bytes()).to_string();
        payload.signature = Some(signature);
        payload
    }

    #[test]
    fn apply_time_attestation_accepts_registered_oracle() {
        // #1756: a registered oracle with a valid signature still verifies.
        let pop = ProofOfPublishing::new(1, 60, 0, 10);
        let (oracle_sk, oracle_id) = oracle_identity(17601);
        let registry = oracle_registry_for(&[&oracle_id]);
        let payload =
            signed_attestation_payload("commit-registered", &oracle_sk, &oracle_id, 1_700_000_000);

        assert!(
            pop.verify_attestation_signature_with_registry(&payload, Some(&registry)),
            "registered oracle with valid signature must verify"
        );
    }

    /// mobile#215 — the PRODUCER reconstruction path maps a gamification
    /// `Reward` tx to `ApplyGamificationReward` with the claim id, amount, and
    /// block height. Must stay byte-for-byte identical to the P2P applier path
    /// (`transition_extractor::extract_transitions`) — see that module's test.
    #[test]
    fn producer_maps_gamification_reward_to_apply_gamification_reward() {
        use crate::crypto::domain_signing::{
            GAMIFICATION_ENV_TEST_LOCK, GAMIFICATION_OPERATOR_PUBKEYS_ENV,
        };
        use crate::crypto::signature::{PrivateKey, PublicKey};
        use rand::{SeedableRng, rngs::StdRng};
        let _env = GAMIFICATION_ENV_TEST_LOCK.lock().unwrap_or_else(|e| e.into_inner());

        let pop = ProofOfPublishing::new(1, 60, 0, 10);
        let recipient = Address([9u8; 20]);
        let mut rng = StdRng::seed_from_u64(215_215);
        let operator = PrivateKey::generate(&mut rng);
        let op_pk = PublicKey::from_private_key(&operator).to_hex();
        let prev = std::env::var(GAMIFICATION_OPERATOR_PUBKEYS_ENV).ok();
        std::env::set_var(GAMIFICATION_OPERATOR_PUBKEYS_ENV, &op_pk);

        // Authorized payout maps to the gamification transition.
        let tx =
            Transaction::new_gamification_reward(&recipient.to_hex(), 500, "claim-x", &operator);
        let transition = ProofOfPublishing::launch_transition_for_transaction(&tx, 42, 0, 0)
            .expect("mapping ok")
            .expect("gamification reward yields a transition");

        // #2081 review — fail-closed applier: an unauthorized claim (operator key
        // not on the allowlist) must yield NO transition, never a silent mint.
        let attacker = PrivateKey::generate(&mut rng);
        let forged =
            Transaction::new_gamification_reward(&recipient.to_hex(), 500, "claim-y", &attacker);
        assert!(
            ProofOfPublishing::launch_transition_for_transaction(&forged, 42, 0, 0)
                .expect("mapping ok")
                .is_none(),
            "an unauthorized gamification claim must emit no transition"
        );

        match prev {
            Some(v) => std::env::set_var(GAMIFICATION_OPERATOR_PUBKEYS_ENV, v),
            None => std::env::remove_var(GAMIFICATION_OPERATOR_PUBKEYS_ENV),
        }

        match transition {
            StateTransition::ApplyGamificationReward {
                address,
                amount,
                claim_id,
                current_block,
            } => {
                assert_eq!(address, recipient);
                assert_eq!(amount, Balance::new(500));
                assert_eq!(claim_id, "claim-x");
                assert_eq!(current_block, 42);
            },
            other => panic!("expected ApplyGamificationReward, got {other:?}"),
        }
    }

    /// #2055 Option A: the PRODUCER reconstruction path maps an authorized
    /// oracle-registration tx to the compound `ApplyOracleRegistration`
    /// transition, and drops an unauthorized one (fail-closed). Must match the
    /// P2P extractor path (native-chain `transition_extractor` test) so
    /// producer == applier == replay.
    #[test]
    fn producer_maps_oracle_registration_to_apply_oracle_registration() {
        use crate::crypto::domain_signing::{
            ORACLE_GOVERNANCE_ENV_TEST_LOCK, ORACLE_GOVERNANCE_PUBKEYS_ENV,
        };
        use crate::crypto::signature::{PrivateKey, PublicKey};
        use rand::{SeedableRng, rngs::StdRng};
        let _env = ORACLE_GOVERNANCE_ENV_TEST_LOCK.lock().unwrap_or_else(|e| e.into_inner());

        let prev = std::env::var(ORACLE_GOVERNANCE_PUBKEYS_ENV).ok();
        let mut rng = StdRng::seed_from_u64(2055_1);
        let gov = PrivateKey::generate(&mut rng);
        std::env::set_var(ORACLE_GOVERNANCE_PUBKEYS_ENV, PublicKey::from_private_key(&gov).to_hex());

        let pop = ProofOfPublishing::new(1, 60, 0, 10);
        let identity = "0xoracle-1";
        let tx = Transaction::new_oracle_registration(
            vec![identity.to_string()],
            1,
            identity,
            &"aa".repeat(32),
            2,
            1_700_000_000,
            &gov,
        );
        let transition = ProofOfPublishing::launch_transition_for_transaction(&tx, 7, 0, 0)
            .expect("mapping ok")
            .expect("authorized oracle registration yields a transition");

        // Unauthorized (non-allowlisted signer) → no transition.
        let attacker = PrivateKey::generate(&mut rng);
        let forged = Transaction::new_oracle_registration(
            vec![identity.to_string()],
            1,
            identity,
            &"aa".repeat(32),
            2,
            1_700_000_000,
            &attacker,
        );
        assert!(
            ProofOfPublishing::launch_transition_for_transaction(&forged, 7, 0, 0)
                .expect("mapping ok")
                .is_none(),
            "an unauthorized oracle registration must emit no transition"
        );

        match prev {
            Some(v) => std::env::set_var(ORACLE_GOVERNANCE_PUBKEYS_ENV, v),
            None => std::env::remove_var(ORACLE_GOVERNANCE_PUBKEYS_ENV),
        }

        match transition {
            StateTransition::ApplyOracleRegistration {
                oracle_set,
                oracle_quorum,
                identity: id,
                public_key,
                epoch,
                activated_at,
            } => {
                assert_eq!(oracle_set, vec![identity.to_string()]);
                assert_eq!(oracle_quorum, 1);
                assert_eq!(id, identity);
                assert_eq!(public_key, "aa".repeat(32));
                assert_eq!(epoch, 2);
                assert_eq!(activated_at, 1_700_000_000);
            },
            other => panic!("expected ApplyOracleRegistration, got {other:?}"),
        }
    }

    /// #3277 S4: the producer never INCLUDES an extension this binary would
    /// not admit (unknown or unschedulable feature), evicts it, and orders the
    /// extensions it keeps by `sequence` within their slots. Neither step is in
    /// `classify_block_transaction`, so neither is a validity rule.
    #[test]
    fn producer_drops_unadmissible_and_orders_schedule_extensions_3277() {
        use crate::governance::schedule_extension::{
            FeatureScheduleExtension, ScheduleEntry, SignedFeatureScheduleExtension,
        };
        let ext = |sequence: u64, feature: &str| {
            Transaction::new_feature_schedule_extension(&SignedFeatureScheduleExtension {
                extension: FeatureScheduleExtension {
                    chain_id: "777".into(),
                    network_id: "testnet".into(),
                    genesis_hash: "ab".repeat(32),
                    sequence,
                    entries: vec![ScheduleEntry::new(feature, 5_000 + sequence)],
                    version_steps: Vec::new(),
                    min_protocol_version: 3,
                    release_commit: "c4d0a11".into(),
                },
                signatures: Vec::new(),
            })
        };
        let other = build_tx(TransactionType::Transfer, None, "3277-other");
        let unknown = ext(0, "a_b4_feature");
        let held = ext(0, "paymaster");
        let seq2 = ext(2, "passkey_p256_auth");
        let seq1 = ext(1, "verify_unit_pricing");
        let mut garbage = ext(0, "verify_unit_pricing");
        garbage.data = Some("nope".into());
        garbage.set_id();

        let mut txs = vec![
            seq2.clone(),
            unknown.clone(),
            other.clone(),
            held.clone(),
            seq1.clone(),
            garbage.clone(),
        ];
        let dropped = ProofOfPublishing::drop_unadmissible_schedule_extensions(&mut txs, None);
        assert_eq!(dropped, vec![unknown.id.unwrap(), held.id.unwrap()]);
        let ids: Vec<_> = txs.iter().map(|t| t.id).collect();
        // Kept in their slots, extensions re-ordered by sequence; the
        // unparsable one sorts last and is left to the validity screens.
        assert_eq!(ids, vec![seq1.id, other.id, seq2.id, garbage.id]);
    }

    /// #3361 F3 (producer half of the admission matrix): the producer
    /// includes a faucet-binding extension only when this node's block 1 is
    /// the one its `LEGACY_FAUCET_BINDINGS` row names (and the extension is
    /// bound to it); on any other chain, on a node with no block-1 hash, and
    /// for a suffix with no row, it drops and evicts it. Policy only: none of
    /// this is in `classify_block_transaction`.
    #[test]
    fn producer_includes_the_faucet_binding_only_on_its_rows_chain_3361() {
        use crate::crypto::chain_binding::LEGACY_FAUCET_BINDINGS;
        use crate::governance::schedule_extension::{
            FeatureScheduleExtension, ScheduleEntry, SignedFeatureScheduleExtension,
        };
        let row_chain = LEGACY_FAUCET_BINDINGS[0].genesis_hash.to_string();
        let other_chain = "cd".repeat(32);
        let ext = |genesis: &str, feature: &str| {
            Transaction::new_feature_schedule_extension(&SignedFeatureScheduleExtension {
                extension: FeatureScheduleExtension {
                    chain_id: "777".into(),
                    network_id: "testnet".into(),
                    genesis_hash: genesis.to_string(),
                    sequence: 0,
                    entries: vec![ScheduleEntry::new(feature, 25_000)],
                    version_steps: Vec::new(),
                    min_protocol_version: 3,
                    release_commit: "f3".into(),
                },
                signatures: Vec::new(),
            })
        };
        let bound = ext(&row_chain, "faucet_sink_binding");
        let no_row = ext(&row_chain, "faucet_sink_binding_r2");
        let foreign_genesis = ext(&other_chain, "faucet_sink_binding");

        // This node IS the row's chain: only the bound extension survives.
        let mut txs = vec![bound.clone(), no_row.clone(), foreign_genesis.clone()];
        let dropped =
            ProofOfPublishing::drop_unadmissible_schedule_extensions(&mut txs, Some(&row_chain));
        assert_eq!(dropped, vec![no_row.id.unwrap(), foreign_genesis.id.unwrap()]);
        assert_eq!(txs.iter().map(|t| t.id).collect::<Vec<_>>(), vec![bound.id]);

        // Any other chain, or no block-1 hash at all: dropped.
        for node in [Some(other_chain.as_str()), None] {
            let mut txs = vec![bound.clone()];
            let dropped = ProofOfPublishing::drop_unadmissible_schedule_extensions(&mut txs, node);
            assert_eq!(dropped, vec![bound.id.unwrap()], "{node:?}");
            assert!(txs.is_empty());
        }
    }

    /// #2055 Option A: `verify_block` rejects a block containing an unauthorized
    /// oracle-registration tx and accepts one with a valid governance signature.
    #[tokio::test]
    async fn verify_block_rejects_unauthorized_oracle_registration() {
        use crate::crypto::domain_signing::{
            ORACLE_GOVERNANCE_ENV_TEST_LOCK, ORACLE_GOVERNANCE_PUBKEYS_ENV,
        };
        use crate::crypto::signature::{PrivateKey, PublicKey};
        use rand::{SeedableRng, rngs::StdRng};
        let _env = ORACLE_GOVERNANCE_ENV_TEST_LOCK.lock().unwrap_or_else(|e| e.into_inner());

        let prev = std::env::var(ORACLE_GOVERNANCE_PUBKEYS_ENV).ok();
        let mut rng = StdRng::seed_from_u64(2055_2);
        let gov = PrivateKey::generate(&mut rng);
        let attacker = PrivateKey::generate(&mut rng);
        std::env::set_var(ORACLE_GOVERNANCE_PUBKEYS_ENV, PublicKey::from_private_key(&gov).to_hex());

        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        let identity = "0xoracle-1";
        let build = |signer: &PrivateKey| {
            let coinbase = Transaction::new_coinbase("miner", adjusted_block_reward(5), 5);
            let reg = Transaction::new_oracle_registration(
                vec![identity.to_string()],
                1,
                identity,
                &"aa".repeat(32),
                2,
                1_700_000_000,
                signer,
            );
            let txs = vec![coinbase, reg];
            let score = pop.calculate_block_publishing_score(&txs, 5);
            let mut block = Block::new(3, Hash::default(), txs, 1, 5);
            block
                .metadata
                .insert("publishing_score".to_string(), score.to_string());
            block
        };

        let forged_block = build(&attacker);
        let authorized_block = build(&gov);

        let forged_ok = pop
            .verify_block(&forged_block, &FxHashSet::default(), DEFAULT_ORACLE_QUORUM.max(1), &[])
            .await
            .unwrap();
        assert!(!forged_ok, "block with an unauthorized oracle registration must be rejected");

        let authorized_ok = pop
            .verify_block(&authorized_block, &FxHashSet::default(), DEFAULT_ORACLE_QUORUM.max(1), &[])
            .await
            .unwrap();
        assert!(authorized_ok, "block with an authorized oracle registration must be accepted");

        match prev {
            Some(v) => std::env::set_var(ORACLE_GOVERNANCE_PUBKEYS_ENV, v),
            None => std::env::remove_var(ORACLE_GOVERNANCE_PUBKEYS_ENV),
        }
    }

    /// #2081 review, blocker 2: a block whose gamification payouts (plus
    /// coinbase) exceed `MAX_BLOCK_EMISSION` must be rejected by `verify_block`
    /// BEFORE any payout is applied — the previous code only saturated the
    /// contribution-reward budget and applied the payouts anyway (checked only
    /// against MAX_SUPPLY). The payouts here are validly authorized, so the ONLY
    /// reason to reject the over-cap block is the emission cap.
    #[tokio::test]
    async fn verify_block_rejects_gamification_payouts_over_emission_cap() {
        use crate::crypto::domain_signing::{
            GAMIFICATION_ENV_TEST_LOCK, GAMIFICATION_OPERATOR_PUBKEYS_ENV,
        };
        use crate::crypto::signature::{PrivateKey, PublicKey};
        use rand::{SeedableRng, rngs::StdRng};
        let _env = GAMIFICATION_ENV_TEST_LOCK.lock().unwrap_or_else(|e| e.into_inner());

        let prev = std::env::var(GAMIFICATION_OPERATOR_PUBKEYS_ENV).ok();
        let mut rng = StdRng::seed_from_u64(215_216);
        let operator = PrivateKey::generate(&mut rng);
        std::env::set_var(
            GAMIFICATION_OPERATOR_PUBKEYS_ENV,
            PublicKey::from_private_key(&operator).to_hex(),
        );

        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        let recipient = Address([9u8; 20]).to_hex();
        let units = 100_000_000u64; // base units per WRF
        let build = |amount: u64, tag: &str| {
            let coinbase = Transaction::new_coinbase("miner", adjusted_block_reward(5), 5);
            let p1 = Transaction::new_gamification_reward(
                &recipient,
                amount,
                &format!("{tag}-1"),
                &operator,
            );
            let p2 = Transaction::new_gamification_reward(
                &recipient,
                amount,
                &format!("{tag}-2"),
                &operator,
            );
            let txs = vec![coinbase, p1, p2];
            let score = pop.calculate_block_publishing_score(&txs, 5);
            let mut block = Block::new(3, Hash::default(), txs, 1, 5);
            block
                .metadata
                .insert("publishing_score".to_string(), score.to_string());
            block
        };

        // Build both blocks first so the closure's immutable borrow of `pop`
        // ends before the `&mut self` verify_block calls.
        // #2492 rescale: the ceiling is 3_200 WRF and the height-5 coinbase is
        // 800 WRF, so the payouts must clear 1_200 WRF each to breach it.
        // Two 1_500 WRF payouts + 800 coinbase = 3_800 WRF > 3_200 → rejected.
        let over = build(1_500 * units, "over");
        // Control: two 10 WRF payouts = 20 WRF, well under the cap → accepted.
        let under = build(10 * units, "under");
        // (NLL ends the closure's borrow of `pop` after the last `build(...)`
        // call above, freeing `pop` for the `&mut self` verify_block calls.)

        let over_ok = pop
            .verify_block(&over, &FxHashSet::default(), DEFAULT_ORACLE_QUORUM.max(1), &[])
            .await
            .unwrap();
        assert!(
            !over_ok,
            "gamification payouts summing above MAX_BLOCK_EMISSION must be rejected"
        );

        let under_ok = pop
            .verify_block(&under, &FxHashSet::default(), DEFAULT_ORACLE_QUORUM.max(1), &[])
            .await
            .unwrap();
        assert!(
            under_ok,
            "authorized under-cap payouts must NOT be rejected by the emission gate"
        );

        match prev {
            Some(v) => std::env::set_var(GAMIFICATION_OPERATOR_PUBKEYS_ENV, v),
            None => std::env::remove_var(GAMIFICATION_OPERATOR_PUBKEYS_ENV),
        }
    }

    /// A plain (non-gamification) `Reward` tx still maps to `ApplyReward` — the
    /// gamification branch must not capture ordinary role/mining rewards.
    #[test]
    fn producer_maps_plain_reward_to_apply_reward() {
        let pop = ProofOfPublishing::new(1, 60, 0, 10);
        let recipient = Address([4u8; 20]);
        let output = TransactionOutput {
            amount: 100,
            address: recipient.to_hex(),
            script: "OP_TRUE".to_string(),
            nft_data: None,
        };
        let input = TransactionInput {
            txid: hash_string("plain-reward-input"),
            vout: 0,
            signature: None,
            public_key: None,
            coinbase_data: None,
        };
        let mut tx = Transaction::new(vec![input], vec![output]);
        tx.tx_type = TransactionType::Reward;
        tx.set_id();

        let transition = ProofOfPublishing::launch_transition_for_transaction(&tx, 7, 0, 0)
            .expect("mapping ok")
            .expect("reward yields a transition");
        assert!(
            matches!(transition, StateTransition::ApplyReward { .. }),
            "plain reward must map to ApplyReward, not the gamification variant"
        );
    }

    #[test]
    fn apply_time_attestation_rejects_unregistered_oracle() {
        // #1756: a cryptographically valid *self-signed* attestation whose
        // oracle_id is not explicitly registered must be rejected when a
        // registry is present — closing the legacy identity-as-pubkey self-cert
        // fallback at apply time.
        let pop = ProofOfPublishing::new(1, 60, 0, 10);
        let (attacker_sk, attacker_id) = oracle_identity(17602);
        // Registry knows a *different* oracle, not the attacker.
        let (_victim_sk, victim_id) = oracle_identity(17603);
        let registry = oracle_registry_for(&[&victim_id]);
        let payload = signed_attestation_payload(
            "commit-unregistered",
            &attacker_sk,
            &attacker_id,
            1_700_000_000,
        );

        assert!(
            !pop.verify_attestation_signature_with_registry(&payload, Some(&registry)),
            "unregistered/forged oracle_id must be rejected at apply time"
        );
    }

    #[test]
    fn apply_time_attestation_rejects_forged_sig_for_registered_oracle() {
        // #1756: a registered oracle_id with a signature produced by a different
        // key must be rejected (signature does not verify against the registered
        // operator key).
        let pop = ProofOfPublishing::new(1, 60, 0, 10);
        let (_victim_sk, victim_id) = oracle_identity(17604);
        let (attacker_sk, _attacker_id) = oracle_identity(17605);
        let registry = oracle_registry_for(&[&victim_id]);
        // Attacker signs while claiming the registered victim's oracle_id.
        let payload =
            signed_attestation_payload("commit-forged", &attacker_sk, &victim_id, 1_700_000_000);

        assert!(
            !pop.verify_attestation_signature_with_registry(&payload, Some(&registry)),
            "forged signature for a registered oracle must be rejected"
        );
    }

    #[test]
    fn apply_time_attestation_none_registry_preserves_self_cert() {
        // #1756: when no registry is threaded through (the publishing-score
        // path), the existing self-cert verification is preserved so block
        // scoring is unchanged for legitimate blocks. This documents the
        // intentional residual noted in the PR.
        let pop = ProofOfPublishing::new(1, 60, 0, 10);
        let (oracle_sk, oracle_id) = oracle_identity(17606);
        let payload =
            signed_attestation_payload("commit-none", &oracle_sk, &oracle_id, 1_700_000_000);

        assert!(
            pop.verify_attestation_signature_with_registry(&payload, None),
            "self-signed attestation still verifies on the registry-less path"
        );
    }

    #[test]
    fn publishing_score_requires_attested_contribution_reveal() {
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);

        let (contribution_commit, contribution_reveal, commit_id) = build_commit_and_reveal(
            TransactionType::ContributionReveal,
            "station-1",
            "contribution",
            1_700_000_000,
            serde_json::json!({"quality":1.0,"volume":1.0,"uniqueness":1.0}),
            "contrib",
        );
        let attestation_a = build_attestation(&commit_id, true, "contrib-a");
        let attestation_b = build_attestation(&commit_id, true, "contrib-b");

        let score = pop.calculate_block_publishing_score(
            &[
                contribution_commit,
                contribution_reveal,
                attestation_a,
                attestation_b,
            ],
            100,
        );

        // Contribution reveal score 6_000_000, two attestations at 2_000_000 each.
        // With minimum-based scoring (#818), block score = min(6M, 2M, 2M) = 2_000_000.
        assert_eq!(
            score, 2_000_000,
            "expected minimum publishing score of 2_000_000 (attestation floor), got {score}"
        );
    }

