    #[test]
    fn useful_work_policy_hooks_apply_task_assigner_and_scarcity() {
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        pop.set_task_assigner_policy(TaskAssignerPolicy {
            enabled: true,
            underserved_bonus_multiplier: 1.4,
            redundancy_penalty_multiplier: 0.5,
        })
        .expect("task assigner policy should be valid");
        pop.set_scarcity_policy(ScarcityPolicy {
            data_desert_multiplier: 1.2,
            proximity_multiplier: 1.1,
        })
        .expect("scarcity policy should be valid");

        let tx = build_tx(TransactionType::ForecastReveal, Some("{}"), "policy-hooks");
        let mut metrics = FxHashMap::default();
        metrics.insert("assignment_utility".to_string(), 0.9);
        metrics.insert("redundancy".to_string(), 0.2);
        metrics.insert("data_desert".to_string(), 0.5);
        metrics.insert("proximity_need".to_string(), 0.5);

        let adjusted = pop.apply_useful_work_policy_hooks(&tx, &metrics, 10_000_000);
        // 10.0 * 1.4 * (1.0 - 0.2 * 0.5) * (1.0 + 0.5 * (1.2 - 1.0)) * (1.0 + 0.5 * (1.1 - 1.0))
        // ≈ 16.17 → 16_170_000 in fixed-point (may differ slightly due to integer truncation)
        let expected = (10.0
            * 1.4
            * (1.0 - 0.2 * 0.5)
            * (1.0 + 0.5 * (1.2 - 1.0))
            * (1.0 + 0.5 * (1.1 - 1.0))
            * 1_000_000.0) as u64;
        let tolerance = 10_000u64; // allow for integer truncation
        assert!(
            (adjusted as i64 - expected as i64).unsigned_abs() < tolerance,
            "expected adjusted score ~{expected}, got {adjusted}"
        );
    }

    #[test]
