    // ── Integration: all three hooks combined ─────────────────────────────

    #[test]
    fn all_policy_hooks_compose_correctly() {
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        pop.set_task_assigner_policy(TaskAssignerPolicy {
            enabled: true,
            underserved_bonus_multiplier: 1.5,
            redundancy_penalty_multiplier: 0.3,
        })
        .expect("valid task assigner policy");
        pop.set_scarcity_policy(ScarcityPolicy {
            data_desert_multiplier: 2.0,
            proximity_multiplier: 1.5,
        })
        .expect("valid scarcity policy");
        pop.set_multidomain_reward_policy(MultidomainRewardPolicy {
            soil_enabled: true,
            ocean_enabled: false,
            hydrology_enabled: false,
            schema_version_min: 1,
            soil_weight: 1.5,
            ocean_weight: 1.0,
            hydrology_weight: 1.0,
        })
        .expect("valid multidomain policy");

        let tx = build_tx(
            TransactionType::ForecastReveal,
            Some(
                r#"{"domain":"soil","schema_version":1,"pipeline":{"backend39_ready":true,"storage_providers6_ready":true}}"#,
            ),
            "all-hooks",
        );
        let mut metrics = FxHashMap::default();
        metrics.insert("assignment_utility".to_string(), 0.9);
        metrics.insert("redundancy".to_string(), 0.2);
        metrics.insert("data_desert".to_string(), 0.5);
        metrics.insert("proximity_need".to_string(), 0.3);

        let adjusted = pop.apply_useful_work_policy_hooks(&tx, &metrics, 10_000_000);
        let expected = (10.0
            * 1.5                                    // underserved bonus (utility > 0.5)
            * (1.0 - 0.2 * 0.3)                     // redundancy penalty
            * (1.0 + 0.5 * (2.0 - 1.0))             // data desert
            * (1.0 + 0.3 * (1.5 - 1.0))             // proximity
            * 1.5                                    // soil multidomain weight
            * 1_000_000.0) as u64;
        let tolerance = 100_000u64; // allow for integer truncation across multiple steps
        assert!(
            (adjusted as i64 - expected as i64).unsigned_abs() < tolerance,
            "all hooks should compose multiplicatively, expected ~{expected}, got {adjusted}"
        );
    }

    /// #2700 — `MAX_BLOCK_SIZE` must actually bound what this node packs.
    ///
    /// Before this ceiling was wired, `assemble_block_transactions` concatenated
    /// every category with no byte limit, so producer-side block size was bounded
    /// by nothing. The transport limits do NOT cover this: gossip's
    /// `max_transmit_size` (1 MiB) and block-sync's `MAX_SYNC_MESSAGE_BYTES`
    /// (16 MiB) bound what we RECEIVE, not what we BUILD — a producer could
    /// assemble a block it could never propagate.
    ///
    /// Feeds the assembler more than the ceiling and asserts the ceiling is what
    /// stops it: the result must fit, the excess must be dropped, and the
    /// coinbase must survive at index 0 (several call sites index
    /// `transactions[0]` for the coinbase output).
    #[test]
    fn assemble_block_transactions_stops_packing_at_max_block_size() {
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        let coinbase = Transaction::new_coinbase("miner1", 50, 1);

        // ~1 MiB of payload each, so ~33 of them overshoot the 32 MiB ceiling.
        let payload = "x".repeat(1024 * 1024);
        let oversized: Vec<Transaction> = (0..40)
            .map(|i| {
                build_tx(
                    TransactionType::Regular,
                    Some(&payload),
                    &format!("oversize-{i}"),
                )
            })
            .collect();

        let offered: usize = oversized.iter().map(|t| t.size()).sum();
        assert!(
            offered > MAX_BLOCK_SIZE,
            "the test must actually offer more than the ceiling, offered {offered}"
        );

        let assembled = pop.assemble_block_transactions(
            coinbase,
            vec![],
            vec![],
            vec![],
            vec![],
            vec![],
            oversized.clone(),
            None,
        );

        let packed: usize = assembled.iter().map(|t| t.size()).sum();
        assert!(
            packed <= MAX_BLOCK_SIZE,
            "assembled block must fit the ceiling, got {packed} > {MAX_BLOCK_SIZE}"
        );
        assert!(
            assembled.len() < oversized.len() + 1,
            "the ceiling must actually drop excess; packed all {} offered",
            oversized.len()
        );
        assert_eq!(
            assembled[0].tx_type,
            TransactionType::Coinbase,
            "the coinbase must survive the budget and stay at index 0"
        );

        // The bound must not be so eager it starves a normal block: a small set
        // well under the ceiling must be packed in full. Without this the test
        // would still pass if the budget dropped everything.
        let small = vec![build_tx(TransactionType::Regular, None, "small-a")];
        let small_assembled = pop.assemble_block_transactions(
            Transaction::new_coinbase("miner1", 50, 1),
            vec![],
            vec![],
            vec![],
            vec![],
            vec![],
            small.clone(),
            None,
        );
        assert_eq!(
            small_assembled.len(),
            small.len() + 1,
            "a block well under the ceiling must be packed in full"
        );
    }

    #[test]
    fn assemble_block_transactions_prioritizes_commits_then_reveals_before_regular() {
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);

        let coinbase = Transaction::new_coinbase("miner1", 50, 1);
        let contribution_commit = build_tx(
            TransactionType::ContributionCommit,
            Some(
                r#"{"commit_id":"c1","station_id":"s1","timestamp":1,"contribution_type":"contribution"}"#,
            ),
            "priority-contrib-commit",
        );
        let forecast_commit = build_tx(
            TransactionType::ForecastCommit,
            Some(
                r#"{"commit_id":"f1","station_id":"s1","timestamp":1,"contribution_type":"forecast"}"#,
            ),
            "priority-forecast-commit",
        );
        let contribution_reveal = build_tx(
            TransactionType::ContributionReveal,
            Some(r#"{"quality":0.8,"volume":0.8,"uniqueness":0.8}"#),
            "priority-contrib",
        );
        let forecast_reveal = build_tx(
            TransactionType::ForecastReveal,
            Some(r#"{"accuracy":0.8,"complexity":0.8,"usefulness":0.8}"#),
            "priority-forecast",
        );
        let regular_a = build_tx(TransactionType::Regular, None, "regular-a");
        let regular_b = build_tx(TransactionType::Regular, None, "regular-b");

        let assembled = pop.assemble_block_transactions(
            coinbase,
            vec![contribution_commit.clone()],
            vec![forecast_commit.clone()],
            vec![contribution_reveal.clone()],
            vec![forecast_reveal.clone()],
            vec![],
            vec![regular_a.clone(), regular_b.clone()],
            None,
        );

        assert_eq!(assembled.len(), 7);
        assert_eq!(assembled[0].tx_type, TransactionType::Coinbase);
        assert_eq!(assembled[1].tx_type, TransactionType::ContributionCommit);
        assert_eq!(assembled[2].tx_type, TransactionType::ForecastCommit);
        assert_eq!(assembled[3].tx_type, TransactionType::ContributionReveal);
        assert_eq!(assembled[4].tx_type, TransactionType::ForecastReveal);
        assert_eq!(assembled[5].tx_type, TransactionType::Regular);
        assert_eq!(assembled[6].tx_type, TransactionType::Regular);

        assert_eq!(assembled[1].id, contribution_commit.id);
        assert_eq!(assembled[2].id, forecast_commit.id);
        assert_eq!(assembled[3].id, contribution_reveal.id);
        assert_eq!(assembled[4].id, forecast_reveal.id);
        assert_eq!(assembled[5].id, regular_a.id);
        assert_eq!(assembled[6].id, regular_b.id);
    }

    #[test]
    fn rewards_require_oracle_quorum() {
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        let mut chain = Blockchain::default();
        let (oracle_q1_sk, oracle_q1_id) = oracle_identity(201);
        let (_oracle_q2_sk, oracle_q2_id) = oracle_identity(202);
        chain
            .apply_state_transition(StateTransition::SetOracleConfig {
                oracle_set: vec![oracle_q1_id.clone(), oracle_q2_id],
                oracle_quorum: 2,
            })
            .unwrap();
        let recipient = addr(7);
        chain.state.create_account(recipient, Balance::new(0));

        let (commit, mut reveal, commit_id) = build_commit_and_reveal(
            TransactionType::ContributionReveal,
            "station-q",
            "contribution",
            1_700_000_010,
            serde_json::json!({"quality":1.0,"volume":1.0,"uniqueness":1.0}),
            "q",
        );
        reveal.sender_address = recipient;
        let att1 = signed_attestation_tx(
            &commit_id,
            &oracle_q1_sk,
            &oracle_q1_id,
            true,
            1_700_000_011,
            "q1",
        );

        let mut block = Block::new(3, chain.tip, vec![commit, reveal, att1], 1, 1);
        pop.apply_contribution_rewards(&mut chain, &mut block)
            .unwrap();

        let account = chain.state.get_account(&recipient).unwrap();
        assert_eq!(account.earned_balance_total, 0);
        assert_eq!(
            block
                .metadata
                .get("rewards_minted_count")
                .map(String::as_str),
            Some("0")
        );
        assert_eq!(
            block
                .metadata
                .get("oracle_reward_revealed_commit_count")
                .map(String::as_str),
            Some("1")
        );
        assert_eq!(
            block
                .metadata
                .get("oracle_reward_quorum_commit_count")
                .map(String::as_str),
            Some("0")
        );
        assert_eq!(
            block
                .metadata
                .get("oracle_reward_missing_quorum_count")
                .map(String::as_str),
            Some("1")
        );
        assert_eq!(
            block
                .metadata
                .get("oracle_reward_required_quorum")
                .map(String::as_str),
            Some("2")
        );
    }

    // -----------------------------------------------------------------------
    // #2743: rewards pay the REGISTERED owner from the binding activation
    // height. Note the template test below (`rewards_mint_when_quorum_met`)
    // registers the station owner AS the reveal sender — the exact
    // coincidence that made this defect invisible: whoever submits the reveal
    // names the payee, and the registration's owner_address was decorative.
    // -----------------------------------------------------------------------

    /// Everything valid, quorum met — but the reveal is submitted by (and
    /// pays) an address that is NOT the registered owner. From the activation
    /// height the registered owner must be paid and the submitter must not.
    #[test]
    fn rewards_pay_the_registered_owner_not_the_reveal_submitter_at_activation() {
        let h = STATION_OWNERSHIP_BINDING_ACTIVATION_HEIGHT;
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        let mut chain = Blockchain::default();
        let (oracle_sk, oracle_id) = oracle_identity(274_301);
        chain
            .apply_state_transition(StateTransition::SetOracleConfig {
                oracle_set: vec![oracle_id.clone()],
                oracle_quorum: 1,
            })
            .unwrap();
        let owner = addr(0xA1);
        let submitter = addr(0xBB);
        chain.state.create_account(owner, Balance::new(0));
        chain.state.create_account(submitter, Balance::new(0));
        register_real_test_station(&mut chain, "station-owner-bind", owner);

        let (commit, mut reveal, commit_id) = build_commit_and_reveal(
            TransactionType::ContributionReveal,
            "station-owner-bind",
            "contribution",
            1_700_000_020,
            serde_json::json!({"quality":1.0,"volume":1.0,"uniqueness":1.0}),
            "own",
        );
        reveal.sender_address = submitter;
        let att = signed_attestation_tx(
            &commit_id,
            &oracle_sk,
            &oracle_id,
            true,
            1_700_000_021,
            "own1",
        );

        let mut block = Block::new(3, chain.tip, vec![commit, reveal, att], 1, h);
        pop.apply_contribution_rewards(&mut chain, &mut block).unwrap();

        let owner_account = chain.state.get_account(&owner).unwrap();
        assert!(
            owner_account.earned_balance_total > Balance::new(0),
            "from height {h} the REGISTERED owner must receive the reward; \
             owner earned {:?}",
            owner_account.earned_balance_total
        );
        let submitter_account = chain.state.get_account(&submitter).unwrap();
        assert_eq!(
            submitter_account.earned_balance_total,
            Balance::new(0),
            "the reveal submitter must no longer be able to name itself payee"
        );
    }

    /// Below activation the legacy rule is pinned: the submitter/first-output
    /// address is paid. This branch is what keeps blocks 716/851 replaying
    /// byte-identically — weakening it is a chain split, not a cleanup.
    #[test]
    fn below_activation_the_reveal_submitter_is_still_paid_legacy_rule() {
        let h = STATION_OWNERSHIP_BINDING_ACTIVATION_HEIGHT;
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        let mut chain = Blockchain::default();
        let (oracle_sk, oracle_id) = oracle_identity(274_302);
        chain
            .apply_state_transition(StateTransition::SetOracleConfig {
                oracle_set: vec![oracle_id.clone()],
                oracle_quorum: 1,
            })
            .unwrap();
        let owner = addr(0xA2);
        let submitter = addr(0xBC);
        chain.state.create_account(owner, Balance::new(0));
        chain.state.create_account(submitter, Balance::new(0));
        register_real_test_station(&mut chain, "station-legacy-pay", owner);

        let (commit, mut reveal, commit_id) = build_commit_and_reveal(
            TransactionType::ContributionReveal,
            "station-legacy-pay",
            "contribution",
            1_700_000_030,
            serde_json::json!({"quality":1.0,"volume":1.0,"uniqueness":1.0}),
            "leg",
        );
        reveal.sender_address = submitter;
        let att = signed_attestation_tx(
            &commit_id,
            &oracle_sk,
            &oracle_id,
            true,
            1_700_000_031,
            "leg1",
        );

        let mut block = Block::new(3, chain.tip, vec![commit, reveal, att], 1, h - 1);
        pop.apply_contribution_rewards(&mut chain, &mut block).unwrap();

        assert!(
            chain.state.get_account(&submitter).unwrap().earned_balance_total
                > Balance::new(0),
            "below activation the legacy recipient rule must hold for replay"
        );
        assert_eq!(
            chain.state.get_account(&owner).unwrap().earned_balance_total,
            Balance::new(0)
        );
    }

    /// A Real station whose registered owner_address cannot parse as an
    /// on-chain address (possible only for grandfathered registrations) is
    /// fail-closed at activation: nobody is paid, and the refusal is visible
    /// in block metadata — never a payment to a guessed address.
    #[test]
    fn an_unparseable_registered_owner_fails_closed_at_activation() {
        let h = STATION_OWNERSHIP_BINDING_ACTIVATION_HEIGHT;
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        let mut chain = Blockchain::default();
        let (oracle_sk, oracle_id) = oracle_identity(274_303);
        chain
            .apply_state_transition(StateTransition::SetOracleConfig {
                oracle_set: vec![oracle_id.clone()],
                oracle_quorum: 1,
            })
            .unwrap();
        let submitter = addr(0xBD);
        chain.state.create_account(submitter, Balance::new(0));
        chain
            .state
            .register_weather_station(WeatherStation {
                station_id: "station-bad-owner".to_string(),
                owner_address: "not-an-address".to_string(),
                location: StationLocation {
                    latitude: 46.7867,
                    longitude: -92.1005,
                    elevation_meters: None,
                },
                hardware_model: "bad-owner-fixture".to_string(),
                calibration_date: None,
                is_active: true,
                reputation_score: 0,
                data_quality_tier: DataQualityTier::Unverified,
                provenance_class: ContributionProvenanceClass::Real,
                ring_public_key: None,
            })
            .unwrap();

        let (commit, mut reveal, commit_id) = build_commit_and_reveal(
            TransactionType::ContributionReveal,
            "station-bad-owner",
            "contribution",
            1_700_000_040,
            serde_json::json!({"quality":1.0,"volume":1.0,"uniqueness":1.0}),
            "bad",
        );
        reveal.sender_address = submitter;
        let att = signed_attestation_tx(
            &commit_id,
            &oracle_sk,
            &oracle_id,
            true,
            1_700_000_041,
            "bad1",
        );

        let mut block = Block::new(3, chain.tip, vec![commit, reveal, att], 1, h);
        pop.apply_contribution_rewards(&mut chain, &mut block).unwrap();

        assert_eq!(
            chain.state.get_account(&submitter).unwrap().earned_balance_total,
            Balance::new(0),
            "an unresolvable owner must never fall back to paying the submitter"
        );
        assert_eq!(
            block
                .metadata
                .get("rewards_owner_unresolvable_count")
                .map(String::as_str),
            Some("1"),
            "the refusal must be visible, not silent"
        );
    }

    /// #2969 (c) acceptance, owner-ruled 2026-09-03: `emission_rate` is
    /// retired as a budget knob. Two chains identical in every respect except
    /// the governance rate (1 base unit vs the 100 WRF seed) must DECIDE the
    /// same reward for the same max-quality decision, and that decision must
    /// be sized from the contribution reward allowance, not from the rate.
    ///
    /// RED on the pre-(c) producer, where the rate was passed as the
    /// downward clamp: the 1-base-unit chain decided exactly 1.
    #[test]
    fn emission_rate_no_longer_sizes_a_decision_2969c() {
        fn decide(emission_rate: u64) -> (u128, u64, Blockchain) {
            let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
            let mut chain = Blockchain::default();
            chain.state.governance.params.emission_rate = emission_rate;
            let (oracle_a_sk, oracle_a_id) = oracle_identity(231);
            let (oracle_b_sk, oracle_b_id) = oracle_identity(232);
            chain
                .apply_state_transition(StateTransition::SetOracleConfig {
                    oracle_set: vec![oracle_a_id.clone(), oracle_b_id.clone()],
                    oracle_quorum: 2,
                })
                .unwrap();
            let recipient = addr(9);
            chain.state.create_account(recipient, Balance::new(0));
            register_real_test_station(&mut chain, "station-c", recipient);
            let (commit, mut reveal, commit_id) = build_commit_and_reveal(
                TransactionType::ContributionReveal,
                "station-c",
                "contribution",
                1_700_000_030,
                serde_json::json!({"quality":1.0,"volume":1.0,"uniqueness":1.0}),
                "c",
            );
            reveal.sender_address = recipient;
            let att_a = signed_attestation_tx(
                &commit_id,
                &oracle_a_sk,
                &oracle_a_id,
                true,
                1_700_000_031,
                "ca",
            );
            let att_b = signed_attestation_tx(
                &commit_id,
                &oracle_b_sk,
                &oracle_b_id,
                true,
                1_700_000_032,
                "cb",
            );
            let mut block = Block::new(3, chain.tip, vec![commit, reveal, att_a, att_b], 1, 1);
            pop.apply_contribution_rewards(&mut chain, &mut block)
                .unwrap();
            let decided: u128 = block
                .metadata
                .get("rewards_minted_total")
                .expect("a quorum decision reports its decided total")
                .parse()
                .unwrap();
            (decided, block.height, chain)
        }

        let (decided_with_dust_rate, height, chain) = decide(1);
        let (decided_with_seed_rate, _, _) =
            decide(100 * crate::common::constants::WRF_UNITS_PER_COIN);

        assert_eq!(
            decided_with_dust_rate, decided_with_seed_rate,
            "the governance rate must not size a decision any more (#2969 c)"
        );
        assert!(
            decided_with_dust_rate > 1,
            "a 1-base-unit rate must not clamp the decision to 1 — it did on the \
             pre-(c) producer"
        );
        let allowance = EmissionForTests(&chain.state).contribution_reward_allowance(height);
        let base = EmissionForTests(&chain.state).contribution_decision_base(height);
        assert!(
            decided_with_dust_rate <= allowance,
            "a decision can never exceed the contribution reward allowance \
             ({decided_with_dust_rate} > {allowance})"
        );
        // Magnitude, not identity: this fixture carries no desert or
        // hyper-local bonus, and the trust and quality multipliers for a
        // freshly registered station compose to well under 1 (about 0.45), so
        // the decision sits inside the base's own order of magnitude. The
        // pre-(c) producer decided 1 here.
        assert!(
            decided_with_dust_rate <= base && decided_with_dust_rate * 4 > base,
            "a max-quality, fully attested, bonus-free decision is sized from the \
             decision base, not against a stale ceiling ({decided_with_dust_rate} \
             vs base {base}, allowance {allowance})"
        );
    }

    /// One quorum-approved max-quality decision for `recipient` at `height`,
    /// under an explicit governance `emission_rate` seed. Returns the block
    /// and the recipient's `earned_balance_total` delta across it.
    fn run_one_decision_under_rate(
        chain: &mut Blockchain,
        pop: &mut ProofOfPublishing,
        emission_rate: u64,
        recipient: Address,
        station: &str,
        tag: &str,
        height: u64,
    ) -> (Block, u128) {
        chain.state.governance.params.emission_rate = emission_rate;
        let (oracle_a_sk, oracle_a_id) = oracle_identity(3021_1);
        let (oracle_b_sk, oracle_b_id) = oracle_identity(3021_2);
        chain
            .apply_state_transition(StateTransition::SetOracleConfig {
                oracle_set: vec![oracle_a_id.clone(), oracle_b_id.clone()],
                oracle_quorum: 2,
            })
            .unwrap();
        if chain.state.get_account(&recipient).is_none() {
            chain.state.create_account(recipient, Balance::new(0));
        }
        if chain.state.station_registry.get(station).is_none() {
            register_real_test_station(chain, station, recipient);
        }
        let before = chain
            .state
            .get_account(&recipient)
            .map(|a| a.earned_balance_total.into_inner())
            .unwrap_or(0);
        let ts = 1_700_000_000 + height as i64 * 100;
        let (commit, mut reveal, commit_id) = build_commit_and_reveal(
            TransactionType::ContributionReveal,
            station,
            "contribution",
            ts,
            serde_json::json!({"quality":1.0,"volume":1.0,"uniqueness":1.0}),
            tag,
        );
        reveal.sender_address = recipient;
        let att1 = signed_attestation_tx(&commit_id, &oracle_a_sk, &oracle_a_id, true, ts + 1, &format!("{tag}-a"));
        let att2 = signed_attestation_tx(&commit_id, &oracle_b_sk, &oracle_b_id, true, ts + 2, &format!("{tag}-b"));
        let mut block = Block::new(3, chain.tip, vec![commit, reveal, att1, att2], 1, height);
        pop.apply_contribution_rewards(chain, &mut block).unwrap();
        let after = chain
            .state
            .get_account(&recipient)
            .map(|a| a.earned_balance_total.into_inner())
            .unwrap_or(0);
        (block, after - before)
    }

    fn metadata_u128_of(block: &Block, key: &str) -> u128 {
        block
            .metadata
            .get(key)
            .unwrap_or_else(|| panic!("{key} must be present"))
            .parse()
            .unwrap_or_else(|e| panic!("{key} must parse as u128: {e}"))
    }

    /// #3021: `rewards_minted_total` is what the state CREDITED this block;
    /// `rewards_decided_total` is what the producer DECIDED before the
    /// per-contributor window (#2509). The two were equal for the whole
    /// history of the key until #2969 (a2) let the window clamp a credit,
    /// which is why nobody noticed the key was reporting decisions. This pins
    /// the relationship from both sides so they cannot drift silently again:
    /// minted equals the balance delta, minted never exceeds decided, the gap
    /// is nonzero exactly when the ceiling binds, and a decision that credits
    /// nothing this block is decided-counted but not minted-counted.
    #[test]
    fn rewards_minted_total_is_the_credited_amount_and_decided_total_shows_the_gap_3021() {
        let mut chain = Blockchain::default();
        let cap = EmissionForTests(&chain.state).per_user_emission_cap(1);
        assert!(cap > 0);
        // Under #2969 (c) + the 2026-09-09 window-cap ruling (N = 2), one
        // max-quality decision never exceeds the window on its own: the cap
        // IS the whole per-decision allowance. The ceiling binds only once
        // the window is partly spent, so the binding vector is data-driven:
        // keep deciding for one address inside a single window until a block
        // decides more than it credits. `emission_rate` is passed for the
        // helper's signature only — since (c) it sizes nothing.
        let denominated = 100 * crate::common::constants::WRF_UNITS_PER_COIN;
        let window = emission_window_blocks(1);
        assert!(window >= 4, "the vector needs room inside one window");

        // (1) The ceiling binds: decided > minted, minted == credited.
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        let mut bound_at = None;
        for height in 1..window {
            let (block, credited) = run_one_decision_under_rate(
                &mut chain,
                &mut pop,
                denominated,
                addr(0x31),
                "station-3021-bind",
                &format!("bind-{height}"),
                height,
            );
            let decided = metadata_u128_of(&block, "rewards_decided_total");
            let minted = metadata_u128_of(&block, "rewards_minted_total");
            assert!(decided > 0, "the vector must decide a positive reward at height {height}");
            assert_eq!(minted, credited, "minted must be what the account was credited");
            assert!(minted <= decided, "minted can never exceed decided");
            assert_eq!(block.metadata.get("rewards_decided_count").map(String::as_str), Some("1"));
            // Before #2969 (a2) an over-window reward is refused whole (credited
            // 0, so not minted-counted); after it the remainder is credited (so
            // minted-counted). Either way the count follows the credit, never the
            // decision — which is the property under test.
            assert_eq!(
                block.metadata.get("rewards_minted_count").map(String::as_str),
                Some(if credited > 0 { "1" } else { "0" }),
                "minted_count follows the credit: credited={credited}"
            );
            if decided > minted {
                bound_at = Some((height, decided, minted));
                break;
            }
        }
        let (height, decided, minted) =
            bound_at.expect("the per-user ceiling must bind inside one window");
        assert!(
            decided > minted,
            "with the per-user ceiling binding the gap must be visible at height {height}: \
             decided={decided} minted={minted}"
        );

        // (2) The ceiling does not bind: the gap is zero.
        let mut chain = Blockchain::default();
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        let under_cap = (cap / 2) as u64;
        let (block, credited) = run_one_decision_under_rate(
            &mut chain, &mut pop, under_cap, addr(0x32), "station-3021-free", "free", 1,
        );
        let decided = metadata_u128_of(&block, "rewards_decided_total");
        let minted = metadata_u128_of(&block, "rewards_minted_total");
        assert!(decided > 0);
        assert_eq!(minted, credited);
        assert_eq!(minted, decided, "no ceiling binding ⇒ no gap");

        // (3) Exhaust the window for this address. The decided reward is the
        // multipliers this test does not assume times the decision base, so
        // the fill is data-driven: keep deciding inside the window (six blocks
        // at the genesis tier) until the per-user window ledger is spent to
        // the last unit. Every block on the way must satisfy the relationship.
        // Before #2969 (a2) the first non-fitting decision is refused whole
        // (credited 0); after (a2) its remainder is credited and the ledger
        // reads exactly `cap`. Under the N = 2 ruling one bonus-free decision
        // is well under half the cap, so with one decision per block the window
        // has no room for a further zero-credit block — exhaustion is proven by
        // the ledger (`emission_window_spent == cap`), not by an extra block.
        let window = emission_window_blocks(1);
        assert!(window >= 4, "the vector needs room inside one window");
        let spent_of = |chain: &Blockchain| {
            chain
                .state
                .emission_window_spent
                .get(&addr(0x32))
                .copied()
                .unwrap_or(0)
        };
        let mut reached_exhaustion = false;
        for height in 2..window {
            let (block, credited) = run_one_decision_under_rate(
                &mut chain,
                &mut pop,
                cap as u64,
                addr(0x32),
                "station-3021-free",
                &format!("fill-{height}"),
                height,
            );
            let decided = metadata_u128_of(&block, "rewards_decided_total");
            let minted = metadata_u128_of(&block, "rewards_minted_total");
            assert!(decided > 0, "every fill decision decides a positive reward");
            assert_eq!(minted, credited, "minted must equal the credit at height {height}");
            assert!(minted <= decided);
            assert_eq!(
                block.metadata.get("rewards_decided_count").map(String::as_str),
                Some("1")
            );
            assert_eq!(
                block.metadata.get("rewards_minted_count").map(String::as_str),
                Some(if credited > 0 { "1" } else { "0" })
            );
            let spent = spent_of(&chain);
            assert!(spent <= cap, "the ledger can never exceed the cap ({spent} > {cap})");
            if credited == 0 || spent == cap {
                assert!(
                    decided >= minted,
                    "the exhausting block must never mint more than it decided"
                );
                reached_exhaustion = true;
                break;
            }
        }
        assert!(
            reached_exhaustion,
            "the window must be exhausted inside one window, or the vector proves nothing"
        );
        assert_eq!(spent_of(&chain), cap, "exhaustion means the ledger reads exactly the cap");

        // (4) The next window starts clean: the first decision after the roll is
        // credited in full again and the ledger restarts from that credit.
        let (block, credited) = run_one_decision_under_rate(
            &mut chain, &mut pop, cap as u64, addr(0x32), "station-3021-free", "next-window", window,
        );
        let decided = metadata_u128_of(&block, "rewards_decided_total");
        let minted = metadata_u128_of(&block, "rewards_minted_total");
        assert!(credited > 0, "a fresh window must credit again");
        assert_eq!(minted, credited);
        assert_eq!(minted, decided, "no ceiling binds in a fresh window");
        assert_eq!(spent_of(&chain), credited, "the ledger restarts from the fresh credit");
    }

    #[test]
    fn rewards_mint_when_quorum_met() {
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        let mut chain = Blockchain::default();
        let (oracle_r1_sk, oracle_r1_id) = oracle_identity(211);
        let (oracle_r2_sk, oracle_r2_id) = oracle_identity(212);
        chain
            .apply_state_transition(StateTransition::SetOracleConfig {
                oracle_set: vec![oracle_r1_id.clone(), oracle_r2_id.clone()],
                oracle_quorum: 2,
            })
            .unwrap();
        let recipient = addr(8);
        chain.state.create_account(recipient, Balance::new(0));
        register_real_test_station(&mut chain, "station-r", recipient);

        let (commit, mut reveal, commit_id) = build_commit_and_reveal(
            TransactionType::ContributionReveal,
            "station-r",
            "contribution",
            1_700_000_020,
            serde_json::json!({"quality":1.0,"volume":1.0,"uniqueness":1.0}),
            "r",
        );
        reveal.sender_address = recipient;
        let att1 = signed_attestation_tx(
            &commit_id,
            &oracle_r1_sk,
            &oracle_r1_id,
            true,
            1_700_000_021,
            "r1",
        );
        let att2 = signed_attestation_tx(
            &commit_id,
            &oracle_r2_sk,
            &oracle_r2_id,
            true,
            1_700_000_022,
            "r2",
        );

        let mut block = Block::new(3, chain.tip, vec![commit, reveal, att1, att2], 1, 1);
        pop.apply_contribution_rewards(&mut chain, &mut block)
            .unwrap();

        let account = chain.state.get_account(&recipient).unwrap();
        assert!(account.earned_balance_total > Balance::new(0));
        assert_eq!(
            block
                .metadata
                .get("rewards_minted_count")
                .map(String::as_str),
            Some("1")
        );
        assert_eq!(
            block
                .metadata
                .get("oracle_reward_revealed_commit_count")
                .map(String::as_str),
            Some("1")
        );
        assert_eq!(
            block
                .metadata
                .get("oracle_reward_quorum_commit_count")
                .map(String::as_str),
            Some("1")
        );
        assert_eq!(
            block
                .metadata
                .get("oracle_reward_missing_quorum_count")
                .map(String::as_str),
            Some("0")
        );
        assert_eq!(
            block
                .metadata
                .get("oracle_reward_required_quorum")
                .map(String::as_str),
            Some("2")
        );
    }

