    #[test]
    fn rewards_reject_attestations_with_invalid_signature() {
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        let mut chain = Blockchain::default();
        let (_oracle_bad_sk, oracle_bad_id) = oracle_identity(231);
        let (_oracle_good_sk, oracle_good_id) = oracle_identity(232);
        chain
            .apply_state_transition(StateTransition::SetOracleConfig {
                oracle_set: vec![oracle_bad_id.clone(), oracle_good_id],
                oracle_quorum: 1,
            })
            .unwrap();
        let recipient = addr(10);
        chain.state.create_account(recipient, Balance::new(0));

        let (commit, mut reveal, commit_id) = build_commit_and_reveal(
            TransactionType::ContributionReveal,
            "station-bad-sig",
            "contribution",
            1_700_000_040,
            serde_json::json!({"quality":1.0,"volume":1.0,"uniqueness":1.0}),
            "bad-sig",
        );
        reveal.sender_address = recipient;

        let invalid_payload = OracleAttestationPayload {
            commit_id,
            oracle_id: oracle_bad_id,
            approved: true,
            signature: Some("definitely-not-a-valid-signature".to_string()),
            confidence: Some(1.0),
            timestamp: 1_700_000_041,
            nonce: None,
        };
        let mut bad_att = build_tx(TransactionType::OracleAttestation, None, "bad-sig-att");
        bad_att.data = Some(serde_json::to_string(&invalid_payload).unwrap());
        bad_att.set_id();

        let mut block = Block::new(3, chain.tip, vec![commit, reveal, bad_att], 1, 1);
        let err = pop
            .apply_contribution_rewards(&mut chain, &mut block)
            .expect_err("invalid attestation signatures must fail strict PoP replay");
        let typed = err
            .downcast_ref::<ConsensusInvariantError>()
            .expect("reward pass should preserve typed invariant");
        assert!(matches!(
            typed,
            ConsensusInvariantError::PopStateTransitionFailed {
                tx_index: 2,
                tx_type: TransactionType::OracleAttestation,
                ..
            }
        ));
        assert!(
            err.to_string()
                .contains("SP_CONS_INV_POP_STATE_TRANSITION_FAILED")
        );
        let account = chain.state.get_account(&recipient).unwrap();
        assert_eq!(account.earned_balance_total, 0);
    }

    #[test]
    fn publishing_score_quality_tiers_high_borderline_low() {
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);

        let (high_commit, high_reveal, high_commit_id) = build_commit_and_reveal(
            TransactionType::ContributionReveal,
            "station-quality-high",
            "contribution",
            1_700_100_000,
            serde_json::json!({"quality":1.0,"volume":1.0,"uniqueness":1.0}),
            "quality-high",
        );
        let high_att_a = build_attestation(&high_commit_id, true, "quality-high-a");
        let high_att_b = build_attestation(&high_commit_id, true, "quality-high-b");
        let high_score = pop.calculate_block_publishing_score(
            &[high_commit, high_reveal, high_att_a, high_att_b],
            100,
        );

        let (border_commit, border_reveal, border_commit_id) = build_commit_and_reveal(
            TransactionType::ContributionReveal,
            "station-quality-borderline",
            "contribution",
            1_700_100_010,
            serde_json::json!({"quality":0.75,"volume":1.0,"uniqueness":1.0}),
            "quality-borderline",
        );
        let border_att_a = build_attestation(&border_commit_id, true, "quality-borderline-a");
        let border_att_b = build_attestation(&border_commit_id, true, "quality-borderline-b");
        let borderline_score = pop.calculate_block_publishing_score(
            &[border_commit, border_reveal, border_att_a, border_att_b],
            100,
        );

        let (low_commit, low_reveal, low_commit_id) = build_commit_and_reveal(
            TransactionType::ContributionReveal,
            "station-quality-low",
            "contribution",
            1_700_100_020,
            serde_json::json!({"quality":0.20,"volume":1.0,"uniqueness":1.0}),
            "quality-low",
        );
        let low_att_a = build_attestation(&low_commit_id, true, "quality-low-a");
        let low_att_b = build_attestation(&low_commit_id, true, "quality-low-b");
        let low_score = pop
            .calculate_block_publishing_score(&[low_commit, low_reveal, low_att_a, low_att_b], 100);

        // With minimum-based scoring (#818), all three block scores are capped by the
        // attestation floor (2_000_000) because each block's reveal score exceeds 2M.
        // The quality tiers still affect individual reveal scores, but the block-level
        // minimum is dominated by the attestation scores.
        assert_eq!(
            high_score, borderline_score,
            "all tiers should equal attestation floor under minimum scoring, got {high_score} vs {borderline_score}"
        );
        assert_eq!(
            borderline_score, low_score,
            "all tiers should equal attestation floor under minimum scoring, got {borderline_score} vs {low_score}"
        );
        assert_eq!(
            low_score, 2_000_000,
            "block score should equal attestation floor (2M), got {low_score}"
        );
    }

    /// Regression for #1760: the block publishing-score path must gate
    /// attestation inputs by the authorized oracle set, so a producer cannot
    /// forge attestations (mint a keypair, set `oracle_id = own_pubkey`, sign)
    /// to inflate its block's publishing score.
    ///
    /// Strategy: score the SAME block under three oracle-set configurations and
    /// assert the gate excludes forged attesters while leaving legitimate blocks
    /// byte-identical.
    #[test]
    fn publishing_score_gate_excludes_forged_attestation_oracle() {
        let (commit, reveal, commit_id) = build_commit_and_reveal(
            TransactionType::ContributionReveal,
            "station-forge-1760",
            "contribution",
            1_700_500_000,
            serde_json::json!({"quality":1.0,"volume":1.0,"uniqueness":1.0}),
            "forge-1760",
        );

        // Two attesting oracles with VALID self-certifying signatures. Quorum is
        // DEFAULT_ORACLE_QUORUM (2), so both are needed for the commit to attest.
        let (f1_sk, f1_id) = oracle_identity(7_760_001);
        let (f2_sk, f2_id) = oracle_identity(7_760_002);
        let att_f1 =
            signed_attestation_tx(&commit_id, &f1_sk, &f1_id, true, 1_700_500_001, "forge-1760-f1");
        let att_f2 =
            signed_attestation_tx(&commit_id, &f2_sk, &f2_id, true, 1_700_500_001, "forge-1760-f2");

        let coinbase =
            Transaction::new_coinbase("miner", adjusted_block_reward(100), 100);
        let txs = vec![coinbase, commit, reveal, att_f1, att_f2];

        // A) Empty authorized set (genesis / no oracles registered): the membership
        //    filter is skipped, so the self-signed attestations still reach quorum
        //    and the reveal is scored. This is the pre-fix behaviour, preserved only
        //    while no oracle set exists — matching the ~40 existing score tests.
        let mut pop_empty = ProofOfPublishing::new(1, 60, 0, 10);
        let score_empty = pop_empty.calculate_block_publishing_score(&txs, 100);
        assert!(
            score_empty > 0,
            "empty oracle set must preserve prior scoring behaviour (>0)"
        );

        // B) A DIFFERENT oracle set is authorized. From the chain's perspective the
        //    block's F1/F2 attestations are FORGED (their oracle_ids aren't authorized)
        //    -> excluded -> commit never reaches quorum -> reveal scores 0 -> the
        //    forged attestations cannot inflate the block score.
        let (_, g1_id) = oracle_identity(7_760_003);
        let (_, g2_id) = oracle_identity(7_760_004);
        let mut authorized_other = FxHashSet::default();
        authorized_other.insert(g1_id);
        authorized_other.insert(g2_id);
        let mut pop_other = ProofOfPublishing::new(1, 60, 0, 10);
        pop_other.set_authorized_oracles(authorized_other);
        let score_forged = pop_other.calculate_block_publishing_score(&txs, 100);
        assert_eq!(
            score_forged, 0,
            "forged (unauthorized) oracle attestations must NOT inflate the publishing score, got {score_forged}"
        );

        // C) Positive control: the attesting oracles F1/F2 ARE the authorized set
        //    -> gate passes -> score is identical to the legacy no-oracle-set path.
        //    Proves legitimate blocks are unchanged by the gate.
        let mut authorized_real = FxHashSet::default();
        authorized_real.insert(f1_id);
        authorized_real.insert(f2_id);
        let mut pop_auth = ProofOfPublishing::new(1, 60, 0, 10);
        pop_auth.set_authorized_oracles(authorized_real);
        let score_auth = pop_auth.calculate_block_publishing_score(&txs, 100);
        assert_eq!(
            score_auth, score_empty,
            "authorized-oracle attestations must score identically to the legacy \
             no-oracle-set path (legit blocks unchanged): {score_auth} vs {score_empty}"
        );
    }

