    #[test]
    fn repeated_low_quality_triggers_slashing_after_policy_streak() {
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        let mut chain = Blockchain::default();
        chain
            .state
            .governance
            .params
            .data_quality_policy
            .low_quality_slash_streak = 2;
        chain
            .state
            .governance
            .params
            .data_quality_policy
            .low_quality_slash_amount = 5;

        let (oracle_a_sk, oracle_a_id) = oracle_identity(361);
        let (oracle_b_sk, oracle_b_id) = oracle_identity(362);
        chain
            .apply_state_transition(StateTransition::SetOracleConfig {
                oracle_set: vec![oracle_a_id.clone(), oracle_b_id.clone()],
                oracle_quorum: 2,
            })
            .unwrap();

        let recipient = addr(42);
        chain.state.create_account(recipient, Balance::new(100));
        register_real_test_station(&mut chain, "station-low-streak", recipient);

        let (commit_1, mut reveal_1, commit_id_1) = build_commit_and_reveal(
            TransactionType::ContributionReveal,
            "station-low-streak",
            "contribution",
            1_700_220_000,
            serde_json::json!({"quality":0.20,"volume":1.0,"uniqueness":1.0}),
            "low-streak-1",
        );
        reveal_1.sender_address = recipient;
        let att1_1 = signed_attestation_tx(
            &commit_id_1,
            &oracle_a_sk,
            &oracle_a_id,
            true,
            1_700_220_001,
            "low-streak-1-a",
        );
        let att1_2 = signed_attestation_tx(
            &commit_id_1,
            &oracle_b_sk,
            &oracle_b_id,
            true,
            1_700_220_002,
            "low-streak-1-b",
        );

        let mut block_1 = Block::new(3, chain.tip, vec![commit_1, reveal_1, att1_1, att1_2], 1, 1);
        pop.apply_contribution_rewards(&mut chain, &mut block_1)
            .unwrap();
        assert_eq!(
            chain.state.get_account(&recipient).unwrap().balance,
            100,
            "first low-quality event should not slash yet"
        );

        let (commit_2, mut reveal_2, commit_id_2) = build_commit_and_reveal(
            TransactionType::ContributionReveal,
            "station-low-streak",
            "contribution",
            1_700_220_010,
            serde_json::json!({"quality":0.20,"volume":1.0,"uniqueness":1.0}),
            "low-streak-2",
        );
        reveal_2.sender_address = recipient;
        let att2_1 = signed_attestation_tx(
            &commit_id_2,
            &oracle_a_sk,
            &oracle_a_id,
            true,
            1_700_220_011,
            "low-streak-2-a",
        );
        let att2_2 = signed_attestation_tx(
            &commit_id_2,
            &oracle_b_sk,
            &oracle_b_id,
            true,
            1_700_220_012,
            "low-streak-2-b",
        );

        let mut block_2 = Block::new(4, chain.tip, vec![commit_2, reveal_2, att2_1, att2_2], 1, 1);
        pop.apply_contribution_rewards(&mut chain, &mut block_2)
            .unwrap();

        assert_eq!(
            chain.state.get_account(&recipient).unwrap().balance,
            95,
            "second consecutive low-quality event should apply slash amount"
        );
        assert_eq!(
            block_2
                .metadata
                .get("quality_slashing_applied_count")
                .map(String::as_str),
            Some("1")
        );
        assert_eq!(chain.state.quality_policy_events().len(), 3);
        let slashing_event = chain
            .state
            .quality_policy_events()
            .iter()
            .find(|event| event.event_type == QualityPolicyEventType::SlashingApplied)
            .expect("slashing event should be recorded");
        assert_eq!(slashing_event.commit_id, commit_id_2);
        assert_eq!(slashing_event.quality_band, DataQualityBand::Low);
        assert_eq!(slashing_event.slashed_amount, Some(Balance::new(5)));
    }

    #[test]
    fn rewards_apply_trust_weighting_by_contributor_class() {
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        let (oracle_a_sk, oracle_a_id) = oracle_identity(701);
        let (oracle_b_sk, oracle_b_id) = oracle_identity(702);

        fn run_reward_for_class(
            pop: &ProofOfPublishing,
            oracle_a_sk: &PrivateKey,
            oracle_a_id: &str,
            oracle_b_sk: &PrivateKey,
            oracle_b_id: &str,
            class: ContributorClass,
            station_id: &str,
            tag: &str,
        ) -> Balance {
            let mut chain = Blockchain::default();
            chain
                .state
                .governance
                .params
                .trust_weighting_policy
                .unverified_weight = 0.50;
            chain
                .state
                .governance
                .params
                .trust_weighting_policy
                .verified_station_weight = 0.80;
            chain
                .state
                .governance
                .params
                .trust_weighting_policy
                .trusted_provider_weight = 1.00;
            chain
                .apply_state_transition(StateTransition::SetOracleConfig {
                    oracle_set: vec![oracle_a_id.to_string(), oracle_b_id.to_string()],
                    oracle_quorum: 2,
                })
                .unwrap();

            let timestamp = 1_700_310_000;
            match class {
                ContributorClass::Unverified => {},
                ContributorClass::VerifiedStation => {
                    chain.state.calibration_attestations.insert(
                        station_id.to_string(),
                        CalibrationAttestationRecord {
                            station_id: station_id.to_string(),
                            calibrator_id: "calibrator".to_string(),
                            calibrator_key_epoch: None,
                            issued_at: timestamp - 100,
                            expires_at: timestamp + 100,
                            nonce: None,
                        },
                    );
                },
                ContributorClass::TrustedProvider => {
                    chain
                        .state
                        .governance
                        .params
                        .contributor_tier_policy
                        .trusted_provider_station_ids
                        .insert(station_id.to_string());
                },
            }

            let recipient = addr(91);
            chain.state.create_account(recipient, Balance::new(0));
            register_real_test_station(&mut chain, station_id, recipient);

            let (commit, mut reveal, commit_id) = build_commit_and_reveal(
                TransactionType::ContributionReveal,
                station_id,
                "contribution",
                timestamp,
                serde_json::json!({"quality":1.0,"volume":1.0,"uniqueness":1.0}),
                tag,
            );
            reveal.sender_address = recipient;
            let att_a = signed_attestation_tx(
                &commit_id,
                oracle_a_sk,
                oracle_a_id,
                true,
                timestamp + 1,
                &format!("{tag}-a"),
            );
            let att_b = signed_attestation_tx(
                &commit_id,
                oracle_b_sk,
                oracle_b_id,
                true,
                timestamp + 2,
                &format!("{tag}-b"),
            );
            let mut block = Block::new(3, chain.tip, vec![commit, reveal, att_a, att_b], 1, 1);
            pop.apply_contribution_rewards(&mut chain, &mut block)
                .unwrap();
            decided_reward_with_clamped_credit(&chain, &block, &commit_id, &recipient)
        }

        let unverified_reward = run_reward_for_class(
            &pop,
            &oracle_a_sk,
            &oracle_a_id,
            &oracle_b_sk,
            &oracle_b_id,
            ContributorClass::Unverified,
            "station-unverified-trust",
            "trust-unverified",
        );
        let verified_reward = run_reward_for_class(
            &pop,
            &oracle_a_sk,
            &oracle_a_id,
            &oracle_b_sk,
            &oracle_b_id,
            ContributorClass::VerifiedStation,
            "station-verified-trust",
            "trust-verified",
        );
        let trusted_reward = run_reward_for_class(
            &pop,
            &oracle_a_sk,
            &oracle_a_id,
            &oracle_b_sk,
            &oracle_b_id,
            ContributorClass::TrustedProvider,
            "station-trusted-trust",
            "trust-trusted",
        );

        assert!(
            trusted_reward > verified_reward && verified_reward > unverified_reward,
            "expected trusted > verified > unverified rewards with trust weighting, got {trusted_reward} >? {verified_reward} >? {unverified_reward}"
        );
    }

    #[test]
    fn block_hash_for_log_returns_typed_error_when_hash_missing() {
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        let block = Block::new(3, Hash::default(), vec![], 1, 1);
        let err = pop
            .block_hash_for_log(&block)
            .expect_err("missing hash should be rejected");
        let typed = err
            .downcast_ref::<ConsensusInvariantError>()
            .expect("error should preserve typed consensus invariant");
        assert_eq!(
            typed,
            &ConsensusInvariantError::MissingBlockHash {
                height: block.height
            }
        );
        assert!(err.to_string().contains("SP_CONS_INV_BLOCK_HASH_MISSING"));
    }

    #[test]
    fn block_hash_for_log_returns_hash_when_present() {
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        let mut block = Block::new(3, Hash::default(), vec![], 1, 1);
        let expected = block.calculate_hash();
        block.set_hash(expected);

        let hash = pop
            .block_hash_for_log(&block)
            .expect("present hash should be returned");
        assert_eq!(*hash, expected);
    }

