    #[test]
    fn forecast_rewards_emitted_as_state_transitions() {
        let (pop, mut chain, oracle_sk, oracle_id) = setup_oracle_chain(302);
        let recipient = addr(32);
        chain.state.create_account(recipient, Balance::new(0));
        register_real_test_station(&mut chain, "station-st", recipient);

        let manifest = test_manifest();
        let data = serde_json::json!({"accuracy": 1.0, "complexity": 1.0, "usefulness": 1.0});
        let nonce = "nonce-st";
        let commit_id =
            Transaction::compute_commit_id(&data, nonce, "station-st", 1_700_000_000, "forecast");
        let receipt = test_receipt_with_key(&oracle_sk, &oracle_id, &manifest, &commit_id, 0.8);

        let commit_payload = CommitPayload {
            commit_id: commit_id.clone(),
            station_id: "station-st".to_string(),
            timestamp: 1_700_000_000,
            contribution_type: "forecast".to_string(),
            auth_pubkey: None,
            auth_signature: None,
        };
        let reveal_payload = RevealPayload {
            commit_id: commit_id.clone(),
            station_id: "station-st".to_string(),
            timestamp: 1_700_000_000,
            contribution_type: "forecast".to_string(),
            data,
            nonce: nonce.to_string(),
            data_cid: None,
            data_hash: None,
            storage_provider: None,
            provenance: None,
            manifest: Some(manifest),
            verification_receipt: Some(receipt),
            compute_receipt: None,
                quality_tier: None,
        };

        let mut commit_tx = build_tx(TransactionType::ForecastCommit, None, "commit-st");
        commit_tx.data = Some(serde_json::to_string(&commit_payload).unwrap());
        commit_tx.set_id();

        let mut reveal_tx = build_tx(TransactionType::ForecastReveal, None, "reveal-st");
        reveal_tx.data = Some(serde_json::to_string(&reveal_payload).unwrap());
        reveal_tx.sender_address = recipient;
        reveal_tx.set_id();

        let att = signed_attestation_tx(
            &commit_id,
            &oracle_sk,
            &oracle_id,
            true,
            1_700_000_001,
            "st-att",
        );

        let balance_before = chain
            .state
            .get_account(&recipient)
            .map(|a| a.earned_balance_total)
            .unwrap_or(Balance::new(0));
        let mut block = Block::new(3, chain.tip, vec![commit_tx, reveal_tx, att], 1, 1);
        pop.apply_contribution_rewards(&mut chain, &mut block)
            .unwrap();

        let balance_after = chain
            .state
            .get_account(&recipient)
            .unwrap()
            .earned_balance_total;
        assert!(
            balance_after > balance_before,
            "reward should increase balance via state transition"
        );

        // #3021: `forecast_rewards_decided_total` is the producer's DECIDED
        // total; `forecast_rewards_minted_total` is what the state CREDITED,
        // i.e. the decided total clamped to the per-user window cap (#2509,
        // #2969 a2). Under a correctly denominated emission_rate the cap binds
        // here, so the two differ by construction and both are pinned.
        let decided: u128 = block
            .metadata
            .get("forecast_rewards_decided_total")
            .expect("forecast_rewards_decided_total must be present")
            .parse()
            .unwrap();
        let minted: u128 = block
            .metadata
            .get("forecast_rewards_minted_total")
            .expect("forecast_rewards_minted_total must be present")
            .parse()
            .unwrap();
        assert_eq!(
            decided,
            decided_reward_for_commit(&block, &commit_id).into_inner(),
            "decided total is the decided forecast reward"
        );
        assert_eq!(
            minted,
            (balance_after - balance_before).into_inner(),
            "minted total is what was credited (#3021)"
        );
        assert_eq!(
            minted,
            decided.min(EmissionForTests(&chain.state).per_user_emission_cap(block.height)),
            "the credit is the decided reward clamped to the per-user window cap (#2969 a2)"
        );
    }

