    // -----------------------------------------------------------------------
    // Forecast receipt chain-id binding (2026-09-09 forecast prototype)
    //
    // `forecast-score/src/blockchain.rs` folds a chain id and network id into
    // every receipt signing preimage, resolved PER CALL from
    // `WRFCOIN_CHAIN_ID` / `WRFCOIN_NETWORK_ID` with a MAINNET fallback
    // (`wrfcoin-main` / `mainnet`, #2034/#2065), so a signer and a node that
    // do not export the same pair produce receipts the node cannot verify.
    // These two tests pin what the code does about that TODAY; neither
    // changes consensus.
    // -----------------------------------------------------------------------

    /// Re-sign `receipt` under a chain/network binding that is deliberately
    /// NOT the one this process resolves.
    ///
    /// The test binary inherits whatever `WRFCOIN_CHAIN_ID` the environment
    /// carries (unset in CI, so the mainnet fallback). Mutating that env var
    /// mid-run would race every other signing test in this binary, so instead
    /// the ambient canonical preimage is rebuilt with its chain and network
    /// fields swapped for a binding chosen to differ from ambient. On a node
    /// actually configured for the testnet (`WRFCOIN_CHAIN_ID=777`) this is
    /// exactly the mainnet-signed-receipt case; with chain id unset it is its
    /// mirror image. Either way the asserted property is the one that matters:
    /// a receipt whose chain binding disagrees with the verifier's.
    fn sign_receipt_under_foreign_chain_binding(
        receipt: &mut ForecastVerificationReceipt,
        private_key: &PrivateKey,
    ) {
        let ambient = crate::blockchain::transaction::forecast_receipt_signing_message(receipt);
        let mut parts: Vec<String> = ambient.split('|').map(str::to_string).collect();
        assert_eq!(
            parts.len(),
            8,
            "canonical forecast signing preimage is 8 pipe-separated fields, got: {ambient}"
        );
        let (foreign_chain, foreign_network) = if parts[2] == "wrfcoin-main" {
            ("777", "testnet")
        } else {
            ("wrfcoin-main", "mainnet")
        };
        parts[2] = foreign_chain.to_string();
        parts[3] = foreign_network.to_string();
        let foreign_message = parts.join("|");
        receipt.signature = Some(private_key.sign(foreign_message.as_bytes()).to_string());
    }

    /// Build a quorum-attested forecast commit/reveal/attestation triple for
    /// `station_id`, paying `owner`.
    ///
    /// `receipt_skill` attaches an oracle receipt at that skill score;
    /// `foreign_binding` re-signs it under a chain binding this process does
    /// not resolve. Returns `(commit, reveal, attestation, commit_id)`.
    #[allow(clippy::too_many_arguments)]
    fn attested_forecast_bundle(
        oracle_sk: &PrivateKey,
        oracle_id: &str,
        station_id: &str,
        owner: Address,
        manifest: &ForecastArtifactManifest,
        timestamp: i64,
        tag: &str,
        receipt_skill: Option<f64>,
        foreign_binding: bool,
    ) -> (Transaction, Transaction, Transaction, String) {
        let data = serde_json::json!({"accuracy": 1.0, "complexity": 1.0, "usefulness": 1.0});
        // The receipt is bound to the commit id, so it has to be derived here
        // the same way `build_forecast_commit_reveal_with_manifest` derives it.
        let commit_id = Transaction::compute_commit_id(
            &data,
            &format!("nonce-{tag}"),
            station_id,
            timestamp,
            "forecast",
        );
        let receipt = receipt_skill.map(|skill| {
            let mut receipt =
                test_receipt_with_key(oracle_sk, oracle_id, manifest, &commit_id, skill);
            if foreign_binding {
                sign_receipt_under_foreign_chain_binding(&mut receipt, oracle_sk);
            }
            receipt
        });
        let (commit_tx, mut reveal_tx, commit_id) = build_forecast_commit_reveal_with_manifest(
            station_id,
            timestamp,
            data,
            Some(manifest.clone()),
            receipt,
            tag,
        );
        // Below `STATION_OWNERSHIP_BINDING_ACTIVATION_HEIGHT` the
        // payee is resolved from the reveal itself, not the station registry.
        reveal_tx.sender_address = owner;
        reveal_tx.set_id();
        let attestation = signed_attestation_tx(
            &commit_id,
            oracle_sk,
            oracle_id,
            true,
            timestamp + 1,
            &format!("{tag}-att"),
        );
        (commit_tx, reveal_tx, attestation, commit_id)
    }

    /// (a) A quorum-attested `ForecastReveal` carrying a receipt signed by a
    /// genesis-oracle-set key under the binding this process resolves scores
    /// at the receipt's own `skill_score` — strictly more than the same
    /// reveal with no receipt, which falls to `BASELINE_FORECAST_SKILL` — and
    /// the minted amount is charged to the block's contribution slice.
    #[test]
    fn attested_forecast_receipt_mints_above_baseline_and_charges_contribution_slice() {
        let (pop, mut chain, oracle_sk, oracle_id) = setup_oracle_chain(9091);
        let receipt_owner = addr(91);
        let baseline_owner = addr(92);
        chain.state.create_account(receipt_owner, Balance::new(0));
        chain.state.create_account(baseline_owner, Balance::new(0));
        register_real_test_station(&mut chain, "station-forecast-receipt", receipt_owner);
        register_real_test_station(&mut chain, "station-forecast-baseline", baseline_owner);

        let manifest = test_manifest();

        // Both reveals ride in ONE block, so they see an identical block
        // emission and an identical contribution slice, and differ only in
        // whether a valid receipt is attached. Distinct payees keep each
        // decision inside its own per-user emission window (#2509), so
        // neither is left pending and re-swept into a later block.
        let (receipt_commit, receipt_reveal, receipt_att, receipt_commit_id) =
            attested_forecast_bundle(
                &oracle_sk,
                &oracle_id,
                "station-forecast-receipt",
                receipt_owner,
                &manifest,
                1_700_000_000,
                "proto-receipt",
                Some(0.95),
                false,
            );
        let (base_commit, base_reveal, base_att, base_commit_id) = attested_forecast_bundle(
            &oracle_sk,
            &oracle_id,
            "station-forecast-baseline",
            baseline_owner,
            &manifest,
            1_700_000_000,
            "proto-baseline",
            None,
            false,
        );

        let mut block = Block::new(
            3,
            chain.tip,
            vec![
                receipt_commit,
                receipt_reveal,
                receipt_att,
                base_commit,
                base_reveal,
                base_att,
            ],
            1,
            1,
        );
        pop.apply_contribution_rewards(&mut chain, &mut block)
            .unwrap();

        let with_receipt = decided_reward_for_commit(&block, &receipt_commit_id);
        let baseline = decided_reward_for_commit(&block, &base_commit_id);

        assert!(
            baseline > Balance::new(0),
            "an attested forecast with a valid manifest and no receipt still pays the \
             baseline skill ({BASELINE_FORECAST_SKILL}), got {baseline}"
        );
        assert!(
            with_receipt > baseline,
            "a receipt signed by an authorized oracle under the resolved chain binding \
             must score at its own skill_score (0.95), not the baseline \
             ({BASELINE_FORECAST_SKILL}): with_receipt={with_receipt}, baseline={baseline}"
        );

        assert_eq!(
            block
                .metadata
                .get("forecast_rewards_with_receipt_count")
                .map(String::as_str),
            Some("1"),
            "exactly one reveal carried an accepted receipt"
        );
        assert_eq!(
            block
                .metadata
                .get("forecast_rewards_baseline_count")
                .map(String::as_str),
            Some("1"),
            "exactly one reveal fell through to the baseline path"
        );

        // The forecast lane is charged to the same contribution slice as the
        // contribution lane: `forecast_rewards_minted_total` is the lane's
        // decided total, and it rolls up into the block's real-provenance
        // minted total.
        let forecast_total: u128 = block
            .metadata
            .get("forecast_rewards_minted_total")
            .expect("forecast_rewards_minted_total must be present")
            .parse()
            .unwrap();
        assert_eq!(
            forecast_total,
            with_receipt.into_inner() + baseline.into_inner(),
            "forecast_rewards_minted_total is the decided total for both reveals"
        );
        let real_minted_total: u128 = block
            .metadata
            .get("rewards_provenance_real_minted_total")
            .expect("rewards_provenance_real_minted_total must be present")
            .parse()
            .unwrap();
        assert_eq!(
            real_minted_total, forecast_total,
            "with no contribution-lane rewards in this block, the entire real-provenance \
             charge against the contribution slice is the forecast lane's"
        );

        // The credit lands on the reveal's payee, clamped to the per-user
        // window cap (#2969 a2) — the metadata total is the DECIDED amount.
        let credited = chain
            .state
            .get_account(&receipt_owner)
            .expect("payee account must exist")
            .earned_balance_total;
        assert_eq!(
            credited,
            Balance::new(
                with_receipt
                    .into_inner()
                    .min(chain.state.emission_for_tests().per_user_emission_cap(block.height)),
            ),
            "the receipt-scored reward is credited to the reveal's payee, clamped to the \
             per-user window cap"
        );
    }

    /// (b) Foreign-binding receipts fail strict replay, but normal production
    /// prunes the reveal and continues. Pin the durable outcome on producer
    /// AND follower: no forecast credit and no oracle slash survives the
    /// discarded pruning state. This does not change #3064's consensus policy.
    #[tokio::test]
    async fn forecast_foreign_binding_is_pruned_without_durable_oracle_slashing() {
        let (mut pop, mut chain, oracle_sk, oracle_id) = setup_oracle_chain(9093);
        let foreign_owner = addr(93);
        chain.state.create_account(foreign_owner, Balance::new(0));
        register_real_test_station(&mut chain, "station-forecast-foreign", foreign_owner);

        let manifest = test_manifest();
        let (foreign_commit, foreign_reveal, foreign_att, foreign_commit_id) =
            attested_forecast_bundle(
                &oracle_sk,
                &oracle_id,
                "station-forecast-foreign",
                foreign_owner,
                &manifest,
                1_700_000_000,
                "proto-foreign",
                Some(0.95),
                true,
            );

        // The receipt is well formed, bound to the right commit and manifest,
        // and issued by an oracle in the genesis set. The ONLY defect is the
        // chain binding folded into its signature.
        let payload = foreign_reveal
            .parse_reveal_payload()
            .expect("reveal payload must parse");
        let receipt = payload
            .verification_receipt
            .as_ref()
            .expect("the reveal carries a receipt");
        assert!(receipt.validate().is_ok(), "receipt fields are valid");
        assert_eq!(receipt.commit_id, foreign_commit_id);
        assert_eq!(
            receipt.manifest_digest,
            forecast_manifest_digest(&manifest),
            "receipt is bound to this manifest"
        );
        assert!(
            pop.is_authorized_oracle(&receipt.oracle_id),
            "the signer is in the genesis oracle set"
        );
        assert!(
            !forecast_receipt_has_valid_signature(receipt),
            "a foreign chain binding is enough, on its own, to fail signature verification"
        );

        let state_before_refusal = chain.state.clone();
        let mut block = Block::new(
            3,
            chain.tip,
            vec![foreign_commit.clone(), foreign_reveal.clone(), foreign_att.clone()],
            1,
            1,
        );
        let err = pop
            .apply_contribution_rewards(&mut chain, &mut block)
            .expect_err(
                "a ForecastReveal carrying a receipt signed under a foreign chain binding \
                 must fail state replay, not be silently paid at baseline",
            )
            .to_string();

        assert!(
            err.contains("ForecastReveal"),
            "the refusal names the offending transaction type: {err}"
        );
        assert!(
            err.contains("Slashing triggered") && err.contains("InvalidSignature"),
            "the refusal is a slashing trigger for an invalid receipt signature: {err}"
        );
        assert!(
            err.contains(&oracle_id),
            "the trigger names the receipt oracle ({oracle_id}): {err}"
        );

        // The strict error above mutates a temporary replay state, not a produced block.
        // Start the real producer from its pristine state at height 1 so the next
        // block exercises pruning rather than the block-1 ceremony machinery.
        chain.state = state_before_refusal;
        chain.height = 1;
        pop.set_clock(fixed_clock());
        let oracle_address = Address::from_hex(
            PublicKey::from_private_key(&oracle_sk).to_address().trim_start_matches("wrf"),
        ).unwrap();
        chain.state.create_account(oracle_address, Balance::new(1_000_000_000));
        let oracle_balance_before = chain.state.get_account(&oracle_address).unwrap().balance;
        assert!(oracle_balance_before > Balance::new(0));
        assert!(!chain.state.oracle_registry().is_in_cooldown(&oracle_id, 2));
        assert!(chain.state.slashing_events_by_reason().is_empty());

        let mut follower = Blockchain::default();
        follower.height = chain.height;
        follower.state = chain.state.clone();
        follower.tip = chain.tip;
        let mut control_chain = Blockchain::default();
        control_chain.height = chain.height;
        control_chain.tip = chain.tip;
        control_chain.state = chain.state.clone();
        let control = Arc::new(RwLock::new(control_chain));
        let control_mempool = Arc::new(RwLock::new(Mempool::new(&Config::default())));
        let (mut control_pop, _, _, _) = setup_oracle_chain(9093);
        control_pop.set_clock(fixed_clock());
        let producer = Arc::new(RwLock::new(chain));
        let mempool = Arc::new(RwLock::new(Mempool::new(&Config::default())));
        let signing_keys = oracle_registry_for(&[&oracle_id]);
        let mut reveal_id = None;
        // Explicit fees force commit -> reveal -> attestation, so an absent
        // commit cannot be the reason the receipt is refused.
        for (mut tx, fee) in [(foreign_commit, 3), (foreign_reveal, 2), (foreign_att, 1)] {
            tx.timestamp = fixed_test_now();
            tx.fee = fee;
            tx.set_id();
            if tx.tx_type == TransactionType::ForecastReveal {
                reveal_id = tx.id;
            } else {
                control_mempool.write().await.add_transaction_with_signing_keys(tx.clone(), Some(&signing_keys)).unwrap();
            }
            mempool.write().await.add_transaction_with_signing_keys(tx, Some(&signing_keys)).unwrap();
        }
        let reveal_id = reveal_id.unwrap();
        assert!(mempool.read().await.get_transaction(&reveal_id).is_some());
        control_pop.create_next_block(
            control.clone(), control_mempool, "0x1111111111111111111111111111111111111111",
        ).await.expect("the matched control without the bad reveal must produce");
        let control = control.read().await;
        // Accepted attestations can earn reputation and attester rewards. The
        // control holds those effects constant so they cannot mask a penalty.
        let expected_oracle_balance = control.state.get_account(&oracle_address).unwrap().balance;
        let expected_oracle_reputation = control.state.oracle_registry().reputation_score(&oracle_id);
        assert!(expected_oracle_balance >= oracle_balance_before);
        assert!(control.state.slashing_events_by_reason().is_empty());
        let mut produced = pop.create_next_block(
            producer.clone(), mempool.clone(), "0x1111111111111111111111111111111111111111",
        ).await.expect("the producer prunes the bad receipt and still makes a block");
        assert_eq!(produced.height, 2);
        assert_eq!(produced.metadata.get("pop_skipped_mempool_transactions").map(String::as_str), Some("1"));
        assert!(!produced.transactions.iter().any(|tx| tx.tx_type == TransactionType::ForecastReveal));
        assert!(produced.transactions.iter().any(|tx| tx.tx_type == TransactionType::ForecastCommit));
        assert!(mempool.read().await.get_transaction(&reveal_id).is_none());
        for key in ["forecast_rewards_with_receipt_count", "forecast_rewards_baseline_count",
            "forecast_rewards_minted_count", "forecast_rewards_minted_total"] {
            assert_eq!(produced.metadata.get(key).map(String::as_str), Some("0"), "{key}");
        }
        pop.replay_received_block_for_test_support(&mut follower, &mut produced)
            .expect("the produced block must replay and finalize on a follower");
        let producer = producer.read().await;
        assert_eq!(producer.height, 2);
        assert_eq!(follower.height, 2);
        assert_eq!(producer.state.state_root, follower.state.state_root);
        for state in [&producer.state, &follower.state] {
            assert_eq!(state.get_account(&oracle_address).unwrap().balance, expected_oracle_balance);
            assert_eq!(state.oracle_registry().reputation_score(&oracle_id), expected_oracle_reputation);
            assert!(!state.oracle_registry().is_in_cooldown(&oracle_id, produced.height));
            assert!(state.slashing_events_by_reason().is_empty());
            assert_eq!(state.get_account(&foreign_owner).unwrap().earned_balance_total, Balance::new(0));
            assert!(!state.finalized_contribution_rewards.contains(&foreign_commit_id));
            assert!(!state.contribution_reward_records.contains_key(&foreign_commit_id));
        }
        // An additional flush cannot apply a hidden pending slash to live state:
        // the trigger existed only on the producer's discarded pruning clone.
        let mut finalized_again = producer.state.clone();
        finalized_again.flush_deferred_slashing();
        assert_eq!(finalized_again.get_account(&oracle_address).unwrap().balance, expected_oracle_balance);
        assert_eq!(finalized_again.oracle_registry().reputation_score(&oracle_id), expected_oracle_reputation);
        assert!(finalized_again.slashing_events_by_reason().is_empty());
    }

