    #[tokio::test]
    async fn verify_block_quality_path_uses_runtime_oracle_quorum() {
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        pop.set_clock(fixed_clock());

        let (oracle_sk, oracle_id) = oracle_identity(7303);
        let mut oracle_set = FxHashSet::default();
        oracle_set.insert(oracle_id.clone());
        // Mirror production: register the oracle in the signing-key registry
        // before verify_block (#1756 fail-closed apply-time check).
        pop.set_oracle_signing_keys(oracle_registry_for(&[&oracle_id]));

        let (commit_tx, mut low_quality_reveal_tx, commit_id) = build_commit_and_reveal(
            TransactionType::ContributionReveal,
            "station-low-quorum-runtime",
            "contribution",
            1_700_000_550,
            serde_json::json!({ "quality": 0.20 }),
            "low-quorum-runtime",
        );
        low_quality_reveal_tx.fee = 1;
        let attestation = signed_attestation_tx(
            &commit_id,
            &oracle_sk,
            &oracle_id,
            true,
            1_700_000_551,
            "low-quorum-runtime",
        );

        let coinbase = Transaction::new_coinbase("miner", adjusted_block_reward(5), 5);
        let txs = vec![coinbase, commit_tx, low_quality_reveal_tx, attestation];
        let score = pop.calculate_block_publishing_score(&txs, 5);
        let mut block = Block::new(3, Hash::default(), txs, 1, 5);
        block.timestamp = fixed_test_now();
        block
            .metadata
            .insert("publishing_score".to_string(), score.to_string());

        let rejected = pop.verify_block(&block, &oracle_set, 2, &[]).await.unwrap();
        assert!(
            !rejected,
            "Block should be rejected when runtime oracle quorum is 2 but only one attestation exists"
        );

        let accepted = pop.verify_block(&block, &oracle_set, 1, &[]).await.unwrap();
        assert!(
            accepted,
            "Block should be accepted when runtime oracle quorum is 1 and one attestation exists"
        );
    }

