    #[tokio::test]
    async fn create_next_block_keeps_low_quality_reveal_when_quorum_attested() {
        let config = Config::default();
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        // #2523: this dev chain has no oracle ceremony. It must SAY so — a
        // block 1 that declares nothing is refused, which is the point.
        pop.declare_no_genesis_oracles();
        pop.set_clock(fixed_clock());
        let chain = Arc::new(RwLock::new(Blockchain::default()));
        let mempool = Arc::new(RwLock::new(Mempool::new(&config)));

        let (oracle_sk, oracle_id) = oracle_identity(7401);
        {
            let mut chain_guard = chain.write().await;
            chain_guard
                .apply_state_transition(StateTransition::SetOracleConfig {
                    oracle_set: vec![oracle_id.clone()],
                    oracle_quorum: 1,
                })
                .unwrap();
            register_real_test_station(
                &mut chain_guard,
                "station-low-mining",
                addr(0),
            );
        }

        let (commit_tx, mut low_quality_reveal_tx, commit_id) = build_commit_and_reveal(
            TransactionType::ContributionReveal,
            "station-low-mining",
            "contribution",
            1_700_000_700,
            serde_json::json!({ "quality": 0.20 }),
            "low-attested-mining",
        );
        low_quality_reveal_tx.fee = 1;
        let attestation_tx = signed_attestation_tx(
            &commit_id,
            &oracle_sk,
            &oracle_id,
            true,
            1_700_000_701,
            "low-attested-mining",
        );

        // Oracle attestations require the signing-key registry at mempool
        // admission (#1723). The oracle is registered in chain state via
        // SetOracleConfig above, so thread that registry through.
        let signing_keys = chain.read().await.state.signing_keys.clone();  // secret-copy-ok: SigningKeyRegistry holds public keys only
        {
            let mut mempool_guard = mempool.write().await;
            mempool_guard.add_transaction(commit_tx).unwrap();
            mempool_guard
                .add_transaction(low_quality_reveal_tx)
                .unwrap();
            mempool_guard
                .add_transaction_with_signing_keys(attestation_tx, Some(&signing_keys))
                .unwrap();
        }

        let block = pop
            .create_next_block(chain.clone(), mempool.clone(), "wrf-low-miner")
            .await
            .unwrap();

        let low_reveal_count = block
            .transactions
            .iter()
            .filter(|tx| tx.tx_type == TransactionType::ContributionReveal)
            .count();
        assert_eq!(
            low_reveal_count, 1,
            "Low-quality reveal with quorum attestation should be included in mined block"
        );
        assert_eq!(
            block
                .metadata
                .get("quality_challenge_count")
                .map(String::as_str),
            Some("1"),
            "Low-band inclusion should emit challenge metadata in mined block"
        );
    }

