    #[tokio::test]
    async fn create_next_block_skips_and_evicts_invalid_launch_transactions() {
        // This test exercises launch-tx timing/replay eviction with zero-fee
        // weather reveals. Such reveals are only valid under the testnet
        // compute-fee floor (`WRFCOIN_MIN_WORK_FACTOR=0`); pin that here so the
        // producer self-screen (#1730) — which now enforces the same
        // compute-fee gate as verify_block — keeps the valid reveal instead of
        // dropping it as a no-receipt feeless tx. Serialize against #1487 env
        // tests via the shared guard.
        let _g = MIN_WORK_FACTOR_ENV_GUARD.lock().unwrap_or_else(|p| p.into_inner());
        set_min_work_factor_floor_override_for_tests(Some(0));

        let config = Config::default();
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        // #2523: this dev chain has no oracle ceremony. It must SAY so — a
        // block 1 that declares nothing is refused, which is the point.
        pop.declare_no_genesis_oracles();
        pop.set_clock(fixed_clock());
        pop.set_submission_time_window(400_000);
        let chain = Arc::new(RwLock::new(Blockchain::default()));
        let mempool = Arc::new(RwLock::new(Mempool::new(&config)));

        let now = fixed_test_now().timestamp();
        let valid_timestamp = now - 30;
        let invalid_timestamp = now + 200_000;
        let station_id = "station-skip";

        let (valid_commit_tx, valid_reveal_tx, _) = build_commit_and_reveal(
            TransactionType::ContributionReveal,
            station_id,
            "contribution",
            valid_timestamp,
            serde_json::json!({ "temperature": 21.0, "humidity": 0.42 }),
            "skip-valid",
        );
        let (invalid_commit_tx, invalid_reveal_tx, _) = build_commit_and_reveal(
            TransactionType::ContributionReveal,
            station_id,
            "contribution",
            invalid_timestamp,
            serde_json::json!({ "temperature": 22.0, "humidity": 0.40 }),
            "skip-invalid",
        );
        let invalid_reveal_id = invalid_reveal_tx
            .id
            .expect("invalid reveal must have a transaction id");

        {
            let mut mempool_guard = mempool.write().await;
            mempool_guard.add_transaction(valid_commit_tx).unwrap();
            mempool_guard.add_transaction(invalid_commit_tx).unwrap();
            mempool_guard.add_transaction(valid_reveal_tx).unwrap();
            mempool_guard.add_transaction(invalid_reveal_tx).unwrap();
        }

        let block = pop
            .create_next_block(chain.clone(), mempool.clone(), "wrf-skip-miner")
            .await
            .expect("block creation should skip the invalid launch tx instead of aborting");

        // Reset the floor override before assertions so a failure cannot leak it.
        set_min_work_factor_floor_override_for_tests(None);

        let reveal_count = block
            .transactions
            .iter()
            .filter(|tx| tx.tx_type == TransactionType::ContributionReveal)
            .count();
        assert_eq!(
            reveal_count, 1,
            "only the valid reveal should survive block assembly"
        );
        // Was `Some("2")`. One of those two was the COINBASE.
        //
        // This test runs under `fixed_clock()`, so the producer reference time is
        // ~2.7 years from the coinbase's `Utc::now()` stamp, and
        // `filter_by_submission_timing` counted the coinbase as a skipped
        // *mempool* transaction — which it is not; it is minted during assembly
        // and never passes through the mempool. The figure has therefore been
        // asserting the defect, not the behaviour: a block that reached this
        // assertion with "2" had already had its coinbase deleted.
        //
        // With the coinbase exempted, exactly one genuinely invalid mempool
        // transaction is skipped, which is what the name of this test describes.
        assert_eq!(
            block
                .metadata
                .get("pop_skipped_mempool_transactions")
                .map(String::as_str),
            Some("1"),
            "exactly one invalid MEMPOOL transaction should be recorded as \
             skipped; the coinbase is not a mempool transaction and must not be \
             counted here"
        );
        assert_eq!(
            block
                .transactions
                .iter()
                .filter(|tx| tx.tx_type == TransactionType::Coinbase)
                .count(),
            1,
            "the coinbase must survive assembly even under a skewed clock"
        );
        assert!(
            !block
                .transactions
                .iter()
                .any(|tx| tx.id == Some(invalid_reveal_id)),
            "the invalid reveal must be pruned from the final block"
        );

        let mempool_guard = mempool.read().await;
        assert!(
            mempool_guard.get_transaction(&invalid_reveal_id).is_none(),
            "the skipped invalid reveal must be evicted from the mempool"
        );
    }

    /// Regression: low-band reveal must NOT be admitted based on attestations
    /// that only exist in prior-block chain state (not the current block).
    ///
    /// Before the fix, `create_next_block` extended `low_quality_quorum_commit_ids`
    /// with `chain.state.attestations`, letting a reveal slip through even when
    /// no oracle attestation was present in the candidate block.  `verify_block`
    /// has no access to chain state attestations, so such a block would have
    /// failed re-validation — a mining/verify split.
    ///
    /// After the fix the mining admission check uses only in-block attestations,
    /// matching what `verify_block` can observe.
    #[tokio::test]
    async fn create_next_block_rejects_reveal_relying_on_prior_block_attestations() {
        let config = Config::default();
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        // #2523: this dev chain has no oracle ceremony. It must SAY so — a
        // block 1 that declares nothing is refused, which is the point.
        pop.declare_no_genesis_oracles();
        let chain = Arc::new(RwLock::new(Blockchain::default()));
        let mempool = Arc::new(RwLock::new(Mempool::new(&config)));

        let (oracle_sk, oracle_id) = oracle_identity(7403);

        let (commit_tx, mut low_quality_reveal_tx, commit_id) = build_commit_and_reveal(
            TransactionType::ContributionReveal,
            "station-prior-attest",
            "contribution",
            1_700_000_800,
            serde_json::json!({ "quality": 0.20 }),
            "prior-attest",
        );
        low_quality_reveal_tx.fee = 1;

        {
            let mut chain_guard = chain.write().await;
            // Configure single-oracle quorum so one attestation is sufficient.
            chain_guard
                .apply_state_transition(StateTransition::SetOracleConfig {
                    oracle_set: vec![oracle_id.clone()],
                    oracle_quorum: 1,
                })
                .unwrap();

            // Simulate a prior block that already accumulated the attestation —
            // record it into chain state the same way block application does.
            let prior_att = signed_attestation_tx(
                &commit_id,
                &oracle_sk,
                &oracle_id,
                true,
                1_700_000_801,
                "prior-attest-chain",
            );
            let payload = prior_att
                .parse_oracle_attestation_payload()
                .expect("attestation payload must parse");
            chain_guard
                .apply_state_transition(StateTransition::RecordOracleAttestation {
                    payload,
                    current_block: 0,
                })
                .unwrap();

            // Precondition: quorum is now satisfied in chain state.
            assert!(
                chain_guard
                    .state
                    .attestations
                    .get(&commit_id)
                    .map(|s| s.has_quorum(1))
                    .unwrap_or(false),
                "precondition: chain state must reflect quorum-satisfied attestation"
            );
        }

        // Mempool contains only the commit and the low-quality reveal.
        // The attestation is NOT in the mempool — it was "included" in a
        // prior block (represented above by the chain-state population).
        {
            let mut mempool_guard = mempool.write().await;
            mempool_guard.add_transaction(commit_tx).unwrap();
            mempool_guard
                .add_transaction(low_quality_reveal_tx)
                .unwrap();
        }

        let block = pop
            .create_next_block(chain.clone(), mempool.clone(), "wrf-miner-prior")
            .await
            .unwrap();

        let reveal_count = block
            .transactions
            .iter()
            .filter(|tx| tx.tx_type == TransactionType::ContributionReveal)
            .count();
        assert_eq!(
            reveal_count, 0,
            "Low-quality reveal must not be admitted when quorum comes only from prior-block \
             chain state — verify_block cannot observe those attestations"
        );
    }

