    #[test]
    fn verify_launch_state_invariants_rejects_reveal_without_commit() {
        let pop = ProofOfPublishing::new(1, 60, 0, 10);
        let chain = Blockchain::default();
        let (_, reveal_tx, _) = build_commit_and_reveal(
            TransactionType::ContributionReveal,
            "station-missing-commit",
            "contribution",
            1_700_000_900,
            serde_json::json!({ "quality": 0.90 }),
            "missing-commit",
        );
        let block = Block::new(3, chain.tip, vec![reveal_tx], 1, 1);

        let err = ProofOfPublishing::verify_launch_state_invariants(&chain, &block)
            .expect_err("reveal without commit should fail replay invariants");
        let typed = err
            .downcast_ref::<ConsensusInvariantError>()
            .expect("replay failure should preserve typed invariant");
        assert!(matches!(
            typed,
            ConsensusInvariantError::PopStateTransitionFailed {
                tx_index: 0,
                tx_type: TransactionType::ContributionReveal,
                ..
            }
        ));
        assert!(
            err.to_string()
                .contains("SP_CONS_INV_POP_STATE_TRANSITION_FAILED")
        );
    }

