    #[tokio::test]
    async fn create_next_block_skips_reveal_without_commit_before_mutation() {
        let config = Config::default();
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        // #2523: this dev chain has no oracle ceremony. It must SAY so — a
        // block 1 that declares nothing is refused, which is the point.
        pop.declare_no_genesis_oracles();
        let chain = Arc::new(RwLock::new(Blockchain::default()));
        let mempool = Arc::new(RwLock::new(Mempool::new(&config)));
        let (_, mut reveal_tx, _) = build_commit_and_reveal(
            TransactionType::ContributionReveal,
            "station-bad-launch",
            "contribution",
            1_700_000_910,
            serde_json::json!({ "quality": 0.85 }),
            "bad-launch",
        );
        reveal_tx.fee = 1;
        let reveal_id = reveal_tx.id.expect("reveal must have a transaction id");

        {
            let mut mempool_guard = mempool.write().await;
            mempool_guard.add_transaction(reveal_tx).unwrap();
        }

        let block = pop
            .create_next_block(chain.clone(), mempool.clone(), "wrf-bad-launch")
            .await
            .expect("reveal without commit should now be skipped, not fatal");
        assert_eq!(
            block
                .metadata
                .get("pop_skipped_mempool_transactions")
                .map(String::as_str),
            Some("1"),
            "the missing-commit reveal should be counted as a skipped mempool tx"
        );
        assert_eq!(
            block
                .transactions
                .iter()
                .filter(|tx| tx.tx_type == TransactionType::ContributionReveal)
                .count(),
            0,
            "the invalid reveal must not be included in the final block"
        );

        let chain_guard = chain.read().await;
        assert_eq!(
            chain_guard.height, 1,
            "successful block creation must advance the chain"
        );
        assert_eq!(
            chain_guard.blocks().len(),
            1,
            "the skipped reveal should still allow a block to be appended"
        );

        let mempool_guard = mempool.read().await;
        assert!(
            mempool_guard.get_transaction(&reveal_id).is_none(),
            "the skipped reveal must be evicted from the mempool"
        );
    }

    /// #2777 production-path regression: a real reveal and its partial oracle
    /// evidence are deferred (not evicted), while unrelated valid work mines.
    #[tokio::test]
    async fn producer_defers_real_reveal_below_quorum_but_mines_unrelated_work_2777() {
        let config = Config::default();
        let mut pop = ProofOfPublishing::new(1, 60, 0, 16);
        pop.declare_no_genesis_oracles();
        pop.set_clock(fixed_clock());
        let chain = Arc::new(RwLock::new(Blockchain::default()));
        let mempool = Arc::new(RwLock::new(Mempool::new(&config)));

        let (oracle_a_sk, oracle_a_id) = oracle_identity(27_771);
        let (_oracle_b_sk, oracle_b_id) = oracle_identity(27_772);
        let (_oracle_c_sk, oracle_c_id) = oracle_identity(27_773);
        let signing_keys = {
            let mut chain_guard = chain.write().await;
            chain_guard.height = RICH_AMBIENT_REWARD_ACTIVATION_HEIGHT.saturating_sub(1);
            chain_guard
                .apply_state_transition(StateTransition::SetOracleConfig {
                    oracle_set: vec![oracle_a_id.clone(), oracle_b_id, oracle_c_id],
                    // Anti-hardcoding control: this chain explicitly requires
                    // three approvals, unlike the live testnet's configured two.
                    oracle_quorum: 3,
                })
                .unwrap();
            register_real_test_station(&mut chain_guard, "station-real-2777-low", addr(0x71));
            chain_guard.state.signing_keys.clone() // secret-copy-ok: public keys only
        };

        let (commit, mut reveal, commit_id) = build_commit_and_reveal(
            TransactionType::ContributionReveal,
            "station-real-2777-low",
            "contribution",
            FIXED_TEST_NOW_SECS - 10,
            serde_json::json!({ "temperature_c": 18.5, "humidity_pct": 47.0 }),
            "2777-low",
        );
        reveal.fee = 1;
        reveal.set_id();
        let reveal_id = reveal.id.expect("reveal has id");
        let partial_attestation = signed_attestation_tx(
            &commit_id,
            &oracle_a_sk,
            &oracle_a_id,
            true,
            FIXED_TEST_NOW_SECS - 9,
            "2777-low-a",
        );
        let attestation_id = partial_attestation.id.expect("attestation has id");
        let mut unrelated = build_tx(TransactionType::DataStorage, None, "2777-unrelated");
        unrelated.timestamp = fixed_test_now();
        unrelated.fee = 1;
        unrelated.set_id();
        let unrelated_id = unrelated.id.expect("unrelated tx has id");

        {
            let mut pool = mempool.write().await;
            pool.add_transaction(commit).unwrap();
            pool.add_transaction(reveal).unwrap();
            pool.add_transaction_with_signing_keys(partial_attestation, Some(&signing_keys))
                .unwrap();
            pool.add_transaction(unrelated).unwrap();
        }

        let block = pop
            .create_next_block(chain.clone(), mempool.clone(), "wrf-2777-low-miner")
            .await
            .expect("partial quorum must not prevent unrelated block production");

        assert!(
            !block.transactions.iter().any(|tx| tx.id == Some(reveal_id)),
            "one-of-three real reveal must be deferred; this chain configures quorum three"
        );
        assert_eq!(
            block
                .metadata
                .get("pop_deferred_real_contribution_reveals")
                .map(String::as_str),
            Some("1"),
            "the activation-height block must report the one deferred real reveal"
        );
        assert!(
            !block
                .transactions
                .iter()
                .any(|tx| tx.id == Some(attestation_id)),
            "partial approval must remain atomic with its deferred real reveal"
        );
        assert!(
            block
                .transactions
                .iter()
                .any(|tx| tx.id == Some(unrelated_id)),
            "the fence must not stall unrelated valid work"
        );
        assert_eq!(
            chain.read().await.height,
            RICH_AMBIENT_REWARD_ACTIVATION_HEIGHT,
            "unrelated work must still mine at activation"
        );

        let pool = mempool.read().await;
        assert!(
            pool.get_transaction(&reveal_id).is_some(),
            "deferred is not invalid: keep the real reveal in the mempool"
        );
        assert!(
            pool.get_transaction(&attestation_id).is_some(),
            "keep the partial attestation so another distinct vote can form quorum"
        );
        assert!(
            pool.get_transaction(&unrelated_id).is_none(),
            "mined unrelated work must be removed normally"
        );
    }

