    // ------------------------------------------------------------------------
    // #1279: ed25519 input-signature verification on Transfer transactions.
    // `verify_block_transactions_fused` now rejects Transfer txs that are
    // missing a signature, carry a malformed signature, or whose signature
    // does not verify against `signing_hash()` under the provided public key.
    // ------------------------------------------------------------------------

    fn build_block_with_transfer(pop: &ProofOfPublishing, tx: Transaction) -> Block {
        let coinbase = Transaction::new_coinbase("miner", adjusted_block_reward(5), 5);
        let txs = vec![coinbase, tx];
        let score = pop.calculate_block_publishing_score(&txs, 5);
        let mut block = Block::new(3, Hash::default(), txs, 1, 5);
        block
            .metadata
            .insert("publishing_score".to_string(), score.to_string());
        block
    }

    #[tokio::test]
    async fn verify_block_rejects_unsigned_transfer() {
        // Transfer with signature: None must be rejected (#1279).
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        pop.set_privacy_policy(PrivacyPolicy {
            min_privacy_level: PrivacyLevel::Standard,
            privacy_enforcement_activation_height: 0,
        });

        let unsigned = build_tx(TransactionType::Transfer, None, "unsigned");
        let block = build_block_with_transfer(&pop, unsigned);
        let result = pop
            .verify_block(
                &block,
                &FxHashSet::default(),
                DEFAULT_ORACLE_QUORUM.max(1),
                &[],
            )
            .await
            .unwrap();
        assert!(
            !result,
            "unsigned Transfer tx must be rejected at block validation time"
        );
    }

    #[tokio::test]
    async fn verify_block_rejects_transfer_with_forged_signature() {
        // Transfer signed by a key that does not match the claimed public_key
        // (signature is well-formed hex but verifies against the wrong message).
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        pop.set_privacy_policy(PrivacyPolicy {
            min_privacy_level: PrivacyLevel::Standard,
            privacy_enforcement_activation_height: 0,
        });

        let mut tx = build_signed_transfer_tx("forged", 2_001);
        // Overwrite signature with a valid-shape but wrong-message signature.
        let mut rng = StdRng::seed_from_u64(9_999);
        let other_key = PrivateKey::generate(&mut rng);
        let wrong_sig = other_key.sign(b"some other message").to_hex();
        tx.inputs[0].signature = Some(wrong_sig);
        tx.set_id();

        let block = build_block_with_transfer(&pop, tx);
        let result = pop
            .verify_block(
                &block,
                &FxHashSet::default(),
                DEFAULT_ORACLE_QUORUM.max(1),
                &[],
            )
            .await
            .unwrap();
        assert!(
            !result,
            "Transfer with forged signature must be rejected at block validation time"
        );
    }

