    // ───────────────────────── #1763 stake-auth hardening ───────────────────

    #[tokio::test]
    async fn forged_stake_rejected_on_sync_path() {
        // #1763 (a): a forged Stake/Unstake that mutates `victim`'s stake with
        // no valid account-bound authorization must be REJECTED by the sync path
        // — both with no authorization and with a well-formed signature from a
        // key the attacker controls (which does not derive to `victim`).
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        pop.set_privacy_policy(PrivacyPolicy {
            min_privacy_level: PrivacyLevel::Standard,
            privacy_enforcement_activation_height: 0,
        });
        let victim = Address::new([0x55u8; 20]);

        // (1) No authorization at all (the pre-#1763 spoof: bare Stake).
        let forged = build_forged_stake_tx(&victim, 1_000, false, 0, None);
        let block = build_block_with_transfer(&pop, forged);
        let result = pop
            .verify_block(&block, &FxHashSet::default(), DEFAULT_ORACLE_QUORUM.max(1), &[])
            .await
            .unwrap();
        assert!(
            !result,
            "sync path must REJECT a Stake with no account authorization (#1763)"
        );

        // (2) Attacker signs with their OWN key (does not derive to victim).
        let attacker = governance_transfer_key(909_090);
        let forged_signed = build_forged_stake_tx(&victim, 1_000, false, 0, Some(&attacker));
        let block = build_block_with_transfer(&pop, forged_signed);
        let result = pop
            .verify_block(&block, &FxHashSet::default(), DEFAULT_ORACLE_QUORUM.max(1), &[])
            .await
            .unwrap();
        assert!(
            !result,
            "sync path must REJECT a Stake signed by a non-`account` key (#1763)"
        );

        // (3) An Unstake reusing a Stake-bound signature must also be rejected
        // (action binding): sign for Stake, submit as Unstake.
        let account_key = governance_transfer_key(7_654);
        let account = Address::from_public_key(&PublicKey::from_private_key(&account_key));
        let mut payload = StakeAuthPayload {
            account: account.to_hex(),
            amount: 500,
            auth_pubkey: None,
            auth_signature: None,
        };
        payload.sign_authorization(&account_key, false, 0); // signed for Stake
        let mut wrong_action = Transaction::new(vec![], vec![]);
        wrong_action.tx_type = TransactionType::Unstake; // submitted as Unstake
        wrong_action.sender_address = account;
        wrong_action.nonce = 0;
        wrong_action.data = Some(serde_json::to_string(&payload).unwrap());
        wrong_action.set_id();
        let block = build_block_with_transfer(&pop, wrong_action);
        let result = pop
            .verify_block(&block, &FxHashSet::default(), DEFAULT_ORACLE_QUORUM.max(1), &[])
            .await
            .unwrap();
        assert!(
            !result,
            "sync path must REJECT an Unstake bearing a Stake-bound authorization (#1763)"
        );
    }

