    // ------------------------------------------------------------------------
    // #1728: producer/sync parity for the privacy-level gate. The PRODUCER
    // (`create_next_block`) never runs the privacy floor; the SYNC path
    // (`verify_block` → `verify_block_transactions_fused`) does. With the old
    // `Basic` default floor, a default-privacy (Standard) governance Transfer
    // in block 8 passed the producer but was REJECTED on sync, wedging peers at
    // height 7. These tests pin both halves of the durable fix:
    //   (a) the default floor is Standard so default-privacy txs validate
    //       identically on both paths; and
    //   (b) system/governance-provenanced Transfers are exempt even under a
    //       raised floor;
    //   (c) from-authorized USER transparent Transfers without governance
    //       provenance are still rejected under a raised floor; and
    //   (d) genuinely-too-low USER privacy is still rejected on the sync path.
    // ------------------------------------------------------------------------

    #[test]
    fn privacy_policy_default_floor_matches_default_tx_level() {
        // The genesis default floor MUST be satisfiable by a default-privacy tx,
        // or the sync-only privacy gate rejects blocks the producer builds.
        let policy = PrivacyPolicy::default();
        assert_eq!(
            policy.min_privacy_level,
            PrivacyLevel::default(),
            "default privacy floor must equal PrivacyLevel::default() (Standard) so \
             the sync-only privacy gate is a no-op for default-privacy txs"
        );
        // Ordering sanity: a Standard tx must not be below the default floor.
        assert!(
            PrivacyLevel::Standard >= policy.min_privacy_level,
            "Standard-privacy tx must satisfy the default floor"
        );
    }

    #[tokio::test]
    async fn parity_standard_privacy_governance_transfer_accepted_on_sync_default_policy() {
        // SYNC side with the DEFAULT policy (the live testnet configuration that
        // wedged at height 7): a governance/system transparent Transfer with
        // effective privacy level Standard must be ACCEPTED. This is the exact
        // block-8 scenario from #1728.
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        // Sanity: confirm we are running with the new default floor.
        assert_eq!(
            pop.privacy_policy.min_privacy_level,
            PrivacyLevel::Standard
        );

        let to = Address::new([0x22u8; 20]).to_hex();
        let gov =
            build_governance_transparent_transfer(&governance_transfer_key(1728), &to, 100, 0);
        assert_eq!(
            gov.effective_privacy_level(),
            PrivacyLevel::Standard,
            "precondition: governance Transfer is Standard-privacy"
        );
        let block = build_block_with_transfer(&pop, gov);
        let result = pop
            .verify_block(
                &block,
                &FxHashSet::default(),
                DEFAULT_ORACLE_QUORUM.max(1),
                &[],
            )
            .await
            .unwrap();
        assert!(
            result,
            "sync path must ACCEPT a Standard-privacy governance Transfer under the \
             default policy (producer/sync parity #1728)"
        );
    }

    #[tokio::test]
    async fn parity_governance_transfer_exempt_from_privacy_under_raised_floor() {
        // SYNC side with a governance-RAISED floor (High): a system/governance
        // transparent Transfer (effective=Standard, with valid governance
        // provenance) must STILL be accepted. The privacy exemption is separate
        // from sender-bound transparent authorization (#1786).
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        pop.set_privacy_policy(PrivacyPolicy {
            min_privacy_level: PrivacyLevel::High,
            privacy_enforcement_activation_height: 0,
        });

        let authority = "governance-privacy-floor";
        let authority_key = governance_transfer_key(1_786_001);
        let authority_pubkey = PublicKey::from_private_key(&authority_key).to_hex();
        let registry = governance_operator_registry(authority, &authority_pubkey);
        pop.set_oracle_signing_keys(registry.clone());

        let to = Address::new([0x22u8; 20]).to_hex();
        let mut gov =
            build_governance_transparent_transfer(&governance_transfer_key(1729), &to, 100, 0);
        assert!(gov.verify_transparent_transfer_authorization());
        gov.sign_system_authority(authority, &authority_key)
            .expect("governance provenance signs");
        assert!(
            gov.verify_system_authority(&registry),
            "precondition: raised-floor exemption requires governance provenance"
        );
        let block = build_block_with_transfer(&pop, gov);
        let result = pop
            .verify_block(
                &block,
                &FxHashSet::default(),
                DEFAULT_ORACLE_QUORUM.max(1),
                &[],
            )
            .await
            .unwrap();
        assert!(
            result,
            "system/governance Transfer must be exempt from the privacy gate even \
             under a governance-raised floor (#1728)"
        );
    }

    #[tokio::test]
    async fn parity_user_transparent_transfer_rejected_under_raised_floor_without_system_authority() {
        // #1786: a user can authorize debiting their transparent account, but
        // that from-bound authorization is not a system/governance provenance
        // proof and must not bypass a governance-raised privacy floor.
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        pop.set_privacy_policy(PrivacyPolicy {
            min_privacy_level: PrivacyLevel::High,
            privacy_enforcement_activation_height: 0,
        });

        let to = Address::new([0x22u8; 20]).to_hex();
        let user = build_governance_transparent_transfer(
            &governance_transfer_key(1_786_002),
            &to,
            100,
            0,
        );
        assert!(
            user.verify_transparent_transfer_authorization(),
            "precondition: user transparent transfer is validly from-authorized"
        );
        assert!(
            !user.claims_system_authority(),
            "precondition: user transparent transfer carries no governance provenance"
        );

        let block = build_block_with_transfer(&pop, user);
        let result = pop
            .verify_block(
                &block,
                &FxHashSet::default(),
                DEFAULT_ORACLE_QUORUM.max(1),
                &[],
            )
            .await
            .unwrap();
        assert!(
            !result,
            "from-authorized user transparent Transfer must not bypass a raised \
             privacy floor without governance/system authority (#1786)"
        );
    }

    #[tokio::test]
    async fn parity_user_too_low_privacy_still_rejected_on_sync_under_raised_floor() {
        // SYNC side, negative parity: a *user* ConfidentialTransfer that opts into
        // a privacy level BELOW a governance-raised floor must STILL be rejected.
        // The #1728 fix must not weaken real privacy enforcement for user txs.
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        pop.set_privacy_policy(PrivacyPolicy {
            min_privacy_level: PrivacyLevel::High,
            privacy_enforcement_activation_height: 0,
        });

        // Basic < High, and a ConfidentialTransfer is not a transparent
        // Transfer with verified system/governance authority, so the gate
        // applies.
        let user_ct = make_confidential_transfer(PrivacyLevel::Basic, "user-too-low");
        assert!(
            !user_ct.verify_transparent_transfer_authorization(),
            "precondition: a ConfidentialTransfer is not transparent-authorized"
        );
        let coinbase = Transaction::new_coinbase("miner", adjusted_block_reward(5), 5);
        let txs = vec![coinbase, user_ct];
        let score = pop.calculate_block_publishing_score(&txs, 5);
        let mut block = Block::new(3, Hash::default(), txs, 1, 5);
        block
            .metadata
            .insert("publishing_score".to_string(), score.to_string());

        let result = pop
            .verify_block(
                &block,
                &FxHashSet::default(),
                DEFAULT_ORACLE_QUORUM.max(1),
                &[],
            )
            .await
            .unwrap();
        assert!(
            !result,
            "sync path must STILL REJECT a user ConfidentialTransfer below a raised \
             privacy floor — #1728 must not weaken real privacy enforcement"
        );
    }

    #[test]
    fn privacy_policy_governance_update() {
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        // Default floor is Standard (#1728): the no-op floor that a default-privacy
        // tx always satisfies, keeping the sync-only privacy gate symmetric with the
        // producer. Governance can still raise it.
        assert_eq!(
            pop.privacy_policy.min_privacy_level,
            PrivacyLevel::Standard
        );

        pop.set_privacy_policy(PrivacyPolicy {
            min_privacy_level: PrivacyLevel::High,
            privacy_enforcement_activation_height: 500,
        });

        assert_eq!(pop.privacy_policy.min_privacy_level, PrivacyLevel::High);
        assert_eq!(
            pop.privacy_policy.privacy_enforcement_activation_height,
            500
        );
    }

