    /// Helper: create a signed ComputeReceipt with the given work_factor.
    fn make_compute_receipt(work_factor: u64) -> crate::blockchain::transaction::ComputeReceipt {
        let mut rng = StdRng::seed_from_u64(9999);
        let private_key = PrivateKey::generate(&mut rng);
        let worker_id = PublicKey::from_private_key(&private_key).to_string();

        let mut receipt = crate::blockchain::transaction::ComputeReceipt {
            task_id: "task-001".to_string(),
            worker_id,
            work_hash: "c".repeat(64),
            work_factor,
            completed_at: 1_700_000_000,
            nonce: "compute-nonce-001".to_string(),
            signature: None,
        };
        let message = receipt.signing_message();
        let signature = private_key.sign(message.as_bytes()).to_string();
        receipt.signature = Some(signature);
        receipt
    }

    /// Helper: create a ForecastReveal tx with fee=0 and an optional compute receipt.
    fn make_zero_fee_forecast_reveal(
        compute_receipt: Option<crate::blockchain::transaction::ComputeReceipt>,
    ) -> Transaction {
        let payload = crate::blockchain::transaction::RevealPayload {
            commit_id: "commit-comp-001".to_string(),
            station_id: "station-comp-001".to_string(),
            timestamp: 1000,
            contribution_type: "forecast".to_string(),
            data: serde_json::json!({}),
            nonce: "nonce-comp-001".to_string(),
            data_cid: None,
            data_hash: None,
            storage_provider: None,
            provenance: None,
            manifest: None,
            verification_receipt: None,
            compute_receipt,
            quality_tier: None,
        };
        let mut tx = Transaction::new_coinbase("miner", 1, 1);
        tx.tx_type = TransactionType::ForecastReveal;
        tx.fee = 0;
        tx.data = Some(serde_json::to_string(&payload).unwrap());
        tx
    }

    /// Helper: build a block that will pass publishing-score and quality checks.
    /// Uses min_publishing_score=0.0 to bypass liveness path.
    fn computational_fee_test_block(txs: Vec<Transaction>, height: u64) -> Block {
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        let coinbase = Transaction::new_coinbase("miner", adjusted_block_reward(height), height);
        let txs = std::iter::once(coinbase)
            .chain(txs.into_iter())
            .collect::<Vec<_>>();
        let score = pop.calculate_block_publishing_score(&txs, height);
        let mut block = Block::new(3, Hash::default(), txs, 1, height);
        block
            .metadata
            .insert("publishing_score".to_string(), score.to_string());
        block
    }

