    /// #1730 — producer/sync unification: the producer self-screen and the sync
    /// verifier share ONE per-transaction validator
    /// (`classify_block_transaction`), so the transaction the verifier rejects
    /// is exactly the one the producer drops. Concretely: a zero-fee weather tx
    /// with no compute receipt (floor > 0) makes `verify_block` reject the whole
    /// block; screening with the shared helper drops exactly that tx; and the
    /// screened (coinbase-only) block then passes `verify_block`. This is the
    /// invariant that prevents the producer from building a block peers reject.
    #[tokio::test]
    async fn producer_screen_drops_exactly_what_sync_rejects() {
        // Serialize against #1487 env-override tests; unset env → floor = 1000.
        let _g = MIN_WORK_FACTOR_ENV_GUARD.lock().unwrap_or_else(|p| p.into_inner());
        unsafe {
            std::env::remove_var(MIN_WORK_FACTOR_ENV_VAR);
        }
        set_min_work_factor_floor_override_for_tests(None);

        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        let height = 5;
        let bad = make_zero_fee_forecast_reveal(None);
        let block = computational_fee_test_block(vec![bad], height);

        // 1. The sync verifier rejects the whole block.
        let verified = pop
            .verify_block(
                &block,
                &FxHashSet::default(),
                DEFAULT_ORACLE_QUORUM.max(1),
                &[],
            )
            .await
            .unwrap();
        assert!(
            !verified,
            "sync verifier must reject a block carrying a no-receipt zero-fee weather tx"
        );

        // 2. The producer self-screen drops exactly the offending tx, keeping
        //    the coinbase — using the SAME shared per-tx validator.
        let empty_ids: FxHashSet<String> = FxHashSet::default();
        let ctx = BlockTxValidationCtx {
            height,
            block_time: block.timestamp.timestamp() as u64,
            check_quality: height
                >= pop
                    .data_quality_policy
                    .quality_enforcement_activation_height,
            check_privacy: height >= pop.privacy_policy.privacy_enforcement_activation_height,
            check_compute_fee: height >= COMPUTATIONAL_FEE_ACTIVATION_HEIGHT,
            check_disclosure: false,
            check_tx_signatures: height >= TX_SIGNATURE_VERIFICATION_ACTIVATION_HEIGHT,
            low_quality_quorum_commit_ids: &empty_ids,
            selective_disclosure_verifier_keys: &[],
        };
        let mut acc = BlockTxValidationAccumulators::default();
        let mut dropped = 0usize;
        for (i, tx) in block.transactions.iter().enumerate() {
            if i == 0 {
                continue; // coinbase is never screened
            }
            if pop.classify_block_transaction(&ctx, tx, i, &mut acc).is_some() {
                dropped += 1;
            }
        }
        assert_eq!(
            dropped, 1,
            "the screen must drop exactly the one tx the verifier rejects"
        );

        // 3. After dropping it, the (coinbase-only) block passes verification —
        //    the producer can emit it without any peer rejecting it.
        let screened_block = computational_fee_test_block(vec![], height);
        let screened_ok = pop
            .verify_block(
                &screened_block,
                &FxHashSet::default(),
                DEFAULT_ORACLE_QUORUM.max(1),
                &[],
            )
            .await
            .unwrap();
        assert!(
            screened_ok,
            "the screened block must pass the sync verifier (producer/sync parity, #1730)"
        );
    }

