    // --- Selective disclosure verification tests ---

    fn make_signed_disclosure(
        expires_at_block: u64,
        signing_key: &PrivateKey,
    ) -> SelectiveDisclosureProofPayload {
        let mut disclosure = SelectiveDisclosureProofPayload {
            disclosure_id: "sd-1".to_string(),
            scope: vec!["jurisdiction".to_string()],
            expires_at_block,
            disclosed_fields_hash: "deadbeef".to_string(),
            verifier_attestation: String::new(),
        };
        let digest = disclosure.binding_digest();
        disclosure.verifier_attestation = signing_key.sign(digest.as_bytes()).to_hex();
        disclosure
    }

    fn selective_disclosure_verifier_oracle_set(seed: u64) -> (PrivateKey, FxHashSet<String>) {
        let (verifier_sk, verifier_oracle_id) = oracle_identity(seed);
        let mut oracle_set = FxHashSet::default();
        oracle_set.insert(verifier_oracle_id);
        (verifier_sk, oracle_set)
    }

    fn build_confidential_tx(disclosures: Vec<SelectiveDisclosureProofPayload>) -> Transaction {
        let payload = ConfidentialTransferPayload {
            output_commitments: vec!["commit1".to_string()],
            range_proof: None,
            stealth_data: None,
            ring_signature: None,
            key_images: vec![],
            encrypted_payload: None,
            privacy_level: PrivacyLevel::Basic,
            selective_disclosures: disclosures,
            signed_message: None,
        };
        let mut tx = build_tx(
            TransactionType::ConfidentialTransfer,
            Some(&serde_json::to_string(&payload).unwrap()),
            "ct",
        );
        tx.tx_type = TransactionType::ConfidentialTransfer;
        tx
    }

    fn build_shielded_withdrawal_tx(
        disclosure: Option<SelectiveDisclosureProofPayload>,
    ) -> Transaction {
        let payload = ShieldedWithdrawalPayload {
            nullifier: "null1".to_string(),
            shielded_commitment: "sc1".to_string(),
            range_proof: "rp1".to_string(),
            transparent_recipient: "addr1".to_string(),
            transparent_amount: 100,
            authorization_proof: "ap1".to_string(),
            selective_disclosure: disclosure,
        };
        let mut tx = build_tx(
            TransactionType::ShieldedWithdrawal,
            Some(&serde_json::to_string(&payload).unwrap()),
            "sw",
        );
        tx.tx_type = TransactionType::ShieldedWithdrawal;
        tx
    }

    fn pop_for_sd_tests() -> ProofOfPublishing {
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        pop.set_pop_liveness_policy(PopLivenessPolicy {
            useful_work_activation_height: 0,
        })
        .unwrap();
        // Shielded withdrawal test payloads use short placeholder proofs.
        // Now that is_real_zk_proof_hex is removed, they pass through the
        // verifier, so use an accepting verifier.
        pop.set_zk_verifier(Arc::new(StaticWeatherVerifier(Ok(true))));
        pop
    }

    fn sd_block(height: u64, txs: Vec<Transaction>) -> Block {
        let mut block_txs = vec![Transaction::new_coinbase(
            "sd-miner",
            adjusted_block_reward(height),
            height,
        )];
        block_txs.extend(txs);
        let score = ProofOfPublishing::new(1, 60, 0, 10)
            .calculate_block_publishing_score(&block_txs, height);
        let mut block = Block::new(3, Hash::default(), block_txs, 1, height);
        block
            .metadata
            .insert("publishing_score".to_string(), format!("{score}"));
        block
    }

    #[tokio::test]
    async fn selective_disclosure_valid_proof_accepted() {
        let mut pop = pop_for_sd_tests();
        let (verifier_sk, oracle_set) = selective_disclosure_verifier_oracle_set(8_401);
        let disclosure = make_signed_disclosure(1000, &verifier_sk);
        let tx = build_confidential_tx(vec![disclosure]);
        let block = sd_block(5, vec![tx]);
        let result = pop
            .verify_block(&block, &oracle_set, DEFAULT_ORACLE_QUORUM.max(1), &[])
            .await
            .unwrap();
        assert!(
            result,
            "Block with valid selective disclosure should be accepted"
        );
    }

