    #[tokio::test]
    async fn selective_disclosure_invalid_attestation_rejected() {
        let mut pop = pop_for_sd_tests();
        let (verifier_sk, oracle_set) = selective_disclosure_verifier_oracle_set(8_403);
        let mut disclosure = make_signed_disclosure(1000, &verifier_sk);
        disclosure.verifier_attestation = "badhex".to_string();
        let tx = build_confidential_tx(vec![disclosure]);
        let block = sd_block(5, vec![tx]);
        let result = pop
            .verify_block(&block, &oracle_set, DEFAULT_ORACLE_QUORUM.max(1), &[])
            .await
            .unwrap();
        assert!(
            !result,
            "Block with invalid attestation in selective disclosure should be rejected"
        );
    }

