    /// #1762 fence audit: BOTH mempool entrypoints must reject, not just the
    /// thin wrapper.
    ///
    /// `add_transaction` is a one-line delegate to
    /// `add_transaction_with_signing_keys`, and the latter is what production
    /// actually calls (`launch_api/helpers.rs`, the P2P relay path). A test that
    /// exercises only the wrapper would stay green if the gate were moved *into*
    /// the wrapper, while every production caller leaked. Pin the real
    /// entrypoint explicitly rather than by delegation.
    #[test]
    fn both_mempool_entrypoints_reject_shielded_1762() {
        use crate::config::settings::Config;
        use crate::security::key_registry::SigningKeyRegistry;
        use crate::mempool::pool::Mempool;

        for (label, tx) in [
            ("ShieldedDeposit", build_shielded_deposit_tx()),
            ("ShieldedWithdrawal", build_shielded_withdrawal_tx(None)),
        ] {
            let mut via_wrapper = Mempool::new(&Config::default());
            assert!(
                via_wrapper.add_transaction(tx.clone()).is_err(),
                "[{label}] add_transaction must reject while the surface is disabled (#1762)"
            );

            let mut via_real = Mempool::new(&Config::default());
            let keys = SigningKeyRegistry::default();
            assert!(
                via_real
                    .add_transaction_with_signing_keys(tx.clone(), Some(&keys))
                    .is_err(),
                "[{label}] add_transaction_with_signing_keys — the entrypoint production \
                 uses — must reject independently of the wrapper (#1762)"
            ); // secret-leak-ok: test label names a public signing-key API, not key material
            assert!(
                via_real
                    .add_transaction_with_signing_keys(tx, None)
                    .is_err(),
                "[{label}] add_transaction_with_signing_keys(None) must reject too (#1762)"
            ); // secret-leak-ok: test label names a public signing-key API, not key material
        }
    }

    // --- verify_block oracle_set parameter regression tests ---

    /// Build a block whose publishing_score metadata reflects the score computed
    /// with the given oracle set authorised.  The caller controls which oracle
    /// set is used when computing the canonical score so the test can construct
    /// "authorised" and "empty-oracle" variants of the same block.
    fn make_oracle_receipt_block(
        commit_tx: Transaction,
        reveal_tx: Transaction,
        oracle_set: &FxHashSet<String>,
        height: u64,
    ) -> Block {
        let mut scoring_pop = ProofOfPublishing::new(1, 60, 0, 10);
        scoring_pop.set_authorized_oracles(oracle_set.clone());
        let coinbase = Transaction::new_coinbase("miner", adjusted_block_reward(height), height);
        let txs = vec![coinbase, commit_tx, reveal_tx];
        let score = scoring_pop.calculate_block_publishing_score(&txs, height);
        let mut block = Block::new(3, Hash::default(), txs, 1, height);
        block
            .metadata
            .insert("publishing_score".to_string(), score.to_string());
        block
    }

    /// Verify that `verify_block` uses the `oracle_set` parameter, not any
    /// previously-set `authorized_oracles` field.  If the parameter is the
    /// authoritative source, passing an empty set should cause a score
    /// mismatch (oracle receipt rejected → lower computed score) while
    /// passing the correct oracle set should accept the block.
    #[tokio::test]
    async fn verify_block_oracle_set_param_overrides_stale_field() {
        let (oracle_sk, oracle_id) = oracle_identity(999);
        let mut oracle_set = FxHashSet::default();
        oracle_set.insert(oracle_id.clone());

        // Pre-compute the actual commit_id hash that the helpers will use.
        // build_forecast_commit_reveal_with_manifest sets nonce = "nonce-{tag}".
        let tag = "vs";
        let data = serde_json::json!({"temperature": 20.0});
        let nonce = format!("nonce-{tag}");
        let station_id = "station-vs";
        let timestamp = 1_700_000_000i64;
        let commit_id =
            Transaction::compute_commit_id(&data, &nonce, station_id, timestamp, "forecast");

        let manifest = test_manifest();
        // Receipt uses the actual commit_id hash — must match payload.commit_id.
        let receipt = test_receipt_with_key(&oracle_sk, &oracle_id, &manifest, &commit_id, 0.9);
        let (commit_tx, mut reveal_tx, _) = build_forecast_commit_reveal_with_manifest(
            station_id,
            timestamp,
            data,
            Some(manifest),
            Some(receipt),
            tag,
        );
        // Non-zero fee so the zero-fee compute-receipt check in
        // verify_block_transactions_fused does not reject the reveal.
        reveal_tx.fee = 1000;

        // Block metadata score is computed WITH the oracle authorized.
        let block = make_oracle_receipt_block(commit_tx, reveal_tx, &oracle_set, 5);

        // Pop with stale authorized_oracles = oracle_set (simulates old code path
        // where a caller had previously synced the set but the parameter was absent).
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        pop.set_authorized_oracles(oracle_set.clone());

        // Call 1: pass EMPTY oracle set.  Oracle is NOT authorized in the
        // re-computation → calculated score (base×BASELINE) < metadata score
        // (base×skill) → mismatch → false.  Proves the parameter wins over the
        // stale field.
        let empty: FxHashSet<String> = FxHashSet::default();
        let rejected = pop
            .verify_block(&block, &empty, DEFAULT_ORACLE_QUORUM.max(1), &[])
            .await
            .unwrap();
        assert!(
            !rejected,
            "verify_block with empty oracle_set must reject block whose score \
             was computed with oracle authorized (score mismatch proves the \
             parameter, not the stale field, is used)"
        );

        // Call 2: pass the CORRECT oracle set on the SAME block.  Oracle IS
        // authorized → calculated score matches → true.
        let accepted = pop
            .verify_block(&block, &oracle_set, DEFAULT_ORACLE_QUORUM.max(1), &[])
            .await
            .unwrap();
        assert!(
            accepted,
            "verify_block with correct oracle_set should accept the block"
        );
    }

