    #[test]
    fn adjust_difficulty_is_deterministic() {
        // Two independent instances with identical config must converge on
        // identical difficulty + min_publishing_score when fed the same
        // block timestamps — proving the adjustment is a pure function of
        // chain state, not wall-clock time.
        let mut pop_a = ProofOfPublishing::new(1, 14400, 3_000_000, 500);
        let mut pop_b = ProofOfPublishing::new(1, 14400, 3_000_000, 500);

        // Process 2100 blocks (just past one ADJUSTMENT_INTERVAL = 2016)
        for i in 0..2100u64 {
            let ts = 1_700_000_000i64 + (i as i64) * 14400; // deterministic timestamps
            pop_a.blocks_since_adjustment += 1;
            pop_a.adjust_difficulty(i, ts);
            pop_b.blocks_since_adjustment += 1;
            pop_b.adjust_difficulty(i, ts);
        }

        assert_eq!(
            pop_a.difficulty, pop_b.difficulty,
            "difficulty must be identical across independent instances"
        );
        assert_eq!(
            pop_a.min_publishing_score, pop_b.min_publishing_score,
            "min_publishing_score must be identical across independent instances"
        );
    }

    #[test]
    fn adjust_difficulty_first_call_initializes_timestamp() {
        let mut pop = ProofOfPublishing::new(1, 14400, 3_000_000, 500);
        assert!(pop.last_adjustment_timestamp.is_none());
        pop.adjust_difficulty(0, 1_700_000_000i64);
        assert_eq!(pop.last_adjustment_timestamp, Some(1_700_000_000i64));
        // Should not have adjusted yet (just initialized)
        assert_eq!(pop.difficulty, 1);
    }

    #[test]
    fn adjust_difficulty_half_step_boundary_uses_integer_math_1875() {
        // Regression for #1875: the fine-tuning `else` branch previously used
        // `(self.difficulty as f64 / ratio).round() as u32`, which is
        // non-deterministic across FPU implementations (x86 80-bit extended
        // precision vs ARM IEEE-754 double can differ by ±1 ulp near integer
        // boundaries).  The fix uses pure integer arithmetic:
        //   new_difficulty = (difficulty * expected_secs) / elapsed_secs
        //
        // This test pins the exact branch boundary between "somewhat fast"
        // (elapsed * 2 < expected → difficulty * 2) and the "fine-tuning" else
        // branch (elapsed * 2 == expected → integer division).
        //
        // ADJUSTMENT_INTERVAL = 2016.  At height 0, target = 14 400 s.
        //   expected_secs = 14 400 × 2016 = 29 030 400.
        //   half-step     = expected / 2  = 14 515 200.
        //
        // At half - 1: elapsed * 2 = expected - 2 < expected → "somewhat fast"
        // At half    : elapsed * 2 = expected     → NOT < expected → else branch
        const INTERVAL: u64 = 2016;
        let height: u64 = 0;
        let target = compute_target_block_time(height); // 14_400 s
        let expected = target * INTERVAL;               // 29_030_400 s
        let half = expected / 2;                        // 14_515_200 s (exact: expected is even)

        let init_diff: u32 = 1_000_000;
        let base_ts: i64 = 1_700_000_000;

        // ── One tick below the half-step: "somewhat fast" branch, difficulty * 2 ─
        {
            let mut pop = ProofOfPublishing::new(init_diff, target, 3_000_000, 500);
            pop.last_adjustment_timestamp = Some(base_ts);
            pop.blocks_since_adjustment = INTERVAL;
            // elapsed = half - 1 → (half-1)*2 = expected-2 < expected → TRUE
            pop.adjust_difficulty(height, base_ts + (half - 1) as i64);
            assert_eq!(
                pop.difficulty,
                init_diff.saturating_mul(2),
                "#1875: elapsed = half−1 must take the 'somewhat fast' branch (difficulty × 2)"
            );
        }

        // ── Exactly at the half-step: integer fine-tuning branch ─────────────────
        // elapsed = half → half*2 = expected → NOT < expected → else
        // Integer result: (init_diff * expected) / half = 2 * init_diff (exact)
        {
            let mut pop = ProofOfPublishing::new(init_diff, target, 3_000_000, 500);
            pop.last_adjustment_timestamp = Some(base_ts);
            pop.blocks_since_adjustment = INTERVAL;
            pop.adjust_difficulty(height, base_ts + half as i64);
            let expected_diff =
                ((init_diff as u128 * expected as u128) / half as u128) as u32;
            // Since expected = 2 * half, expected_diff = 2 * init_diff exactly.
            assert_eq!(expected_diff, init_diff * 2, "sanity: integer division should give 2×");
            assert_eq!(
                pop.difficulty,
                expected_diff.max(1),
                "#1875: at exact half-step boundary, integer division must yield {expected_diff} \
                 (= 2 × init_diff); f64 round() could have given a different result here"
            );
        }
    }

