    #[tokio::test]
    async fn empty_liveness_block_has_reduced_coinbase() {
        let config = Config::default();
        let miner = "wrf-econ-miner";

        let mut pop = ProofOfPublishing::new(1, 60, 1_000_000, 10);
        // #2523: this dev chain has no oracle ceremony. It must SAY so — a
        // block 1 that declares nothing is refused, which is the point.
        pop.declare_no_genesis_oracles();
        let chain = Arc::new(RwLock::new(Blockchain::default()));
        let mempool = Arc::new(RwLock::new(Mempool::new(&config)));

        let block = pop
            .create_next_block(chain.clone(), mempool.clone(), miner)
            .await
            .expect("empty-liveness block should be created");

        assert_eq!(
            block
                .metadata
                .get("useful_work_liveness_fallback")
                .map(String::as_str),
            Some("empty_liveness"),
        );

        let coinbase_amount = block.transactions[0].outputs[0].amount;
        // ADR-003 (#2846): the liveness fraction now reduces the PRODUCER SLICE,
        // not all of `E(t)` — the coinbase never was the whole emission under
        // the partition, so the #814 reduction composes with it rather than
        // replacing it. The property #814 pins is unchanged: an empty-liveness
        // block earns strictly less than a full one.
        let full_reward = EmissionForTests(&chain.read().await.state).coinbase_allowance(block.height) as u64;
        let expected = full_reward / LIVENESS_BLOCK_REWARD_FRACTION;

        assert_eq!(
            coinbase_amount, expected,
            "empty-liveness block should earn {} (10% of the coinbase slice {}), got {}",
            expected, full_reward, coinbase_amount
        );
        assert!(
            coinbase_amount < full_reward,
            "empty-liveness reward ({}) must be less than the full coinbase slice ({})",
            coinbase_amount,
            full_reward
        );
        assert!(
            (full_reward as u128) < adjusted_block_reward(block.height) as u128,
            "and the coinbase slice itself must be strictly under E(t) (#2846)"
        );
    }

    #[tokio::test]
    async fn verify_block_rejects_overpaid_empty_liveness() {
        let mut pop = ProofOfPublishing::new(1, 60, 1_000_000, 10);
        pop.set_pop_liveness_policy(PopLivenessPolicy {
            useful_work_activation_height: 0,
        })
        .unwrap();

        let height = 5u64;
        let full_reward = adjusted_block_reward(height);

        // Build a block with a full-reward coinbase but empty_liveness metadata
        let coinbase = Transaction::new_coinbase("wrf-cheater", full_reward, height);
        let mut block = Block::new(3, Hash::default(), vec![coinbase], 1, height);
        block
            .metadata
            .insert("publishing_score".to_string(), "0".to_string());
        block.metadata.insert(
            "useful_work_liveness_fallback".to_string(),
            "empty_liveness".to_string(),
        );

        let result = pop
            .verify_block(
                &block,
                &FxHashSet::default(),
                DEFAULT_ORACLE_QUORUM.max(1),
                &[],
            )
            .await
            .unwrap();
        assert!(
            !result,
            "empty-liveness block with full coinbase ({}) should be rejected",
            full_reward
        );
    }

