    #[test]
    fn publishing_score_uses_minimum_not_average() {
        let pop = ProofOfPublishing::new(1, 60, 0, 10);

        // Build oracle attestation transactions with known confidence scores.
        // OracleAttestation scoring: score = 2 * confidence (quantized).
        // We use different confidence values to produce different scores.
        let build_attestation = |confidence: f64, tag: &str| -> Transaction {
            let payload = serde_json::json!({
                "commit_id": format!("commit-{tag}"),
                "oracle_id": format!("oracle-{tag}"),
                "approved": true,
                "confidence": confidence,
                "timestamp": 1000
            });
            build_tx(
                TransactionType::OracleAttestation,
                Some(&payload.to_string()),
                tag,
            )
        };

        // Scores: 2 * confidence * SCORE_PRECISION
        // tx1: 2 * 0.5 = 1.0 * SCORE_PRECISION = 1_000_000
        // tx2: 2 * 0.3 = 0.6 * SCORE_PRECISION = 600_000
        // tx3: 2 * 0.1 = 0.2 * SCORE_PRECISION = 200_000
        // Old average: (1_000_000 + 600_000 + 200_000) / 3 = 600_000
        // New minimum: 200_000
        let txs = vec![
            build_attestation(0.5, "high"),
            build_attestation(0.3, "mid"),
            build_attestation(0.1, "low"),
        ];

        let score = pop.calculate_block_publishing_score(&txs, 1);

        // The minimum should be 200_000 (the lowest scoring tx)
        // The average would have been 600_000
        assert!(
            score < 600_000,
            "score should be minimum-based (< 600_000 average), got {score}"
        );
        assert_eq!(
            score,
            pop.calculate_block_publishing_score(&txs[2..], 1),
            "block score should equal the score of the lowest-scoring transaction"
        );
    }

    #[test]
    fn publishing_score_single_attested_reveal_equals_its_score() {
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);

        // A single attested contribution reveal should be the sole scored transaction,
        // so the block score equals that transaction's score.
        let (commit, reveal, commit_id) = build_commit_and_reveal(
            TransactionType::ContributionReveal,
            "station-single",
            "contribution",
            1_700_000_000,
            serde_json::json!({"quality":1.0,"volume":1.0,"uniqueness":1.0}),
            "single-reveal",
        );
        let att_a = build_attestation(&commit_id, true, "single-a");
        let att_b = build_attestation(&commit_id, true, "single-b");

        // Block with commit + reveal + 2 attestations
        let full_score = pop.calculate_block_publishing_score(
            &[commit.clone(), reveal.clone(), att_a.clone(), att_b.clone()],
            100,
        );
        assert!(
            full_score > 0,
            "attested contribution reveal should produce non-zero score"
        );

        // Score of just the two attestations (reveal is the only other scored tx)
        // The minimum should be the lowest of: reveal_score and att scores.
        let att_only_score = pop.calculate_block_publishing_score(&[att_a, att_b], 100);
        // Without a matching reveal, attestations score 0
        assert_eq!(
            att_only_score, 0,
            "attestations without matching reveal should score 0"
        );
    }

    #[test]
    fn publishing_score_no_publishing_txs_returns_zero() {
        let pop = ProofOfPublishing::new(1, 60, 0, 10);
        // Regular transactions don't contribute to publishing score
        let tx = build_tx(TransactionType::Transfer, None, "regular");
        let score = pop.calculate_block_publishing_score(&[tx], 1);
        assert_eq!(score, 0, "non-publishing transactions should yield score 0");
    }

