    // #809: Emission × block time alignment tests
    // -----------------------------------------------------------------------

    #[test]
    fn adjusted_reward_at_genesis_equals_base_reward() {
        // At genesis tier (height 0..999, block_time = 14400s), the adjustment
        // factor is 14400/14400 = 1.0, so adjusted == base.
        for height in [0, 1, 100, 999] {
            assert_eq!(
                adjusted_block_reward(height),
                base_block_reward(height),
                "at genesis-tier height {height}, adjusted should equal base"
            );
        }
    }

    #[test]
    fn adjusted_reward_decreases_with_faster_block_time() {
        // All values BASE UNITS (#2485). These read 2 / 12 / 25 before the
        // rescale — the whole-coin figures in the comments, minted as base units.

        // Height 25000 → block_time = 600s (10 min)
        // adjusted = 8e10 * 600 / 14400 = 3_333_333_333 (33.33… WRF)
        let reward_25k = adjusted_block_reward(25_000);
        assert_eq!(reward_25k, 3_333_333_333, "at 10-min blocks, reward ≈ 33.33 WRF");

        // Height 5000 → block_time = 3600s (1 hour)
        // adjusted = 8e10 * 3600 / 14400 = 20_000_000_000 (200 WRF)
        let reward_5k = adjusted_block_reward(5_000);
        assert_eq!(reward_5k, 200 * WRF_UNITS_PER_COIN, "at 1-hour blocks, reward is 200 WRF");

        // Height 1000 → block_time = 7200s (2 hours)
        // adjusted = 8e10 * 7200 / 14400 = 40_000_000_000 (400 WRF)
        let reward_1k = adjusted_block_reward(1_000);
        assert_eq!(
            reward_1k,
            400 * WRF_UNITS_PER_COIN,
            "at 2-hour blocks, reward is 400 WRF"
        );
    }

    #[test]
    fn daily_emission_approximately_constant() {
        // Daily emission = adjusted_reward × (86400 / block_time)
        // 300 WRF/day across all tiers (genesis = 50 WRF * 6 blocks). In BASE
        // UNITS that is 3e10 (#2485) — this asserted a bare 300/288 before the
        // rescale, i.e. 0.000003 WRF/day.
        const DAILY: u64 = 4_800 * WRF_UNITS_PER_COIN; // 480_000_000_000

        let genesis_daily = adjusted_block_reward(0) as u64 * 86_400 / 14_400;
        assert_eq!(genesis_daily, DAILY, "genesis daily emission");

        let h1k_daily = adjusted_block_reward(1_000) as u64 * 86_400 / 7_200;
        assert_eq!(h1k_daily, DAILY, "2-hour tier daily emission");

        // Now EXACTLY equal to genesis. At the old denomination the 12.5 WRF
        // tier reward floored to `12`, a 4% truncation error that showed up here
        // as 288 vs 300. With the reward in base units, 1_250_000_000 is exact
        // and the "approximately constant" claim becomes exact.
        let h5k_daily = adjusted_block_reward(5_000) as u64 * 86_400 / 3_600;
        assert_eq!(h5k_daily, DAILY, "1-hour tier daily emission");

        // 479_999_999_952 — 48 base units under, from flooring 3_333_333_333.33.
        let h25k_daily = adjusted_block_reward(25_000) as u64 * 86_400 / 600;
        assert_eq!(h25k_daily, 479_999_999_952, "10-min tier daily emission");

        // All within 5% of genesis
        for (label, daily) in [("2h", h1k_daily), ("1h", h5k_daily), ("10m", h25k_daily)] {
            let ratio = (daily as f64) / (genesis_daily as f64);
            assert!(
                ratio >= 0.90 && ratio <= 1.10,
                "{label} daily emission {daily} is {ratio:.2}x genesis — outside ±10%"
            );
        }
    }

    #[test]
    fn adjusted_reward_reaches_zero_after_terminal_reduction() {
        // #2492: the schedule terminates on WALL CLOCK, not a block count. The
        // reward floors to zero after 61 reductions, i.e. ~243.6 years — where
        // the block-count schedule died at year 9.2.
        //
        // u64::MAX heights must also terminate rather than loop or wrap.
        assert_eq!(
            base_block_reward(u64::MAX),
            0,
            "base reward must reach zero at the far end of the schedule"
        );
        assert_eq!(
            adjusted_block_reward(u64::MAX),
            0,
            "adjusted reward must also be zero once the base reward terminates"
        );
        // Height 10M is only ~9.8 years in and must still be minting.
        assert!(
            adjusted_block_reward(10_000_000) > 0,
            "height 10M is ~9.8 years in — emission must NOT be dead (#2492)"
        );
    }

    #[test]
    fn adjusted_reward_stacks_with_liveness_reduction() {
        // At height 25k: adjusted = 3_333_333_333, liveness = /10 = 333_333_333.
        // Before #2485 this was 2 and 0 — the liveness reward floored away
        // entirely, which the old comment recorded as "expected".
        let adjusted = adjusted_block_reward(25_000);
        let liveness_reward = adjusted / LIVENESS_BLOCK_REWARD_FRACTION;
        assert!(
            liveness_reward < adjusted,
            "liveness reward ({liveness_reward}) must be less than adjusted ({adjusted})"
        );
        // Verify stacking at genesis tier where both are meaningful
        let genesis_adjusted = adjusted_block_reward(5);
        let genesis_liveness = genesis_adjusted / LIVENESS_BLOCK_REWARD_FRACTION;
        assert_eq!(
            genesis_adjusted,
            800 * WRF_UNITS_PER_COIN,
            "genesis adjusted is the full 800 WRF"
        );
        assert_eq!(
            genesis_liveness,
            80 * WRF_UNITS_PER_COIN,
            "genesis liveness is 10% of 800 WRF"
        );
    }

