    #[tokio::test]
    async fn verify_block_accepts_under_claimed_coinbase_at_100k() {
        let mut pop = ProofOfPublishing::new(1, 60, 1_000_000, 10);
        pop.set_pop_liveness_policy(PopLivenessPolicy {
            useful_work_activation_height: 0,
        })
        .unwrap();

        // Was `verify_block_accepts_zero_coinbase_at_100k`, whose precondition
        // asserted `adjusted_block_reward(100_000) == 0` — the #2485 defect
        // pinned as a verifier invariant. The reward at 100k is now non-zero;
        // what this actually tests is that the verifier's coinbase check is an
        // UPPER bound, so a block claiming LESS than its entitlement still
        // verifies. That property is what makes the supply clamp in
        // `create_next_block` safe to apply without a mining/verify split.
        let height = 100_000u64;
        assert!(
            adjusted_block_reward(height) > 0,
            "precondition: reward must be non-zero at height 100K after #2485"
        );

        let coinbase = Transaction::new_coinbase("wrf-zero-miner", 0, height);
        let mut block = Block::new(3, Hash::default(), vec![coinbase], 1, height);
        block
            .metadata
            .insert("publishing_score".to_string(), "0".to_string());
        block.metadata.insert(
            "useful_work_liveness_fallback".to_string(),
            "empty_liveness".to_string(),
        );

        let result = pop
            .verify_block(
                &block,
                &FxHashSet::default(),
                DEFAULT_ORACLE_QUORUM.max(1),
                &[],
            )
            .await
            .unwrap();
        assert!(
            result,
            "zero-coinbase block at height {height} must be accepted — chain must not halt"
        );
    }

