    /// Serializes tests that exercise the cached min-work-factor override path
    /// so each test cleans up its own override state before the next one runs.
    static MIN_WORK_FACTOR_ENV_GUARD: std::sync::Mutex<()> = std::sync::Mutex::new(());

    #[test]
    fn effective_min_work_factor_at_genesis() {
        let _g = MIN_WORK_FACTOR_ENV_GUARD.lock().unwrap_or_else(|p| p.into_inner());
        unsafe { std::env::remove_var(MIN_WORK_FACTOR_ENV_VAR); }
        // Genesis tier (height 0..999, block_time = 14400s): factor = 1.0
        assert_eq!(effective_min_work_factor(0), 1_000);
        assert_eq!(effective_min_work_factor(999), 1_000);
    }

    #[test]
    fn effective_min_work_factor_scales_inversely() {
        let _g = MIN_WORK_FACTOR_ENV_GUARD.lock().unwrap_or_else(|p| p.into_inner());
        unsafe { std::env::remove_var(MIN_WORK_FACTOR_ENV_VAR); }
        // 2h blocks (height 1000): 1000 * 14400 / 7200 = 2000
        assert_eq!(effective_min_work_factor(1_000), 2_000);
        // 1h blocks (height 5000): 1000 * 14400 / 3600 = 4000
        assert_eq!(effective_min_work_factor(5_000), 4_000);
        // 10min blocks (height 25000): 1000 * 14400 / 600 = 24000
        assert_eq!(effective_min_work_factor(25_000), 24_000);
        // 2min blocks (height 100000): 1000 * 14400 / 120 = 120000
        assert_eq!(effective_min_work_factor(100_000), 120_000);
        // 1s blocks (height 10M): 1000 * 14400 / 1 = 14,400,000
        assert_eq!(effective_min_work_factor(10_000_000), 14_400_000);
    }

