    // -----------------------------------------------------------------------
    // TDD Round 12 — Lane B: Supply cap enforcement & emission bounds
    // -----------------------------------------------------------------------

    #[test]
    fn emission_curve_monotonically_decreases_with_height() {
        let heights: [u64; 9] = [0, 1, 100, 1000, 5000, 10000, 25000, 50000, 100000];

        // Genesis reward equals base reward (adjustment factor is 1.0 at height 0).
        assert_eq!(
            adjusted_block_reward(0),
            base_block_reward(0),
            "genesis adjusted reward must equal base reward"
        );
        assert_eq!(
            adjusted_block_reward(0),
            800 * WRF_UNITS_PER_COIN,
            "genesis reward must be 800 WRF, in base units (#2485/#2492)"
        );

        // Monotonically non-increasing across the sampled heights.
        for window in heights.windows(2) {
            let (h_low, h_high) = (window[0], window[1]);
            assert!(
                adjusted_block_reward(h_low) >= adjusted_block_reward(h_high),
                "emission must be non-increasing: reward at height {h_low} ({}) < reward at height {h_high} ({})",
                adjusted_block_reward(h_low),
                adjusted_block_reward(h_high),
            );
        }

        // The third site that pinned the #2485 zero-cliff as intended behaviour
        // (with `adjusted_block_reward_zero_at_block_time_cliff` and
        // `verify_block_*_coinbase_at_100k`). Inverted: emission must SURVIVE the
        // 2-minute tier. `5e9 * 120 / 14_400 = 41_666_666`.
        assert_eq!(
            adjusted_block_reward(100_000),
            444_444_444,
            "emission must survive the 2-minute tier — the 100k zero-cliff was \
             the defect, not the design (#2485)"
        );

        // Every sampled reward is <= the genesis maximum.
        let genesis_reward = adjusted_block_reward(0);
        for &h in &heights {
            assert!(
                adjusted_block_reward(h) <= genesis_reward,
                "reward at height {h} ({}) exceeds genesis reward ({genesis_reward})",
                adjusted_block_reward(h),
            );
        }
    }

    #[test]
    fn max_supply_constant_matches_21m_coins_extended() {
        // Core constant value.
        assert_eq!(MAX_SUPPLY, 2_100_000_000_000_000u128);

        // Derivation: 21 million whole coins × 10^8 base units per coin.
        let units_per_coin: u128 = 100_000_000;
        assert_eq!(
            MAX_SUPPLY,
            21_000_000u128 * units_per_coin,
            "MAX_SUPPLY must equal 21M × 10^8"
        );
        assert_eq!(
            MAX_SUPPLY / units_per_coin,
            21_000_000,
            "MAX_SUPPLY in whole coins must be exactly 21 million"
        );

        // MAX_BLOCK_EMISSION sanity: 3_200 coins × 10^8 (#2492 — 4x the 800 WRF
        // genesis reward, preserving the headroom ratio the old 200-vs-50 pair
        // encoded).
        assert_eq!(MAX_BLOCK_EMISSION, 3_200u128 * units_per_coin);
    }

    #[test]
    fn reward_budget_calculation_caps_at_remaining_supply() {
        // Simulate near-cap conditions: only 50 base units remain before hitting
        // the 21M hard cap.  The budget formula from process_contribution_rewards
        // must clamp total rewards to the remaining supply.
        let max_supply: u128 = MAX_SUPPLY;
        let current_supply: u128 = max_supply - 50;
        let remaining = max_supply.saturating_sub(current_supply);
        assert_eq!(remaining, 50, "remaining supply must be 50 base units");

        // Simulate a typical coinbase (e.g. 5 base units for a liveness block).
        let coinbase_amount: u128 = 5;
        let budget = MAX_BLOCK_EMISSION
            .saturating_sub(coinbase_amount)
            .min(remaining);
        assert_eq!(
            budget, 50,
            "reward budget must be clamped to remaining supply (50)"
        );

        // When remaining is zero, budget must also be zero regardless of coinbase.
        let remaining_zero = max_supply.saturating_sub(max_supply);
        let budget_zero = MAX_BLOCK_EMISSION.saturating_sub(0).min(remaining_zero);
        assert_eq!(budget_zero, 0, "at max supply, reward budget must be 0");

        // When remaining exceeds MAX_BLOCK_EMISSION − coinbase, the emission cap
        // takes precedence.
        let large_remaining: u128 = MAX_BLOCK_EMISSION * 10;
        let budget_large = MAX_BLOCK_EMISSION
            .saturating_sub(coinbase_amount)
            .min(large_remaining);
        assert_eq!(
            budget_large,
            MAX_BLOCK_EMISSION - coinbase_amount,
            "with ample remaining supply, budget equals MAX_BLOCK_EMISSION minus coinbase"
        );
    }

    #[test]
    fn adjusted_block_reward_never_exceeds_max_emission() {
        let heights: [u64; 19] = [
            0, 1, 10, 100, 500, 1000, 2000, 5000, 10000, 20000, 50000, 75000, 99999, 100000,
            200000, 500000, 1000000, 5000000, 10000000,
        ];
        let genesis_reward = adjusted_block_reward(0);

        for &h in &heights {
            let reward = adjusted_block_reward(h);

            // No height ever exceeds the genesis maximum.
            assert!(
                reward <= genesis_reward,
                "adjusted_block_reward({h}) = {reward} exceeds genesis max ({genesis_reward})"
            );

            // Determinism: calling twice must yield the same result.
            let reward_again = adjusted_block_reward(h);
            assert_eq!(
                reward, reward_again,
                "adjusted_block_reward({h}) is not deterministic: {reward} vs {reward_again}"
            );
        }
    }

