    #[test]
    fn compute_receipt_validation_accepts_dynamic_threshold() {
        let _g = MIN_WORK_FACTOR_ENV_GUARD.lock().unwrap_or_else(|p| p.into_inner());
        unsafe { std::env::remove_var(MIN_WORK_FACTOR_ENV_VAR); }
        // Directly verify that a compute receipt meeting the dynamic threshold passes
        // the work_factor check at various heights.
        for (height, expected_min) in [
            (0u64, 1_000u64),
            (1_000, 2_000),
            (25_000, 24_000),
            (100_000, 120_000),
        ] {
            let min_wf = effective_min_work_factor(height);
            assert_eq!(min_wf, expected_min, "at height {height}");

            // A receipt AT the threshold should pass
            let receipt = make_compute_receipt(min_wf);
            assert!(
                receipt.work_factor >= min_wf,
                "receipt at threshold should pass at height {height}"
            );

            // A receipt BELOW the threshold should fail
            if min_wf > 0 {
                assert!(
                    min_wf - 1 < min_wf,
                    "receipt below threshold should fail at height {height}"
                );
            }
        }
    }

    #[tokio::test]
    async fn verify_block_rejects_feeless_tx_cap_exceeded() {
        let _g = MIN_WORK_FACTOR_ENV_GUARD.lock().unwrap_or_else(|p| p.into_inner());
        unsafe { std::env::remove_var(MIN_WORK_FACTOR_ENV_VAR); }
        // Use terminal height (1s blocks) where the cap equals the base constant.
        let terminal_height = 10_000_000;
        let cap = max_feeless_tx_per_block(terminal_height);
        assert_eq!(
            cap, BASE_FEELESS_TX_PER_BLOCK,
            "terminal cap should equal base"
        );

        let mut pop = ProofOfPublishing::new(1, 60, 0, cap + 10);

        // Build cap + 1 fee-less txs to exceed the cap.
        let txs: Vec<Transaction> = (0..=cap)
            .map(|i| {
                let receipt = make_compute_receipt(effective_min_work_factor(terminal_height));
                let mut tx = make_zero_fee_forecast_reveal(Some(receipt));
                // Each tx needs a unique id
                tx.data = Some(format!(
                    r#"{{"commit_id":"feeless-{i}","station_id":"s1","timestamp":1700000000,"contribution_type":"forecast"}}"#
                ));
                tx.set_id();
                tx
            })
            .collect();

        let block = computational_fee_test_block(txs, terminal_height);

        let result = pop
            .verify_block(
                &block,
                &FxHashSet::default(),
                DEFAULT_ORACLE_QUORUM.max(1),
                &[],
            )
            .await
            .unwrap();
        assert!(
            !result,
            "block with {} fee-less txs should be rejected (cap={})",
            cap + 1,
            cap
        );
    }

    // -----------------------------------------------------------------------
    // #835: Per-worker fee-less spam rate limiting
    // -----------------------------------------------------------------------

    /// Helper: create a signed ComputeReceipt for a specific worker (deterministic per seed).
    fn make_compute_receipt_for_worker(
        seed: u64,
        work_factor: u64,
    ) -> crate::blockchain::transaction::ComputeReceipt {
        let mut rng = StdRng::seed_from_u64(seed);
        let private_key = PrivateKey::generate(&mut rng);
        let worker_id = PublicKey::from_private_key(&private_key).to_string();

        let mut receipt = crate::blockchain::transaction::ComputeReceipt {
            task_id: format!("task-{seed}"),  // secret-copy-ok: `seed` is a test loop counter, not key material // secret-leak-ok: test loop counter, not key material
            worker_id,
            work_hash: "c".repeat(64),
            work_factor,
            completed_at: 1_700_000_000,
            nonce: format!("compute-nonce-{seed}"),  // secret-copy-ok: `seed` is a test loop counter, not key material // secret-leak-ok: test loop counter, not key material
            signature: None,
        };
        let message = receipt.signing_message();
        let signature = private_key.sign(message.as_bytes()).to_string();
        receipt.signature = Some(signature);
        receipt
    }

    /// Helper: create a fee-less ForecastReveal with a specific worker and commit_id.
    fn make_zero_fee_reveal_with_worker(
        worker_seed: u64,
        commit_id: &str,
        work_factor: u64,
    ) -> Transaction {
        let receipt = make_compute_receipt_for_worker(worker_seed, work_factor);
        let payload = crate::blockchain::transaction::RevealPayload {
            commit_id: commit_id.to_string(),
            station_id: format!("station-{worker_seed}"),  // secret-copy-ok: worker_seed is a deterministic test index // secret-leak-ok: test loop counter, not key material
            timestamp: 1000,
            contribution_type: "forecast".to_string(),
            data: serde_json::json!({}),
            nonce: format!("nonce-{commit_id}"),
            data_cid: None,
            data_hash: None,
            storage_provider: None,
            provenance: None,
            manifest: None,
            verification_receipt: None,
            compute_receipt: Some(receipt),
            quality_tier: None,
        };
        // Use amount=0 so the coinbase-amount validation (#809) does not reject
        // the block — adjusted_block_reward(5) = 50 and we only care about the
        // fee-less rate-limit checks in these tests.
        let mut tx = Transaction::new_coinbase("miner", 0, 1);
        tx.tx_type = TransactionType::ForecastReveal;
        tx.fee = 0;
        tx.outputs.clear();
        tx.data = Some(serde_json::to_string(&payload).unwrap());
        tx.set_id();
        tx
    }

