    // -----------------------------------------------------------------------
    // #811: Oracle quorum hardening — BFT 2/3+1
    // -----------------------------------------------------------------------

    #[test]
    fn compute_oracle_quorum_at_various_sizes() {
        // 0 oracles → max(2, 0+1) = 2 (minimum floor)
        assert_eq!(compute_oracle_quorum(0), 2);
        // 1 oracle → max(2, 0+1) = 2
        assert_eq!(compute_oracle_quorum(1), 2);
        // 2 oracles → max(2, 1+1) = 2
        assert_eq!(compute_oracle_quorum(2), 2);
        // 3 oracles → max(2, 2+1) = 3 (unanimous)
        assert_eq!(compute_oracle_quorum(3), 3);
        // 4 oracles → max(2, 2+1) = 3
        assert_eq!(compute_oracle_quorum(4), 3);
        // 6 oracles → max(2, 4+1) = 5
        assert_eq!(compute_oracle_quorum(6), 5);
        // 12 oracles → max(2, 8+1) = 9
        assert_eq!(compute_oracle_quorum(12), 9);
        // 100 oracles → max(2, 66+1) = 67
        assert_eq!(compute_oracle_quorum(100), 67);
    }

    #[test]
    fn compute_oracle_quorum_always_at_least_two() {
        for n in 0..=100 {
            assert!(
                compute_oracle_quorum(n) >= 2,
                "quorum for {n} oracles must be >= 2, got {}",
                compute_oracle_quorum(n)
            );
        }
    }

    #[test]
    fn compute_oracle_quorum_never_exceeds_set_size_beyond_minimum() {
        // For N >= 2, quorum should not exceed N (you can't require more votes
        // than you have oracles, except for the N=1 case where we cap at 2).
        for n in 2..=100 {
            assert!(
                compute_oracle_quorum(n) <= n,
                "quorum {} exceeds set size {n}",
                compute_oracle_quorum(n)
            );
        }
    }

    #[test]
    fn dynamic_quorum_in_collect_quorum_approved_commit_ids() {
        let pop = ProofOfPublishing::new(1, 60, 0, 10);

        // Build a commit with 2 oracle attestations (the old static quorum).
        let (_, _, commit_id) = build_commit_and_reveal(
            TransactionType::ContributionReveal,
            "station-quorum-test",
            "contribution",
            1_700_000_000,
            serde_json::json!({"quality":1.0,"volume":1.0,"uniqueness":1.0}),
            "quorum-test",
        );
        let att_a = build_attestation(&commit_id, true, "quorum-oracle-a");
        let att_b = build_attestation(&commit_id, true, "quorum-oracle-b");
        let txs = vec![att_a, att_b];

        // With static quorum=2, 2 attestations should suffice
        let approved_static = pop.collect_quorum_approved_commit_ids(&txs, 2, None, None);
        assert!(
            approved_static.contains(&commit_id),
            "2 attestations should meet static quorum of 2"
        );

        // With 12 oracles, dynamic quorum=9 → 2 attestations are insufficient
        let quorum_12 = compute_oracle_quorum(12);
        assert_eq!(quorum_12, 9);
        let approved_dynamic =
            pop.collect_quorum_approved_commit_ids(&txs, quorum_12, None, None);
        assert!(
            !approved_dynamic.contains(&commit_id),
            "2 attestations should NOT meet dynamic quorum of 9 (12 oracles)"
        );
    }

    // -----------------------------------------------------------------------
    // #962: verify_block rejection paths — role rewards + feeless-no-receipt
    // -----------------------------------------------------------------------

    /// Verify that a block whose `reward_<role>` metadata is inconsistent with
    /// the claimed coinbase amount is rejected via `verify_role_based_rewards`.
    #[tokio::test]
    async fn verify_block_rejects_invalid_role_based_rewards() {
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);

        // Configure roles summing to 1.0 (validation requirement).
        // Collector=0.7, Analyzer=0.3. We'll corrupt the collector entry.
        let mut role_map = std::collections::BTreeMap::new();
        role_map.insert(PublishingRole::Collector, 0.7_f64);
        role_map.insert(PublishingRole::Analyzer, 0.3_f64);
        pop.set_role_reward_percentages(role_map).unwrap();

        let height = 5u64;
        let reward = adjusted_block_reward(height); // 50 WRF-units at genesis tier
        let coinbase = Transaction::new_coinbase("wrf-role-cheater", reward, height);

        // Use a single coinbase so score=0 ≥ min_publishing_score=0 — no liveness path.
        let txs = vec![coinbase];
        let mut pop_score = ProofOfPublishing::new(1, 60, 0, 10);
        let score = pop_score.calculate_block_publishing_score(&txs, height);

        let mut block = Block::new(3, Hash::default(), txs, 1, height);
        block
            .metadata
            .insert("publishing_score".to_string(), score.to_string());

        // Inject a wildly incorrect collector reward (correct would be 50*0.7=35).
        // Note: str::parse::<u64>() does NOT accept underscores, so write the
        // literal without them.
        block
            .metadata
            .insert("reward_collector".to_string(), "999999999".to_string());

        let result = pop
            .verify_block(
                &block,
                &FxHashSet::default(),
                DEFAULT_ORACLE_QUORUM.max(1),
                &[],
            )
            .await
            .unwrap();
        assert!(
            !result,
            "block with incorrect role reward metadata must be rejected by \
             verify_role_based_rewards"
        );
    }

    // #1282: verify_role_based_rewards must require exact match, not ±1 tolerance.
    // -----------------------------------------------------------------------

    /// Helper: build a PoP with Collector=0.7 / Analyzer=0.3 and return both
    /// the configured engine and the expected per-role rewards at `height`.
    fn build_pop_with_roles_and_rewards(
        height: u64,
    ) -> (ProofOfPublishing, u64, u64, u64) {
        let mut pop = ProofOfPublishing::new(1, 60, 0, 10);
        let mut role_map = std::collections::BTreeMap::new();
        role_map.insert(PublishingRole::Collector, 0.7_f64);
        role_map.insert(PublishingRole::Analyzer, 0.3_f64);
        pop.set_role_reward_percentages(role_map).unwrap();

        let total_reward = adjusted_block_reward(height);
        // Mirror the integer arithmetic in apply_role_based_rewards / verify_role_based_rewards.
        let collector_ppm = (0.7_f64 * crate::rewards::config::PPM_SCALE as f64) as u128;
        let analyzer_ppm = (0.3_f64 * crate::rewards::config::PPM_SCALE as f64) as u128;
        let expected_collector =
            (total_reward as u128 * collector_ppm / crate::rewards::config::PPM_SCALE as u128)
                as u64;
        let expected_analyzer =
            (total_reward as u128 * analyzer_ppm / crate::rewards::config::PPM_SCALE as u128)
                as u64;
        (pop, total_reward, expected_collector, expected_analyzer)
    }

    /// (a) #1282: A block whose role reward metadata matches the exact computed
    /// value passes verify_role_based_rewards.
    #[tokio::test]
    async fn verify_role_based_rewards_exact_match_passes() {
        let height = 5u64;
        let (mut pop, total_reward, expected_collector, expected_analyzer) =
            build_pop_with_roles_and_rewards(height);

        let coinbase = Transaction::new_coinbase("wrf-exact", total_reward, height);
        let txs = vec![coinbase];
        let mut block = Block::new(3, Hash::default(), txs, 1, height);
        block
            .metadata
            .insert("publishing_score".to_string(), "0".to_string());
        block
            .metadata
            .insert("reward_collector".to_string(), expected_collector.to_string());
        block
            .metadata
            .insert("reward_analyzer".to_string(), expected_analyzer.to_string());

        let result = pop
            .verify_block(
                &block,
                &FxHashSet::default(),
                DEFAULT_ORACLE_QUORUM.max(1),
                &[],
            )
            .await
            .unwrap();
        assert!(
            result,
            "block with exact role reward values must pass verify_role_based_rewards"
        );
    }

    /// (b) #1282: A block whose collector reward is off by exactly 1 unit is
    /// now rejected (the old ±1 tolerance was removed).
    #[tokio::test]
    async fn verify_role_based_rewards_off_by_one_rejected() {
        let height = 5u64;
        let (mut pop, total_reward, expected_collector, expected_analyzer) =
            build_pop_with_roles_and_rewards(height);

        // Skip this test if the expected collector reward is 0 — adding 1 still
        // yields a non-zero value, but the test is most meaningful when rewards
        // are non-trivial.
        if expected_collector == 0 {
            return;
        }

        let coinbase = Transaction::new_coinbase("wrf-off-by-one", total_reward, height);
        let txs = vec![coinbase];
        let mut block = Block::new(3, Hash::default(), txs, 1, height);
        block
            .metadata
            .insert("publishing_score".to_string(), "0".to_string());
        // Inject collector reward off by exactly +1.
        block.metadata.insert(
            "reward_collector".to_string(),
            (expected_collector + 1).to_string(),
        );
        block
            .metadata
            .insert("reward_analyzer".to_string(), expected_analyzer.to_string());

        let result = pop
            .verify_block(
                &block,
                &FxHashSet::default(),
                DEFAULT_ORACLE_QUORUM.max(1),
                &[],
            )
            .await
            .unwrap();
        assert!(
            !result,
            "block with collector reward off by +1 must be rejected after #1282 tightening"
        );

        // Also test off by -1.
        if expected_collector >= 1 {
            let coinbase2 =
                Transaction::new_coinbase("wrf-off-by-one-neg", total_reward, height);
            let txs2 = vec![coinbase2];
            let mut block2 = Block::new(3, Hash::default(), txs2, 1, height);
            block2
                .metadata
                .insert("publishing_score".to_string(), "0".to_string());
            block2.metadata.insert(
                "reward_collector".to_string(),
                (expected_collector - 1).to_string(),
            );
            block2
                .metadata
                .insert("reward_analyzer".to_string(), expected_analyzer.to_string());

            let result2 = pop
                .verify_block(
                    &block2,
                    &FxHashSet::default(),
                    DEFAULT_ORACLE_QUORUM.max(1),
                    &[],
                )
                .await
                .unwrap();
            assert!(
                !result2,
                "block with collector reward off by -1 must be rejected after #1282 tightening"
            );
        }
    }

    /// (c) #1282: Confirm that apply_role_based_rewards and verify_role_based_rewards
    /// compute identical values — demonstrating the tolerance was always unnecessary.
    /// Two simulated nodes (same PoP config) must produce the same expected reward
    /// for the same block, so ±1 divergence is impossible.
    #[tokio::test]
    async fn verify_role_based_rewards_apply_and_verify_are_consistent() {
        // Test across several heights to exercise different block-time tiers.
        for height in [0u64, 1, 5, 100, 210_000, 420_000] {
            let (mut pop, total_reward, _, _) = build_pop_with_roles_and_rewards(height);

            let coinbase = Transaction::new_coinbase("wrf-consistency", total_reward, height);
            let txs = vec![coinbase];
            let mut block = Block::new(3, Hash::default(), txs, 1, height);
            block
                .metadata
                .insert("publishing_score".to_string(), "0".to_string());

            // Let apply_role_based_rewards write the canonical metadata.
            pop.apply_role_based_rewards(&mut block);

            // verify_role_based_rewards must accept the values it just wrote.
            let valid = pop.verify_role_based_rewards(&block);
            assert!(
                valid,
                "apply_role_based_rewards and verify_role_based_rewards disagree \
                 at height {height} — integer arithmetic is not deterministic (bug)"
            );
        }
    }

