    // -----------------------------------------------------------------------
    // #977: create_next_block → verify_block roundtrip symmetry
    // -----------------------------------------------------------------------

    /// Empty-liveness roundtrip: a block produced by create_next_block from an
    /// empty chain+mempool must always pass verify_block on the same instance.
    /// Guards against a mine-verify split on the liveness path.
    #[tokio::test]
    async fn create_then_verify_roundtrip_empty_liveness() {
        let config = Config::default();
        // min_publishing_score=1_000_000 forces the empty-liveness path when
        // the mempool is empty (no weather data → score=0 < threshold).
        let mut pop = ProofOfPublishing::new(1, 60, 1_000_000, 10);
        // #2523: this dev chain has no oracle ceremony. It must SAY so — a
        // block 1 that declares nothing is refused, which is the point.
        pop.declare_no_genesis_oracles();
        let chain = Arc::new(RwLock::new(Blockchain::default()));
        let mempool = Arc::new(RwLock::new(Mempool::new(&config)));

        let block = pop
            .create_next_block(chain.clone(), mempool.clone(), "wrf-roundtrip-liveness")
            .await
            .expect("create_next_block must succeed on empty chain");

        // Block is at height 1 — below TIMESTAMP_VALIDATION_ACTIVATION_HEIGHT (100_000)
        // so recent_timestamps can be empty.
        let result = pop
            .verify_block(
                &block,
                &FxHashSet::default(),
                DEFAULT_ORACLE_QUORUM.max(1),
                &[],
            )
            .await
            .expect("verify_block must not error");

        assert!(
            result,
            "empty-liveness block produced by create_next_block must pass \
             verify_block (mine-verify symmetry)"
        );
    }

